def _legacy_credential_migration_http_error(
    exc: Exception,
) -> HTTPException:
    return HTTPException(
        status_code=409,
        detail={
            "error": "legacy_credential_migration_failed",
            "message": str(exc),
            "next_action": "Manage this identity through /credentials before retrying",
        },
    )


















def _target_credential_precondition_signals(
    principals: list[dict[str, Any]],
    metadata: dict[str, Any] | None = None,
) -> dict[str, str]:
    """Derive credential readiness from secret-profile references, not identities."""
    metadata = metadata or {}
    profile_by_auth_state = {
        str(item.get("auth_state") or "").strip(): str(item.get("credential_profile") or "").strip()
        for item in principals
        if item.get("is_active", True)
        and item.get("credential_configured") is True
        and str(item.get("auth_state") or "").strip() in {"user1", "user2"}
        and str(item.get("credential_profile") or "").strip()
    }
    primary_profile = profile_by_auth_state.get("user1")
    alternate_profile = profile_by_auth_state.get("user2")
    primary_legacy = bool(metadata.get("auth") or metadata.get("credential_profile"))
    alternate_legacy = bool(metadata.get("second_user") or metadata.get("user2"))
    return {
        "primary_credentials": "configured" if primary_profile or primary_legacy else "unknown",
        "second_user_credentials": (
            "configured"
            if (primary_profile and alternate_profile and primary_profile.lower() != alternate_profile.lower()) or alternate_legacy
            else "unknown"
        ),
    }


async def _resolve_target_credential_profiles(
    conn: Any,
    target_id: uuid.UUID,
    options_payload: dict[str, Any],
) -> dict[str, Any]:
    """Construct content-free managed-profile refs for legacy compatibility.

    Managed secret values must never be copied into scan rows or Redis jobs.
    Canonical Scan, schedules, and ASM do not call this compatibility helper;
    they require explicit profile IDs during admission.
    """
    rows = await conn.fetch(
        """
        SELECT p.auth_state, cp.id AS profile_id, cp.auth_kind
        FROM target_principals p
        JOIN target_credential_profiles cp
          ON cp.target_id = p.target_id
         AND lower(cp.name) = lower(p.credential_profile)
        WHERE p.target_id = $1
          AND p.is_active = true
          AND cp.is_active = true
          AND (cp.expires_at IS NULL OR cp.expires_at > NOW())
          AND p.auth_state IN ('user1', 'user2')
        ORDER BY CASE p.auth_state WHEN 'user1' THEN 0 ELSE 1 END, p.updated_at DESC
        """,
        target_id,
    )
    selected: dict[str, dict[str, Any]] = {}
    for row in rows:
        payload = row_to_dict(row)
        auth_state = str(payload.get("auth_state") or "").strip()
        if auth_state in selected:
            continue
        selected[auth_state] = payload

    primary = selected.get("user1")
    secondary = selected.get("user2")
    if primary and secondary and str(primary.get("profile_id")) == str(secondary.get("profile_id")):
        raise HTTPException(
            status_code=409,
            detail={
                "error": "shared_principal_credential_profile",
                "message": "user1 and user2 must reference distinct managed credential profiles",
                "blocked_by": ["principal_credentials_not_distinct"],
            },
        )

    profile_refs: list[dict[str, str]] = []
    for auth_state in ("user1", "user2"):
        payload = selected.get(auth_state)
        if not payload:
            continue
        auth_kind = str(payload.get("auth_kind") or "")
        if auth_state == "user1":
            option_key = "auth_header" if auth_kind == "authorization_header" else "auth_cookies"
        else:
            option_key = "user2_header" if auth_kind == "authorization_header" else "user2_cookies"
        if options_payload.get(option_key):
            continue
        profile_refs.append({
            "auth_state": auth_state,
            "profile_id": str(payload.get("profile_id")),
            "option_key": option_key,
        })
    if profile_refs:
        options_payload["managed_credential_profiles"] = profile_refs
    return options_payload


async def _admit_generic_scan_credential_profiles(
    conn: Any,
    *,
    target_id: uuid.UUID,
    target_kind: str,
    profile_ids: Sequence[Any],
) -> list[dict[str, Any]]:
    """Resolve opaque Scan inputs to immutable, content-free profile references."""
    normalized: list[str] = []
    for value in profile_ids:
        try:
            profile_id = str(uuid.UUID(str(value or "")))
        except (TypeError, ValueError, AttributeError) as exc:
            raise HTTPException(
                status_code=422, detail="credential_profile_ids contains an invalid UUID"
            ) from exc
        normalized.append(profile_id)
    if not normalized:
        return []
    profiles = await _generic_credential_store.list_profiles(
        conn,
        target_kind=target_kind,
        target_id=target_id,
        include_inactive=True,
    )
    try:
        return admit_scan_credential_profiles(
            normalized,
            profiles,
            target_id=target_id,
            target_kind=target_kind,
        )
    except ScanCredentialError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc




















# --- Opt-in self-registration of test principals (Deep Hunt enabler, roadmap item #1) ----
# For an authorized open-signup target, mint managed principals through the app's OWN signup flow
# (a real registration -- never forged auth) so two-principal BOLA hunts and application-graph
# residue can run without a human hand-provisioning credentials. Strictly opt-in per target; the
# secrets are stored encrypted via the normal credential-profile path and never returned to a model.








def _provision_same_origin_url(target_url: str, path: Any) -> str:
    text = str(path or "")
    if not text.startswith("/") or text.startswith("//"):
        raise HTTPException(status_code=400, detail="auto_provisioning path must be an absolute same-origin path starting with /")
    joined = urllib.parse.urljoin(target_url, text)
    if urllib.parse.urlsplit(joined)[:2] != urllib.parse.urlsplit(target_url)[:2]:
        raise HTTPException(status_code=400, detail="auto_provisioning path escapes the target origin")
    return joined




async def _research_maybe_auto_provision_principals(
    target_id: Any,
    *,
    approval_receipt_id: Any,
    created_by: str | None,
    require_second_user: bool,
) -> dict[str, Any]:
    """Best-effort managed-principal bootstrap shared by episode and campaign launches."""
    target_uuid = _optional_uuid(target_id)
    async with _AUTO_PROVISION_SEMAPHORE:
        async with db_pool.acquire() as conn:
            target = await conn.fetchrow(
                "SELECT id, url, is_active, metadata_json FROM targets WHERE id=$1",
                target_uuid,
            )
            if not target or not target.get("is_active"):
                return {"action": "skipped", "reason": "target_inactive"}
            config = _auto_provisioning_config(dict(target))
            if not config.get("enabled"):
                return {"action": "skipped", "reason": "auto_provisioning_disabled"}
            principal_rows = await conn.fetch(
                """
                SELECT p.auth_state, p.credential_profile, p.is_active,
                       EXISTS (
                         SELECT 1 FROM target_credential_profiles cp
                         WHERE cp.target_id=p.target_id
                           AND lower(cp.name)=lower(p.credential_profile)
                           AND cp.is_active=true
                           AND (cp.expires_at IS NULL OR cp.expires_at > NOW())
                       ) AS credential_configured
                FROM target_principals p
                WHERE p.target_id=$1 AND p.is_active=true
                """,
                target_uuid,
            )
            signals = _target_credential_precondition_signals(
                [row_to_dict(row) for row in principal_rows]
            )
            ready = signals.get("primary_credentials") == "configured" and (
                not require_second_user
                or signals.get("second_user_credentials") == "configured"
            )
            if ready:
                return {"action": "reused", "credential_signals": signals}
            # Validate before the first outbound signup request. Episode creation validates
            # again later, but that cannot authorize an already-performed side effect.
            approval = await _validate_approval_receipt_for_action(
                conn,
                approval_receipt_id,
                target_url=str(target["url"]),
                target_id=target_uuid,
                action_name="target.principals.auto_provision",
                command="target.principals.auto_provision",
                risk_tier="credential",
                created_by=created_by,
                always_require_receipt=True,
            )
            provisioned = await _auto_provision_principals(
                conn,
                target_uuid,
                str(target["url"]),
                config,
            )
            command_result = await _record_command_result(
                conn,
                command="target.principals.auto_provision",
                status="completed",
                risk_tier="credential",
                operator_message=f"Provisioned or reused {len(provisioned)} managed test principals",
                scope_receipt_id=str((approval or {}).get("scope_receipt_id") or "") or None,
                approval_receipt_id=approval_receipt_id,
                result_json={"target_id": str(target_uuid), "principals": provisioned},
                created_by=created_by,
            )
            return {
                "action": "provisioned",
                "principals": provisioned,
                "command_result_id": command_result.get("id"),
            }


































