def _canonical_vulnerability_route(value: Any) -> str | None:
    text = str(value or "").strip()
    if not text:
        return None
    parsed = urllib.parse.urlsplit(text if "://" in text else f"https://placeholder.invalid{text if text.startswith('/') else '/' + text}")
    path = parsed.path or "/"
    path = re.sub(r"(?i)/[0-9a-f]{8}-[0-9a-f-]{27,36}(?=/|$)", "/{id}", path)
    path = re.sub(r"/[0-9]+(?=/|$)", "/{id}", path)
    path = re.sub(r"(?i)/[0-9a-f]{16,}(?=/|$)", "/{id}", path)
    path = re.sub(r"\$?\{[^/{}]+\}|:[A-Za-z_][A-Za-z0-9_]*", "{id}", path)
    path = re.sub(r"/+", "/", path)
    # An object identifier addressed via a query parameter (e.g. crAPI's /orders/all?id=<uuid>) is
    # the SAME object operation as a path-segment id. Collapse such a query id into a trailing /{id}
    # so a query-string object access matches a path-style one and does not degrade to the bare
    # collection route -- otherwise the autobind can never match a query-string BOLA lead.
    if parsed.query and "{id}" not in path and re.search(
        r"(?:^|&)(?:id|[a-z0-9_]+_id)=[^&]+", parsed.query, re.IGNORECASE
    ):
        path = path.rstrip("/") + "/{id}"
    # Normalize a trailing slash: /api/Users/ and /api/Users are the same resource. Without this the
    # inventory's slash/no-slash variants split into different routes, so a create lead, its workflow,
    # and the promotion route-binding never line up.
    path = path.rstrip("/") or "/"
    return path[:1000]


def _research_vulnerability_dimensions(family: Any, *sources: Any) -> dict[str, Any]:
    """Extract stable identity dimensions that distinguish bugs on one operation."""
    raw_family = str(family or "").strip().lower().replace("-", "_").replace(" ", "_")
    canonical_family = family_proof.canonical_family(raw_family)
    parameters: set[str] = set()
    fields: set[str] = set()
    invariants: set[str] = set()
    predicates: set[str] = set()
    roles: set[str] = set()
    tenants: set[str] = set()
    locations: set[str] = set()
    variants: set[str] = set()

    def _add(target: set[str], value: Any) -> None:
        values: list[Any]
        if isinstance(value, dict):
            values = list(value.keys())
        elif isinstance(value, (list, tuple, set)):
            values = list(value)
        else:
            values = [value]
        for item in values:
            text = str(item or "").strip().lower()
            if text:
                target.add(text[:160])

    for source in sources:
        if not isinstance(source, dict):
            continue
        nested_sources = [source]
        for key in (
            "dedupe_dimensions", "canonical_vulnerability_dimensions",
            "metadata_json", "endpoint_hint",
        ):
            if isinstance(source.get(key), dict):
                nested_sources.append(source[key])
        for item in nested_sources:
            for key in ("parameter", "param", "parameter_name", "object_key", "object_id_key"):
                _add(parameters, item.get(key))
            for key in ("object_parameters", "query_keys"):
                _add(parameters, item.get(key))
            if not isinstance(item.get("parameters"), dict):
                _add(parameters, item.get("parameters"))
            for key in ("field", "field_name", "fields", "submitted_fields", "request_fields"):
                _add(fields, item.get(key))
            for key in ("json_body", "form_body"):
                _add(fields, item.get(key))
            if isinstance(item.get("query"), dict):
                _add(parameters, item["query"])
            for key in ("invariant_contract_id", "invariant_id", "invariants", "contract_kind", "operator"):
                _add(invariants, item.get(key))
            for key in ("predicate", "predicates", "assertion_predicates"):
                _add(predicates, item.get(key))
            for key in ("role", "roles", "subject_role", "required_role"):
                _add(roles, item.get(key))
            for key in ("tenant", "tenants", "tenant_id"):
                _add(tenants, item.get(key))
            for key in ("location", "locations", "injection_point", "parameter_location"):
                _add(locations, item.get(key))
            _add(variants, item.get("variant"))

    dimensions: dict[str, Any] = {}
    if canonical_family == "injection":
        if raw_family and raw_family != "injection":
            dimensions["variant"] = raw_family
        elif variants:
            dimensions["variant"] = sorted(variants)[0]
        if parameters:
            dimensions["parameters"] = sorted(parameters)
        if locations:
            dimensions["locations"] = sorted(locations)
    elif canonical_family == "bola":
        if parameters:
            dimensions["object_parameters"] = sorted(parameters)
        if tenants:
            dimensions["tenants"] = sorted(tenants)
    elif canonical_family == "mass_assignment":
        if fields:
            dimensions["fields"] = sorted(fields)
    elif canonical_family in {"field_constraint", "workflow"}:
        if fields:
            dimensions["fields"] = sorted(fields)
        if invariants:
            dimensions["invariants"] = sorted(invariants)
        if predicates:
            dimensions["predicates"] = sorted(predicates)
    elif canonical_family == "access_control":
        if invariants:
            dimensions["invariants"] = sorted(invariants)
        if predicates:
            dimensions["predicates"] = sorted(predicates)
        if roles:
            dimensions["roles"] = sorted(roles)
        if tenants:
            dimensions["tenants"] = sorted(tenants)
    return dimensions


def _canonical_vulnerability_key(
    *, family: Any, route: Any, method: Any = None, dimensions: Any = None,
) -> str | None:
    canonical_family = family_proof.canonical_family(family)
    canonical_route = _canonical_vulnerability_route(route)
    if not canonical_family or not canonical_route:
        return None
    # Method is part of the vulnerability identity: GET vs DELETE on the same object route are
    # distinct operations and must not collapse to one novelty key. '*' when the caller has no
    # method, and '*' only matches '*' (conservative -- an unknown method never suppresses a known one).
    canonical_method = str(method or "").strip().upper() or "*"
    canonical_dimensions = _research_vulnerability_dimensions(
        family,
        dimensions if isinstance(dimensions, dict) else {},
    )
    return hashlib.sha256(
        (
            f"vulnerability:v3|{canonical_family}|{canonical_method}|{canonical_route}|"
            + json.dumps(canonical_dimensions, sort_keys=True, separators=(",", ":"))
        ).encode()
    ).hexdigest()


def _canonical_coverage_key(*, family: Any, route: Any, method: Any = None) -> str | None:
    """Coarse family+method+route coverage key (dimension-less).

    The exact v3 vulnerability key folds in fine-grained dimensions, so a DAST finding and a
    residue lead on the SAME endpoint hash differently whenever the lead's sparse dimensions can't
    reproduce the finding's enriched ones — which lets already-owned BOLA leads slip onto the hunt
    board and monopolize it. This coarse key deliberately drops dimensions so "same family + method
    + route as an existing finding" is enough to recognise coverage at ranking time. The precise v3
    key still guards dispatch, so this only affects board ordering, never promotion.
    """
    canonical_family = family_proof.canonical_family(family)
    canonical_route = _canonical_vulnerability_route(route)
    if not canonical_family or not canonical_route:
        return None
    canonical_method = str(method or "").strip().upper() or "*"
    return hashlib.sha256(
        f"coverage:v1|{canonical_family}|{canonical_method}|{canonical_route}".encode()
    ).hexdigest()


def _finding_family_route_method(value: Any) -> tuple[dict[str, Any], Any, Any, Any, dict[str, Any], Any, Any]:
    """Extract (finding, family, route, method, dedupe_dimensions, evidence, request) from a finding.

    Shared by the exact vulnerability key and the coarse coverage key so both agree on identity —
    in particular the smart_bola/smart_authz method fallback below, without which a covered BOLA
    finding's method would be unknown and never match a GET residue lead's coverage key.
    """
    finding = row_to_dict(value) if value is not None and not isinstance(value, dict) else dict(value or {})
    evidence = _decode_json_value(finding.get("evidence")) or {}
    family = _research_finding_family(finding)
    route = finding.get("url")
    method = finding.get("method")
    dedupe_dimensions: dict[str, Any] = {}
    if isinstance(evidence, dict):
        dedupe_dimensions = evidence.get("dedupe_dimensions") if isinstance(evidence.get("dedupe_dimensions"), dict) else {}
        route = dedupe_dimensions.get("route") or evidence.get("route") or evidence.get("path") or route
        method = dedupe_dimensions.get("method") or evidence.get("method") or method
        # Backward compatibility for SUSPECTED rows written before route/method were persisted at the
        # top level. Only this finding's cited tool evidence is stored in tool_evidence.
        if not method or not route:
            legacy_operations: list[tuple[str, str]] = []
            for item in evidence.get("tool_evidence") or []:
                if not isinstance(item, dict):
                    continue
                try:
                    payload = json.loads(str(item.get("content") or "{}"))
                except (TypeError, ValueError):
                    continue
                request_view = payload.get("request") if isinstance(payload, dict) else None
                if not isinstance(request_view, dict):
                    continue
                candidate_route = str(request_view.get("path") or "").strip()
                candidate_method = str(request_view.get("method") or "").strip().upper()
                if candidate_route and candidate_method:
                    operation = (candidate_route, candidate_method)
                    if operation not in legacy_operations:
                        legacy_operations.append(operation)
            # Never bind an old multi-request finding to whichever control happened to be cited
            # first. Only an unambiguous legacy operation is safe to auto-verify.
            if len(legacy_operations) == 1:
                route = route or legacy_operations[0][0]
                method = method or legacy_operations[0][1]
        if not method:
            consumer = str(evidence.get("consumer_endpoint") or "").strip()
            consumer_match = re.match(r"^(GET|POST|PUT|PATCH|DELETE|HEAD|OPTIONS)\s+", consumer, re.IGNORECASE)
            if consumer_match:
                method = consumer_match.group(1)
    request = _decode_json_value(finding.get("request"))
    if not method and isinstance(request, dict):
        method = request.get("method")
    if not method and isinstance(request, str):
        request_match = re.match(r"^\s*(GET|POST|PUT|PATCH|DELETE|HEAD|OPTIONS)\s+", request, re.IGNORECASE)
        if request_match:
            method = request_match.group(1)
    if not method:
        title_match = re.search(
            r"\b(GET|POST|PUT|PATCH|DELETE|HEAD|OPTIONS)\b",
            str(finding.get("title") or ""),
            re.IGNORECASE,
        )
        if title_match:
            method = title_match.group(1)
    if not method and str(finding.get("tool") or "").lower() in {"smart_bola", "smart_authz"}:
        # Backward compatibility for findings written before those deterministic GET replays stamped
        # their method into evidence. Write replays have always carried PATCH; the remaining historic
        # cross-principal/unauthenticated smart BOLA findings are GET probes by construction.
        proof_type = str((evidence or {}).get("proof_type") or "").lower()
        if "write" not in proof_type:
            method = "GET"
    return finding, family, route, method, dedupe_dimensions, evidence, request


def _finding_vulnerability_key(value: Any) -> str | None:
    finding, family, route, method, dedupe_dimensions, evidence, request = _finding_family_route_method(value)
    computed = _canonical_vulnerability_key(
        family=family,
        route=route,
        method=method,
        dimensions=_research_vulnerability_dimensions(
            family,
            dedupe_dimensions if isinstance(evidence, dict) else {},
            evidence,
            finding,
            request if isinstance(request, dict) else {},
        ),
    )
    if computed:
        return computed
    # Keep opaque legacy/manual evidence attributable only when structured family/route data is absent.
    # Recompute whenever possible so legacy explicit hashes cannot bypass the v3 dimensional key.
    explicit = str((evidence or {}).get("canonical_vulnerability_key") or "").strip().lower()
    return explicit if re.fullmatch(r"[a-f0-9]{64}", explicit) else None


def _finding_coverage_key(value: Any) -> str | None:
    _finding, family, route, method, _dims, _evidence, _request = _finding_family_route_method(value)
    return _canonical_coverage_key(family=family, route=route, method=method)


RESEARCH_SURFACE_MIN_UNIQUE_ROUTES = 20
RESEARCH_SURFACE_MIN_AUTHENTICATED_ROUTES = 5
RESEARCH_SURFACE_MIN_EXECUTABLE_ROUTES = 1
RESEARCH_PREFLIGHT_MAX_ATTEMPTS = 2
RESEARCH_PREFLIGHT_CLAIM_TTL_SECONDS = 120
RESEARCH_PREFLIGHT_TRANSIENT_RETRY_SECONDS = 30
RESEARCH_SEMANTIC_FALSIFICATION_LIMIT = 3
RESEARCH_RECON_ACTION_CAP = 6
RESEARCH_AUTOPILOT_LEASE_SECONDS = 30
RESEARCH_AUTOPILOT_HEARTBEAT_SECONDS = 10
RESEARCH_ASM_FAMILIES = frozenset({"sqli", "xss", "auth", "bola"})
RESEARCH_CAMPAIGN_FAMILIES = frozenset({
    *RESEARCH_ASM_FAMILIES,
    "mass_assignment",
    "workflow",
    "data_exposure",
    "access_control",
    "field_constraint",
})
RESEARCH_DEFAULT_CAMPAIGN_FAMILIES = (
    "sqli", "xss", "auth", "bola", "mass_assignment", "workflow",
    "data_exposure", "access_control", "field_constraint",
)
RESEARCH_PRIMARY_CREDENTIAL_FAMILIES = frozenset({
    "auth", "bola", "mass_assignment", "workflow", "data_exposure",
    "access_control", "field_constraint",
})
RESEARCH_SECOND_USER_FAMILIES = frozenset({"bola"})


def _research_preflight_claim_is_stale(config: Any, *, now: datetime | None = None) -> bool:
    payload = config if isinstance(config, dict) else {}
    if str(payload.get("preflight_state") or "") != "queueing":
        return False
    raw_started = str(payload.get("preflight_started_at") or "").strip()
    if not raw_started:
        return True
    try:
        started = datetime.fromisoformat(raw_started.replace("Z", "+00:00"))
        if started.tzinfo is None:
            started = started.replace(tzinfo=timezone.utc)
    except ValueError:
        return True
    current = now or datetime.now(timezone.utc)
    return (current - started).total_seconds() >= RESEARCH_PREFLIGHT_CLAIM_TTL_SECONDS


def _research_subtract_cost(used: Any, cost: Any) -> dict[str, int]:
    used_map = _research_normalize_budget_used(used)
    cost_map = _research_normalize_budget_used(cost)
    return {
        key: max(0, int(used_map.get(key) or 0) - int(cost_map.get(key) or 0))
        for key in RESEARCH_BUDGET_KEYS
    }


def _research_preflight_error_is_transient(exc: Exception) -> bool:
    detail = getattr(exc, "detail", None)
    error = str(detail.get("error") or "") if isinstance(detail, dict) else ""
    text = f"{error} {detail if detail is not None else exc}".lower()
    return any(token in text for token in (
        "workers_not_confirmed_current",
        "worker_fleet_not_current",
        "pending worker",
        "stale worker",
        "build-current",
    ))


def _research_family_readiness_requirements(families: set[str], *, gated: bool) -> dict[str, Any]:
    """Derive launch prerequisites from the selected families, not the campaign tier."""
    primary = bool(gated and families.intersection(RESEARCH_PRIMARY_CREDENTIAL_FAMILIES))
    second_user = bool(gated and families.intersection(RESEARCH_SECOND_USER_FAMILIES))
    minimum_routes = (
        RESEARCH_SURFACE_MIN_UNIQUE_ROUTES if second_user
        else RESEARCH_SURFACE_MIN_AUTHENTICATED_ROUTES if primary
        else RESEARCH_SURFACE_MIN_EXECUTABLE_ROUTES
    )
    return {
        "primary_credentials": primary,
        "second_user": second_user,
        "authenticated_preflight": primary,
        "unique_routes": minimum_routes,
        "authenticated_routes": RESEARCH_SURFACE_MIN_AUTHENTICATED_ROUTES if primary else 0,
        "executable_routes": RESEARCH_SURFACE_MIN_EXECUTABLE_ROUTES if gated else 0,
    }


def _research_intensity_campaign_families(intensity: Any) -> tuple[str, ...]:
    """Families with a real executable proof path at an intensity's risk ceiling."""
    profile = RESEARCH_LAUNCH_PROFILES.get(str(intensity or ""), {})
    if str(profile.get("max_risk_tier") or "") == "credential":
        return RESEARCH_DEFAULT_CAMPAIGN_FAMILIES
    if str(profile.get("execution_mode") or "") == "gated":
        return tuple(sorted(RESEARCH_ASM_FAMILIES))
    return ()


def _validate_research_intensity_families(intensity: Any, families: list[str]) -> list[str]:
    normalized = list(dict.fromkeys(
        str(item).strip().lower() for item in families if str(item).strip()
    ))
    supported = set(_research_intensity_campaign_families(intensity))
    unavailable = sorted(set(normalized) - supported)
    if unavailable:
        raise HTTPException(
            status_code=400,
            detail=(
                f"Families require a higher research intensity: {', '.join(unavailable)}. "
                "Use deep_hunt for credential-bound workflow proof."
            ),
        )
    return normalized


def _research_hypothesis_route(hypothesis: dict[str, Any]) -> str | None:
    metadata = hypothesis.get("metadata_json") if isinstance(hypothesis.get("metadata_json"), dict) else {}
    metadata_dimensions = metadata.get("dedupe_dimensions") if isinstance(metadata.get("dedupe_dimensions"), dict) else {}
    direct_dimensions = hypothesis.get("dedupe_dimensions") if isinstance(hypothesis.get("dedupe_dimensions"), dict) else {}
    dimensions = {**metadata_dimensions, **direct_dimensions}
    next_action = hypothesis.get("next_test_action") if isinstance(hypothesis.get("next_test_action"), dict) else {}
    parameters = next_action.get("parameters") if isinstance(next_action.get("parameters"), dict) else {}
    return _canonical_vulnerability_route(
        dimensions.get("route")
        or metadata.get("route")
        or parameters.get("route")
        or hypothesis.get("route")
    )


def _research_hypothesis_vulnerability_key(hypothesis: dict[str, Any]) -> str | None:
    metadata = hypothesis.get("metadata_json") if isinstance(hypothesis.get("metadata_json"), dict) else {}
    metadata_dimensions = metadata.get("dedupe_dimensions") if isinstance(metadata.get("dedupe_dimensions"), dict) else {}
    direct_dimensions = hypothesis.get("dedupe_dimensions") if isinstance(hypothesis.get("dedupe_dimensions"), dict) else {}
    dimensions = {**metadata_dimensions, **direct_dimensions}
    return _canonical_vulnerability_key(
        family=hypothesis.get("family"),
        route=_research_hypothesis_route(hypothesis),
        method=dimensions.get("method") or metadata.get("method"),
        dimensions=_research_vulnerability_dimensions(
            hypothesis.get("family"),
            dimensions,
            metadata,
            hypothesis.get("next_test_action") if isinstance(hypothesis.get("next_test_action"), dict) else {},
        ),
    )


def _research_hypothesis_coverage_key(hypothesis: dict[str, Any]) -> str | None:
    """Coarse family+method+route coverage key for a hunt lead (see _canonical_coverage_key)."""
    metadata = hypothesis.get("metadata_json") if isinstance(hypothesis.get("metadata_json"), dict) else {}
    metadata_dimensions = metadata.get("dedupe_dimensions") if isinstance(metadata.get("dedupe_dimensions"), dict) else {}
    direct_dimensions = hypothesis.get("dedupe_dimensions") if isinstance(hypothesis.get("dedupe_dimensions"), dict) else {}
    dimensions = {**metadata_dimensions, **direct_dimensions}
    return _canonical_coverage_key(
        family=hypothesis.get("family"),
        route=_research_hypothesis_route(hypothesis),
        method=dimensions.get("method") or metadata.get("method"),
    )


def _research_exhausted_families(
    candidates: list[dict[str, Any]], known_vulnerability_keys: set[str] | None,
) -> list[str]:
    """Families whose every candidate has the same exact identity as an owned finding.

    Coarse operation coverage is deliberately insufficient here because one route
    may contain distinct parameter, field, role, tenant, or invariant failures.
    """
    known = known_vulnerability_keys or set()
    if not known:
        return []
    by_family: dict[str, list[bool]] = {}
    for item in candidates:
        if not isinstance(item, dict):
            continue
        family = family_proof.canonical_family(item.get("family"))
        if not family:
            continue
        identity = _research_hypothesis_vulnerability_key(item)
        by_family.setdefault(family, []).append(bool(identity and identity in known))
    return sorted(family for family, flags in by_family.items() if flags and all(flags))


def _research_action_semantic_dimension(action: dict[str, Any]) -> str | None:
    """Collapse volatile ids/prose while retaining method, payload, principal, and assertions."""
    command = str(action.get("command") or "").strip()
    parameters = action.get("parameters") if isinstance(action.get("parameters"), dict) else {}
    if command not in {"experiment.workflow", "experiment.http_diff"}:
        return None
    routes: set[str] = set()
    for step in parameters.get("steps") or []:
        if not isinstance(step, dict):
            continue
        route = _canonical_vulnerability_route(step.get("path") or step.get("route"))
        if route:
            routes.add(route)
    direct_route = _canonical_vulnerability_route(parameters.get("route"))
    if direct_route:
        routes.add(direct_route)
    if not routes:
        return None
    comparable = _research_action_dedupe_comparable(action)
    material = {
        "version": "semantic-experiment-v2",
        "routes": sorted(routes),
        "experiment": comparable,
    }
    return _research_canonical_hash(material)


def _research_action_vulnerability_keys(action: dict[str, Any]) -> set[str]:
    command = str(action.get("command") or "").strip()
    parameters = action.get("parameters") if isinstance(action.get("parameters"), dict) else {}
    if command not in {"experiment.workflow", "experiment.http_diff"}:
        return set()
    family = family_proof.canonical_family(parameters.get("proof_family") or command)
    steps_by_label: dict[str, dict[str, Any]] = {}
    for step in parameters.get("steps") or []:
        if isinstance(step, dict):
            label = str(step.get("label") or step.get("id") or "").strip()
            if label:
                steps_by_label[label] = step
    # Only the step(s) an assertion actually targets are the vulnerability under test. Setup, auth,
    # producer and cleanup steps must not make an entire workflow look 'already covered' just because
    # they touch a route that carries a known finding (the reported over-block).
    target_labels: set[str] = set()
    for assertion in parameters.get("assertions") or []:
        if not isinstance(assertion, dict):
            continue
        for ref_key in ("step", "candidate"):
            ref = str(assertion.get(ref_key) or "").strip()
            if ref:
                target_labels.add(ref)
        for ref in assertion.get("steps") or []:
            text = str(ref or "").strip()
            if text:
                target_labels.add(text)
    keys: set[str] = set()

    assertion_predicates = sorted({
        str(assertion.get("predicate") or "").strip().lower()
        for assertion in parameters.get("assertions") or []
        if isinstance(assertion, dict) and assertion.get("predicate")
    })

    def _add(route: Any, method: Any, step: dict[str, Any] | None = None) -> None:
        # A concrete candidate matches only the same concrete method. Unknown-method candidates use
        # the wildcard key, but a methodless historic finding must never suppress every known method.
        key = _canonical_vulnerability_key(
            family=parameters.get("proof_family") or family,
            route=route,
            method=method,
            dimensions=_research_vulnerability_dimensions(
                parameters.get("proof_family") or family,
                parameters,
                step or {},
                {"assertion_predicates": assertion_predicates},
            ),
        )
        if key:
            keys.add(key)

    for label in target_labels:
        step = steps_by_label.get(label)
        if step:
            _add(step.get("path") or step.get("route"), step.get("method"), step)
    _add(parameters.get("route"), parameters.get("method"), parameters)
    return keys


RESEARCH_RECON_COMMANDS = frozenset({
    "asm.gaps",
    "asm.recon",
    "target.get",
    "target.graph",
    "target.principal_matrix",
    "hypothesis.list",
    "hypothesis.generate_from_graph",
})


RESEARCH_EXPERIMENT_OUTCOMES = frozenset({
    "verified", "refuted", "supported_unverified", "inconclusive", "blocked",
})
RESEARCH_INCONCLUSIVE_ACTUATOR_LIMIT = 3


def _research_experiment_failure_detail(result_json: Any) -> tuple[str | None, list[str]]:
    payload = result_json if isinstance(result_json, dict) else {}
    workflow = payload.get("workflow") if isinstance(payload.get("workflow"), dict) else {}
    replay = payload.get("replay") if isinstance(payload.get("replay"), dict) else {}
    observations = [
        *(workflow.get("observations") or []),
        *(payload.get("observations") or []),
        *(replay.get("observations") or []),
    ]
    failed_predicates = sorted({
        str(assertion.get("predicate") or assertion.get("type") or "")[:120]
        for source in (workflow, payload, replay)
        for assertion in (source.get("assertion_results") or [])
        if isinstance(assertion, dict) and assertion.get("passed") is False
        and (assertion.get("predicate") or assertion.get("type"))
    })
    reason = " ".join(str(value or "") for value in (
        payload.get("failure_reason"),
        replay.get("replay_blocked_reason"),
        (payload.get("family_proof") or {}).get("reason")
        if isinstance(payload.get("family_proof"), dict) else "",
    )).lower()
    if "restor" in reason or "before_after_state" in failed_predicates:
        return "restoration_failed", failed_predicates
    if "baseline" in reason:
        return "baseline_failed", failed_predicates
    if "privileg" in reason or "elevation" in reason:
        return "no_privilege_elevation", failed_predicates
    for observation in observations:
        if not isinstance(observation, dict):
            continue
        response = observation.get("response") if isinstance(observation.get("response"), dict) else {}
        status = response.get("status")
        if observation.get("error"):
            return "transport_or_runtime_error", failed_predicates
        if isinstance(status, int) and status >= 400:
            checkpoint = str(observation.get("checkpoint") or "")
            return (
                "baseline_request_failed" if checkpoint == "before"
                else "mutation_request_failed" if checkpoint == "mutation"
                else "workflow_step_failed"
            ), failed_predicates
    if failed_predicates:
        return "proof_predicates_failed", failed_predicates
    return ("proof_evidence_missing" if reason else None), failed_predicates


def _research_experiment_outcome(action: Any, command_result: Any) -> dict[str, Any] | None:
    """Normalize a completed experiment into a scientific outcome.

    Absence of a finding is not refutation.  Only a deterministic family-proof
    ``refuted`` verdict counts as falsification; transport/runtime failures and
    missing proof stay visible as blocked/inconclusive.
    """
    action_payload = action if isinstance(action, dict) else _decode_json_value(action) or {}
    command = str(action_payload.get("command") or "")
    if command not in {"experiment.http_diff", "experiment.workflow"}:
        return None
    result = command_result if isinstance(command_result, dict) else row_to_dict(command_result)
    result_json = _decode_json_value(result.get("result_json")) or {}
    proof = result_json.get("family_proof") if isinstance(result_json.get("family_proof"), dict) else {}
    if not proof:
        nested = result_json.get("workflow") if isinstance(result_json.get("workflow"), dict) else {}
        proof = nested.get("family_proof") if isinstance(nested.get("family_proof"), dict) else {}
    verdict = str(proof.get("verdict") or "").strip().lower()
    finding_ids = _decode_json_value(result.get("finding_ids")) or []
    if finding_ids or verdict == "verified":
        outcome = "verified"
    elif verdict in RESEARCH_EXPERIMENT_OUTCOMES:
        outcome = verdict
    else:
        status = str(result.get("command_status") or result.get("status") or "").strip().lower()
        proof_state = str(
            result_json.get("proof_state")
            or (result_json.get("experiment") or {}).get("proof_state")
            or ""
        ).strip().lower()
        if status in {"blocked", "approval_required", "failed", "cancelled", "error", "partial"}:
            outcome = "blocked"
        elif proof_state in {"supported", "supported_unverified", "likely_vulnerable"}:
            outcome = "supported_unverified"
        else:
            outcome = "inconclusive"
    failure_class, failed_predicates = _research_experiment_failure_detail(result_json)
    if outcome == "blocked" and not failure_class:
        failure_class = "dispatch_or_policy_blocked"
    elif outcome == "inconclusive" and not failure_class:
        failure_class = "proof_evidence_missing"
    return {
        "outcome": outcome,
        "reason": str(
            proof.get("reason")
            or result_json.get("failure_reason")
            or result.get("command_status")
            or result.get("status")
            or ""
        )[:500],
        "family": str(proof.get("family") or (action_payload.get("parameters") or {}).get("proof_family") or "")[:80],
        "deterministic_refutation": outcome == "refuted" and bool(proof.get("refuted_by")),
        "failure_class": failure_class,
        "failed_predicates": failed_predicates[:16],
    }


async def _record_research_hypothesis_outcome(
    conn: Any,
    *,
    decision_id: Any,
    command_result: Any,
) -> dict[str, Any] | None:
    """Persist experiment learning on the bound hypothesis exactly once."""
    decision = await conn.fetchrow(
        "SELECT id, hypothesis_id, action FROM research_decisions WHERE id=$1",
        _optional_uuid(decision_id),
    )
    if not decision or not decision.get("hypothesis_id"):
        return None
    outcome = _research_experiment_outcome(decision.get("action"), command_result)
    if not outcome:
        return None
    hypothesis = await conn.fetchrow(
        "SELECT id, status, metadata_json FROM hypotheses WHERE id=$1 FOR UPDATE",
        decision["hypothesis_id"],
    )
    if not hypothesis:
        return None
    metadata = _decode_json_value(hypothesis.get("metadata_json")) or {}
    history = metadata.get("research_outcomes") if isinstance(metadata.get("research_outcomes"), list) else []
    decision_key = str(decision["id"])
    if any(str(item.get("decision_id") or "") == decision_key for item in history if isinstance(item, dict)):
        return outcome
    attempts = int(metadata.get("attempt_count") or 0) + 1
    failures = int(metadata.get("prior_failures") or 0)
    if outcome["outcome"] in {"inconclusive", "blocked"}:
        failures += 1
    metadata.update({
        "attempt_count": attempts,
        "prior_failures": failures,
        "last_outcome": outcome["outcome"],
        "last_outcome_reason": outcome.get("reason"),
        "research_outcomes": [
            *history,
            {
                **outcome,
                "decision_id": decision_key,
                "recorded_at": datetime.now(timezone.utc).isoformat(),
            },
        ][-20:],
    })
    current_status = str(hypothesis.get("status") or "open")
    next_status = current_status
    terminal_reason = None
    if current_status not in {"promoted", "dead", "exhausted"}:
        if outcome["outcome"] == "refuted" and outcome.get("deterministic_refutation"):
            next_status = "refuted"
            terminal_reason = "deterministic_experiment_refutation"
        elif outcome["outcome"] in {"verified", "supported_unverified"}:
            # Verified promotion normally sets promoted in the workflow
            # transaction.  Preserve that terminal status if it already did.
            next_status = "supported"
        elif outcome["outcome"] in {"inconclusive", "blocked"}:
            same_failure_count = sum(
                1
                for item in [*history, outcome]
                if isinstance(item, dict)
                and item.get("outcome") in {"inconclusive", "blocked"}
                and item.get("failure_class") == outcome.get("failure_class")
            )
            if same_failure_count >= RESEARCH_INCONCLUSIVE_ACTUATOR_LIMIT:
                next_status = "exhausted"
                terminal_reason = (
                    f"experiment_actuator_exhausted:{outcome.get('failure_class') or 'unknown'}"
                )
            else:
                next_status = "open"
    await conn.execute(
        """
        UPDATE hypotheses
        SET status=$2, metadata_json=$3::jsonb,
            terminal_reason=COALESCE($4, terminal_reason),
            version=version+1, updated_at=NOW()
        WHERE id=$1
        """,
        hypothesis["id"],
        next_status,
        json.dumps(metadata),
        terminal_reason,
    )
    return outcome


async def _research_campaign_exhaustion_snapshot(
    conn: Any,
    episode_id: Any,
    campaign_id: Any = None,
) -> dict[str, Any]:
    rows = await conn.fetch(
        """
        SELECT rd.action, rd.status, cr.id AS command_result_id, cr.status AS command_status,
               cr.finding_ids, cr.result_json
        FROM research_decisions rd
        JOIN research_episodes re ON re.id=rd.episode_id
        LEFT JOIN command_results cr ON cr.id=rd.command_result_id
        WHERE rd.episode_id=$1 OR ($2::uuid IS NOT NULL AND re.campaign_id=$2)
        ORDER BY rd.created_at ASC
        LIMIT 2000
        """,
        _optional_uuid(episode_id),
        _optional_uuid(campaign_id),
    )
    falsifications: dict[str, int] = {}
    inconclusive_actuators: dict[str, int] = {}
    recon_actions = 0
    experiments = 0
    for row in rows:
        action = _decode_json_value(row.get("action")) or {}
        command = str(action.get("command") or "")
        if command in RESEARCH_RECON_COMMANDS and str(row.get("status") or "") in {
            "accepted", "dispatching", "completed", "blocked",
        }:
            recon_actions += 1
        dimension = _research_action_semantic_dimension(action)
        if not dimension or not row.get("command_result_id") or str(row.get("status") or "") != "completed":
            continue
        experiments += 1
        outcome = _research_experiment_outcome(action, row)
        if outcome and outcome.get("deterministic_refutation"):
            falsifications[dimension] = falsifications.get(dimension, 0) + 1
        elif outcome and outcome.get("outcome") in {"inconclusive", "blocked"}:
            failure_class = str(outcome.get("failure_class") or "unknown")
            actuator = f"{dimension}:{failure_class}"
            inconclusive_actuators[actuator] = inconclusive_actuators.get(actuator, 0) + 1
    return {
        "experiments": experiments,
        "recon_actions": recon_actions,
        "falsification_counts": falsifications,
        "inconclusive_actuator_counts": inconclusive_actuators,
        "exhausted_inconclusive_actuators": sorted(
            actuator
            for actuator, count in inconclusive_actuators.items()
            if count >= RESEARCH_INCONCLUSIVE_ACTUATOR_LIMIT
        ),
        "exhausted_dimensions": sorted(
            dimension
            for dimension, count in falsifications.items()
            if count >= RESEARCH_SEMANTIC_FALSIFICATION_LIMIT
        ),
        "semantic_falsification_limit": RESEARCH_SEMANTIC_FALSIFICATION_LIMIT,
        "inconclusive_actuator_limit": RESEARCH_INCONCLUSIVE_ACTUATOR_LIMIT,
        "recon_action_cap": RESEARCH_RECON_ACTION_CAP,
    }


async def _research_semantic_policy_violations(
    conn: Any,
    episode: dict[str, Any],
    action: dict[str, Any],
) -> list[str]:
    snapshot = await _research_campaign_exhaustion_snapshot(
        conn,
        episode.get("id"),
        episode.get("campaign_id"),
    )
    errors: list[str] = []
    command = str(action.get("command") or "")
    if command in RESEARCH_RECON_COMMANDS and int(snapshot.get("recon_actions") or 0) >= RESEARCH_RECON_ACTION_CAP:
        errors.append("campaign_recon_cap_reached")
    dimension = _research_action_semantic_dimension(action)
    if dimension and int((snapshot.get("falsification_counts") or {}).get(dimension) or 0) >= RESEARCH_SEMANTIC_FALSIFICATION_LIMIT:
        errors.append(f"semantic_dimension_exhausted:{dimension}")
    if dimension and any(
        str(actuator).startswith(f"{dimension}:")
        for actuator in snapshot.get("exhausted_inconclusive_actuators") or []
    ):
        errors.append(f"experiment_actuator_exhausted:{dimension}")
    if _research_action_vulnerability_keys(action) & await _research_known_vulnerability_keys(conn, episode.get("target_id")):
        errors.append("known_vulnerability_already_covered")
    return errors


async def _research_known_vulnerability_keys(conn: Any, target_id: Any) -> set[str]:
    rows = await conn.fetch(
        """
        SELECT tool, cwe, title, url, evidence, request
        FROM findings
        WHERE target_id=$1
          AND status IN ('active','resolved','accepted_risk')
        ORDER BY last_seen_at DESC
        LIMIT 2000
        """,
        _optional_uuid(target_id),
    )
    return {
        key
        for key in (_finding_vulnerability_key(row) for row in rows)
        if key
    }


async def _research_known_coverage_keys(conn: Any, target_id: Any) -> set[str]:
    """Coarse family+method+route coverage keys of already-owned findings (see _canonical_coverage_key).

    Used only to keep already-found vulnerabilities off the hunt board so net-new families surface;
    dispatch still checks the exact v3 key via _research_known_vulnerability_keys.
    """
    rows = await conn.fetch(
        """
        SELECT tool, cwe, title, url, evidence, request
        FROM findings
        WHERE target_id=$1
          AND status IN ('active','resolved','accepted_risk')
        ORDER BY last_seen_at DESC
        LIMIT 2000
        """,
        _optional_uuid(target_id),
    )
    return {
        key
        for key in (_finding_coverage_key(row) for row in rows)
        if key
    }


async def _research_net_new_finding_count(
    conn: Any,
    target_id: Any,
    *,
    campaign_id: Any = None,
    tool: str = "autonomous_workflow",
    verdict: str | None = "exploited",
) -> int:
    """Count distinct exact findings from ``tool`` not owned by another tool.

    When a campaign is supplied, only findings carrying that campaign's durable
    research provenance count. This prevents a new campaign inheriting credit
    from earlier target hunts.
    """
    rows = await conn.fetch(
        """
        SELECT tool, cwe, title, url, evidence, request, last_verification_verdict
        FROM findings
        WHERE target_id=$1 AND status IN ('active','resolved','accepted_risk')
        """,
        _optional_uuid(target_id),
    )
    other_keys: set[str] = set()
    tool_rows: list[dict[str, Any]] = []
    campaign_text = str(campaign_id or "").strip()
    for row in rows:
        finding = row_to_dict(row)
        if str(finding.get("tool") or "") == tool:
            if campaign_text:
                evidence = _decode_json_value(finding.get("evidence")) or {}
                provenance_items = (
                    evidence.get("research_provenance_history")
                    if isinstance(evidence, dict)
                    and isinstance(evidence.get("research_provenance_history"), list)
                    else []
                )
                if isinstance(evidence, dict) and isinstance(evidence.get("research_provenance"), dict):
                    provenance_items = [*provenance_items, evidence["research_provenance"]]
                if not any(
                    isinstance(item, dict)
                    and str(item.get("campaign_id") or "") == campaign_text
                    for item in provenance_items
                ):
                    continue
            tool_rows.append(finding)
        else:
            key = _finding_vulnerability_key(finding)
            if key:
                other_keys.add(key)
    net_new_keys: set[str] = set()
    for finding in tool_rows:
        if verdict and str(finding.get("last_verification_verdict") or "") != verdict:
            continue
        key = _finding_vulnerability_key(finding)
        if key and key not in other_keys:
            net_new_keys.add(key)
    return len(net_new_keys)


async def _research_campaign_readiness(conn: Any, campaign: Any) -> dict[str, Any]:
    """Fail-closed launch gate for authenticated autonomous hunting."""
    payload = row_to_dict(campaign)
    metadata = _decode_json_value(payload.get("metadata_json")) or {}
    config = metadata.get("autonomous_research") if isinstance(metadata.get("autonomous_research"), dict) else {}
    target_id = _optional_uuid(payload.get("target_id"))
    intensity = str(config.get("intensity") or "deep_hunt")
    gated = RESEARCH_LAUNCH_PROFILES.get(intensity, {}).get("execution_mode") == "gated"
    families = {str(item).strip().lower() for item in config.get("allowed_families") or [] if str(item).strip()}
    requirements = _research_family_readiness_requirements(families, gated=gated)
    principal_rows = await conn.fetch(
        """
        SELECT p.auth_state, p.credential_profile, p.is_active,
               EXISTS (
                 SELECT 1 FROM target_credential_profiles cp
                 WHERE cp.target_id=p.target_id
                   AND lower(cp.name)=lower(p.credential_profile)
                   AND cp.is_active=true
                   AND (cp.expires_at IS NULL OR cp.expires_at > NOW())
               ) AS credential_configured
        FROM target_principals p
        WHERE p.target_id=$1 AND p.is_active=true
        """,
        target_id,
    )
    principals = [row_to_dict(row) for row in principal_rows]
    signals = _target_credential_precondition_signals(principals)
    invariant_counts: dict[str, int] = {}
    try:
        invariant_row = await conn.fetchrow(
            """
            SELECT COUNT(*) FILTER (WHERE contract_kind='access_control')::int AS access_control,
                   COUNT(*) FILTER (WHERE contract_kind='field_constraint')::int AS field_constraint,
                   COUNT(*) FILTER (WHERE contract_kind='workflow_transition')::int AS workflow
            FROM target_invariant_contracts
            WHERE target_id=$1 AND status='approved'
            """,
            target_id,
        )
        invariant_counts = {
            key: int((invariant_row or {}).get(key) or 0)
            for key in ("access_control", "field_constraint", "workflow")
        }
    except Exception:
        # Rolling migrations and test doubles fail closed: invariant-only families are unavailable.
        invariant_counts = {"access_control": 0, "field_constraint": 0, "workflow": 0}
    surface = await conn.fetchrow(
        """
        SELECT COUNT(*)::int AS inventory_rows,
               COUNT(DISTINCT upper(method) || ' ' || path)::int AS unique_routes,
               COUNT(DISTINCT upper(method) || ' ' || path)
                   FILTER (WHERE auth_state IN ('user1','user2'))::int AS authenticated_routes,
               COUNT(DISTINCT upper(method) || ' ' || path)
                   FILTER (WHERE auth_state='user2')::int AS second_user_routes,
               COUNT(DISTINCT upper(method) || ' ' || path)
                   FILTER (
                     WHERE auth_state IN ('user1','user2')
                       AND (
                         upper(method)='GET'
                         OR COALESCE(param_shape, '') <> ''
                         OR COALESCE(replay_spec, '') <> ''
                       )
                   )::int AS executable_routes,
               COUNT(DISTINCT upper(method) || ' ' || path)
                   FILTER (
                     WHERE upper(method)='GET'
                        OR COALESCE(param_shape, '') <> ''
                        OR COALESCE(replay_spec, '') <> ''
                   )::int AS all_executable_routes,
               COUNT(DISTINCT upper(method) || ' ' || path)
                   FILTER (
                     WHERE auth_state IN ('user1','user2')
                       AND path ~ '/(\\{[^/{}]+\\}|:[A-Za-z_][A-Za-z0-9_]*|[0-9]+)(/|$)'
                   )::int AS object_routes,
               COUNT(DISTINCT upper(method) || ' ' || path)
                   FILTER (
                     WHERE auth_state IN ('user1','user2')
                       AND upper(method) IN ('POST','PUT','PATCH')
                       AND (COALESCE(param_shape, '') <> '' OR COALESCE(replay_spec, '') <> '')
                   )::int AS mutation_routes,
               COUNT(DISTINCT upper(method) || ' ' || path)
                   FILTER (
                     WHERE COALESCE(param_shape, '') <> '' OR COALESCE(replay_spec, '') <> ''
                   )::int AS parameterized_routes,
               MAX(last_seen_at) AS latest_inventory_seen_at
        FROM target_endpoints
        WHERE target_id=$1 AND COALESCE(test_status, '') <> 'gone'
        """,
        target_id,
    )
    preflight_scan_id = _optional_uuid(config.get("preflight_scan_id"))
    preflight = None
    reused_preflight = False
    if preflight_scan_id:
        preflight = await conn.fetchrow(
            "SELECT id, status, current_phase, error_message, created_at, completed_at FROM scans WHERE id=$1 AND target_id=$2",
            preflight_scan_id,
            target_id,
        )
    elif gated:
        # Reuse recent target-bound work only when its durable provenance meets
        # the selected families' needs. Public injection/data campaigns do not
        # require a two-principal graph; BOLA still does.
        preflight = await conn.fetchrow(
            """
            SELECT s.id, s.status, s.current_phase, s.error_message, s.created_at, s.completed_at
            FROM scans s
            WHERE s.target_id=$1 AND s.status='completed'
              AND (s.scan_role IS NULL OR s.scan_role <> 'shard')
              AND s.completed_at >= NOW() - INTERVAL '24 hours'
              AND EXISTS (
                SELECT 1 FROM target_endpoints e
                WHERE e.target_id=$1 AND e.last_seen_scan_id IN (
                    SELECT family.id FROM scans family
                    WHERE family.id=s.id OR family.parent_scan_id=s.id
                )
                  AND (
                    $2::boolean=false
                    OR e.auth_state IN ('user1','user2')
                  )
                  AND (
                    $3::boolean=false
                    OR e.auth_state='user2'
                  )
              )
              AND (
                $3::boolean=false
                OR EXISTS (
                  SELECT 1 FROM application_graph_edges edge
                  WHERE edge.target_id=$1 AND edge.scan_id IN (
                      SELECT family.id FROM scans family
                      WHERE family.id=s.id OR family.parent_scan_id=s.id
                  )
                    AND edge.edge_type='auth_boundary'
                    AND COALESCE(edge.attributes->>'source_principal','') <> ''
                    AND COALESCE(edge.attributes->>'excluded_principal','') <> ''
                    AND edge.attributes->>'source_principal' <> edge.attributes->>'excluded_principal'
                )
              )
            ORDER BY s.completed_at DESC
            LIMIT 1
            """,
            target_id,
            bool(requirements["primary_credentials"]),
            bool(requirements["second_user"]),
        )
        if preflight:
            preflight_scan_id = _optional_uuid(preflight.get("id"))
            reused_preflight = True
    fresh_surface = await conn.fetchrow(
        """
        SELECT COUNT(DISTINCT upper(method) || ' ' || path)::int AS fresh_unique_routes,
               COUNT(DISTINCT upper(method) || ' ' || path)
                   FILTER (WHERE auth_state IN ('user1','user2'))::int AS fresh_authenticated_routes,
               COUNT(DISTINCT upper(method) || ' ' || path)
                   FILTER (WHERE auth_state='user2')::int AS fresh_second_user_routes,
               COUNT(DISTINCT upper(method) || ' ' || path)
                   FILTER (
                     WHERE auth_state IN ('user1','user2')
                       AND (
                         upper(method)='GET'
                         OR COALESCE(param_shape, '') <> ''
                         OR COALESCE(replay_spec, '') <> ''
                       )
                   )::int AS fresh_executable_routes,
               COUNT(DISTINCT upper(method) || ' ' || path)
                   FILTER (
                     WHERE upper(method)='GET'
                        OR COALESCE(param_shape, '') <> ''
                        OR COALESCE(replay_spec, '') <> ''
                   )::int AS fresh_all_executable_routes,
               COUNT(DISTINCT upper(method) || ' ' || path)
                   FILTER (
                     WHERE auth_state IN ('user1','user2')
                       AND path ~ '/(\\{[^/{}]+\\}|:[A-Za-z_][A-Za-z0-9_]*|[0-9]+)(/|$)'
                   )::int AS fresh_object_routes,
               COUNT(DISTINCT upper(method) || ' ' || path)
                   FILTER (
                     WHERE auth_state IN ('user1','user2')
                       AND upper(method) IN ('POST','PUT','PATCH')
                       AND (COALESCE(param_shape, '') <> '' OR COALESCE(replay_spec, '') <> '')
                   )::int AS fresh_mutation_routes,
               COUNT(DISTINCT upper(method) || ' ' || path)
                   FILTER (
                     WHERE COALESCE(param_shape, '') <> '' OR COALESCE(replay_spec, '') <> ''
                   )::int AS fresh_parameterized_routes
        FROM target_endpoints
        WHERE target_id=$1 AND last_seen_scan_id IN (
            SELECT id FROM scans
            WHERE id=COALESCE((SELECT parent_scan_id FROM scans WHERE id=$2::uuid), $2::uuid)
               OR parent_scan_id=COALESCE((SELECT parent_scan_id FROM scans WHERE id=$2::uuid), $2::uuid)
        )
        """,
        target_id,
        preflight_scan_id,
    )
    graph = await conn.fetchrow(
        """
        SELECT COUNT(*) FILTER (WHERE node_type='route')::int AS route_nodes,
               COUNT(*) FILTER (
                   WHERE node_type='route' AND scan_id IN (
                       SELECT id FROM scans
                       WHERE id=COALESCE((SELECT parent_scan_id FROM scans WHERE id=$2::uuid), $2::uuid)
                          OR parent_scan_id=COALESCE((SELECT parent_scan_id FROM scans WHERE id=$2::uuid), $2::uuid)
                   )
               )::int AS fresh_route_nodes,
               MAX(last_seen_at) AS latest_graph_seen_at,
               (SELECT COUNT(*)::int FROM application_graph_edges WHERE target_id=$1) AS edge_count,
               (SELECT COUNT(*)::int FROM application_graph_edges
                  WHERE target_id=$1 AND scan_id IN (
                      SELECT id FROM scans
                      WHERE id=COALESCE((SELECT parent_scan_id FROM scans WHERE id=$2::uuid), $2::uuid)
                         OR parent_scan_id=COALESCE((SELECT parent_scan_id FROM scans WHERE id=$2::uuid), $2::uuid)
                  )) AS fresh_edge_count,
               (SELECT COUNT(*)::int FROM application_graph_edges
                  WHERE target_id=$1 AND scan_id IN (
                      SELECT id FROM scans
                      WHERE id=COALESCE((SELECT parent_scan_id FROM scans WHERE id=$2::uuid), $2::uuid)
                         OR parent_scan_id=COALESCE((SELECT parent_scan_id FROM scans WHERE id=$2::uuid), $2::uuid)
                  )
                    AND edge_type='auth_boundary'
                    AND COALESCE(attributes->>'source_principal','') <> ''
                    AND COALESCE(attributes->>'excluded_principal','') <> ''
                    AND attributes->>'source_principal' <> attributes->>'excluded_principal'
               ) AS fresh_auth_boundary_edges
        FROM application_graph_nodes WHERE target_id=$1
        """,
        target_id,
        preflight_scan_id,
    )
    surface_payload = {
        **(row_to_dict(surface) if surface else {}),
        **(row_to_dict(fresh_surface) if fresh_surface else {}),
        **(row_to_dict(graph) if graph else {}),
    }
    before = config.get("surface_before_preflight") if isinstance(config.get("surface_before_preflight"), dict) else {}
    executable_routes = int(surface_payload.get("executable_routes") or 0)
    all_executable_routes = int(surface_payload.get("all_executable_routes") or 0)
    object_routes = int(surface_payload.get("object_routes") or 0)
    mutation_routes = int(surface_payload.get("mutation_routes") or 0)
    parameterized_routes = int(surface_payload.get("parameterized_routes") or 0)
    fresh_route_nodes = int(surface_payload.get("fresh_route_nodes") or 0)
    fresh_edge_count = int(surface_payload.get("fresh_edge_count") or 0)
    # A BOLA-usable graph needs a FRESH cross-principal auth_boundary edge (source_principal !=
    # excluded_principal), not merely any new edge -- a lone producer/produces edge or a stale
    # boundary must not open the gate. Counting any edge_type let readiness pass with no real
    # two-principal surface (the reported fail-open).
    fresh_auth_boundary_edges = int(surface_payload.get("fresh_auth_boundary_edges") or 0)
    family_executable_routes = (
        int(surface_payload.get("fresh_executable_routes") or 0) if gated else executable_routes
    )
    family_all_executable_routes = (
        int(surface_payload.get("fresh_all_executable_routes") or 0) if gated else all_executable_routes
    )
    family_object_routes = (
        int(surface_payload.get("fresh_object_routes") or 0) if gated else object_routes
    )
    family_second_user_routes = (
        int(surface_payload.get("fresh_second_user_routes") or 0)
        if gated else int(surface_payload.get("second_user_routes") or 0)
    )
    family_mutation_routes = (
        int(surface_payload.get("fresh_mutation_routes") or 0) if gated else mutation_routes
    )
    family_parameterized_routes = (
        int(surface_payload.get("fresh_parameterized_routes") or 0) if gated else parameterized_routes
    )
    executable_families: list[str] = []
    if "auth" in families and family_executable_routes > 0:
        executable_families.append("auth")
    if (
        "bola" in families
        and family_object_routes > 0
        and family_second_user_routes > 0
        and fresh_auth_boundary_edges > 0
    ):
        executable_families.append("bola")
    for injection_family in ("sqli", "xss"):
        if injection_family in families and family_parameterized_routes > 0:
            executable_families.append(injection_family)
    # Mass-assignment leads come from the persistent endpoint inventory (any authenticated write route
    # with a captured body), NOT from a fresh two-principal preflight like BOLA. A BOLA-focused reused
    # preflight leaves fresh_mutation_routes=0 even when the inventory holds 100+ writable routes, which
    # wrongly drops the whole family and lets its many leads flood the pre-truncation board only to be
    # stripped later, starving executable families. The live-surface filter already discards stale/gone
    # routes, so gate on the persistent mutation surface (whole-target) instead of the fresh count.
    if "mass_assignment" in families and (family_mutation_routes > 0 or mutation_routes > 0):
        executable_families.append("mass_assignment")
    if (
        "field_constraint" in families
        and family_mutation_routes > 0
        and invariant_counts.get("field_constraint", 0) > 0
    ):
        executable_families.append("field_constraint")
    if (
        "workflow" in families
        and family_mutation_routes > 0
        and invariant_counts.get("workflow", 0) > 0
    ):
        executable_families.append("workflow")
    if "data_exposure" in families and family_executable_routes > 0:
        executable_families.append("data_exposure")
    if (
        "access_control" in families
        and family_executable_routes > 0
        and invariant_counts.get("access_control", 0) > 0
    ):
        executable_families.append("access_control")
    fresh_authenticated_routes = int(surface_payload.get("fresh_authenticated_routes") or 0)
    if gated and requirements["authenticated_preflight"]:
        # Count authenticated coverage stamped by THIS preflight, not only net-new cardinality. A
        # successful refresh of 30 existing authenticated routes is useful and fresh; an unrelated
        # concurrent/public route is not. The scan-id provenance closes both the old fail-open and the
        # same-count false-negative that repeatedly exhausted otherwise healthy auth preflights.
        meaningful_preflight_gain = bool(fresh_auth_boundary_edges > 0 or fresh_authenticated_routes > 0)
    elif gated:
        meaningful_preflight_gain = bool(
            int(surface_payload.get("fresh_unique_routes") or 0) > 0
            and (
                family_all_executable_routes > 0
                or family_parameterized_routes > 0
            )
        )
    else:
        meaningful_preflight_gain = bool(
            fresh_route_nodes > 0
            or int(surface_payload.get("unique_routes") or 0) > int(before.get("unique_routes") or 0)
            or not before
        )
    surface_payload.update({
        "executable_families": sorted(set(executable_families)),
        "unavailable_families": sorted(families - set(executable_families)),
        "approved_invariant_counts": invariant_counts,
        "meaningful_preflight_gain": meaningful_preflight_gain,
    })
    blockers: list[str] = []
    if requirements["primary_credentials"] and signals.get("primary_credentials") != "configured":
        blockers.append("primary_credentials_required")
    if gated and not config.get("approval_receipt_id"):
        blockers.append("approval_receipt_required")
    if requirements["second_user"] and signals.get("second_user_credentials") != "configured":
        blockers.append("distinct_second_user_credentials_required")
    preflight_status = str(preflight.get("status") or "missing") if preflight else "missing"
    if gated and preflight_status != "completed":
        blockers.append(
            (
                "authenticated_preflight_in_progress"
                if requirements["authenticated_preflight"] else
                "focused_preflight_in_progress"
            )
            if preflight_status in {"pending", "queued", "running"}
            else (
                "authenticated_preflight_required"
                if requirements["authenticated_preflight"] else
                "focused_preflight_required"
            )
        )
    if int(surface_payload.get("unique_routes") or 0) < int(requirements["unique_routes"]):
        blockers.append(
            "insufficient_unique_route_coverage"
            if gated else
            "read_only_campaign_requires_existing_coverage"
        )
    if requirements["authenticated_routes"] and int(surface_payload.get("authenticated_routes") or 0) < int(requirements["authenticated_routes"]):
        blockers.append("insufficient_authenticated_route_coverage")
    required_executable_count = (
        family_executable_routes if requirements["primary_credentials"]
        else family_all_executable_routes
    )
    if gated and required_executable_count < RESEARCH_SURFACE_MIN_EXECUTABLE_ROUTES:
        blockers.append(
            "no_executable_authenticated_routes"
            if requirements["primary_credentials"] else
            "no_executable_routes"
        )
    if requirements["second_user"] and int(surface_payload.get("second_user_routes") or 0) <= 0:
        blockers.append("second_user_surface_not_observed")
    if requirements["second_user"] and object_routes > 0 and fresh_auth_boundary_edges <= 0:
        blockers.append("two_principal_graph_not_materialized")
    if gated and preflight_status == "completed" and not meaningful_preflight_gain:
        blockers.append(
            "authenticated_preflight_no_material_gain"
            if requirements["authenticated_preflight"] else
            "focused_preflight_no_material_gain"
        )
    if gated and families and not executable_families:
        blockers.append("no_allowed_family_has_executable_surface")
    if gated and config.get("require_all_requested_families"):
        blockers.extend(
            f"family_surface_unavailable:{family}"
            for family in sorted(families - set(executable_families))
        )
    hard_blockers = {
        "primary_credentials_required",
        "distinct_second_user_credentials_required",
        "approval_receipt_required",
        "read_only_campaign_requires_existing_coverage",
    }
    return {
        "ready": not blockers,
        "state": "ready" if not blockers else (
            "blocked" if hard_blockers.intersection(blockers) else
            "waiting" if {
                "authenticated_preflight_in_progress", "focused_preflight_in_progress",
            }.intersection(blockers) else
            "repairable"
        ),
        "blockers": blockers,
        "credential_signals": signals,
        "surface": surface_payload,
        "preflight_scan": row_to_dict(preflight) if preflight else None,
        "reused_preflight": reused_preflight,
        "required": {
            **requirements,
            "fresh_two_principal_graph": bool(requirements["second_user"] and object_routes > 0),
        },
    }


def _research_preflight_scan_options(
    *,
    focus_family: str,
    custom_endpoints: list[str],
    approval_receipt_id: str | None,
) -> ScanOptions:
    endpoint_count = len(custom_endpoints)
    return ScanOptions(
        no_early_stop=True,
        parallel=False,
        auth_state_shards=False,
        custom_endpoints=custom_endpoints or None,
        focused_endpoints_only=bool(custom_endpoints),
        zero_rediscovery=bool(custom_endpoints),
        skip_global_checks=True,
        exploit_depth=focus_family == "bola",
        custom_budget={
            "max_urls": max(50, endpoint_count),
            "active_max_endpoints": max(20, endpoint_count),
            "active_max_seconds": max(900, min(3600, endpoint_count * 20)),
            "phase4_max_seconds": max(600, min(2400, endpoint_count * 12)),
            "max_duration_minutes": 75,
        },
        require_current_workers=True,
        approval_receipt_id=approval_receipt_id,
    )


async def _research_campaign_self_repair(campaign_id: Any) -> dict[str, Any]:
    """Queue one focused, principal-coherent readiness scan at a time.

    BOLA resource mapping requires user1 and user2 in the same execution.  Do
    not use auth-state shards here: they are useful for breadth accounting but
    structurally incapable of producing cross-principal graph edges.
    """
    campaign_uuid = _optional_uuid(campaign_id)
    async with db_pool.acquire() as conn:
        campaign = await conn.fetchrow("SELECT * FROM campaigns WHERE id=$1", campaign_uuid)
        if not campaign:
            raise HTTPException(status_code=404, detail="Research campaign not found")
        readiness = await _research_campaign_readiness(conn, campaign)
        payload = row_to_dict(campaign)
        metadata = _decode_json_value(payload.get("metadata_json")) or {}
        config = metadata.get("autonomous_research") if isinstance(metadata.get("autonomous_research"), dict) else {}
        if readiness["ready"] or readiness["state"] == "waiting":
            if readiness["ready"] and not config.get("preflight_scan_id") and readiness.get("preflight_scan"):
                config.update({
                    "preflight_state": "completed",
                    "preflight_scan_id": str(readiness["preflight_scan"].get("id") or "") or None,
                    "preflight_kind": "reused_recent_authenticated_graph",
                    "readiness": readiness,
                })
                metadata["autonomous_research"] = config
                campaign = await conn.fetchrow(
                    "UPDATE campaigns SET metadata_json=$2::jsonb, updated_at=NOW() WHERE id=$1 RETURNING *",
                    campaign_uuid,
                    json.dumps(metadata, default=str),
                )
                return {
                    "action": "reused_authenticated_graph_preflight",
                    "readiness": readiness,
                    "campaign": _public_campaign_row(campaign),
                }
            return {"action": "none", "readiness": readiness, "campaign": _public_campaign_row(campaign)}
        retry_after_raw = str(config.get("preflight_retry_after") or "").strip()
        if retry_after_raw:
            try:
                retry_after = datetime.fromisoformat(retry_after_raw.replace("Z", "+00:00"))
                if retry_after.tzinfo is None:
                    retry_after = retry_after.replace(tzinfo=timezone.utc)
            except ValueError:
                retry_after = datetime.min.replace(tzinfo=timezone.utc)
            if retry_after > datetime.now(timezone.utc):
                return {
                    "action": "transient_retry_wait",
                    "retry_after": retry_after.isoformat(),
                    "readiness": readiness,
                    "campaign": _public_campaign_row(campaign),
                }
        if readiness["state"] == "blocked":
            config["readiness"] = readiness
            config["last_error"] = ",".join(readiness["blockers"])
            metadata["autonomous_research"] = config
            updated = await conn.fetchrow(
                "UPDATE campaigns SET status='paused', metadata_json=$2::jsonb, updated_at=NOW() WHERE id=$1 RETURNING *",
                campaign_uuid,
                json.dumps(metadata, default=str),
            )
            return {"action": "blocked", "readiness": readiness, "campaign": _public_campaign_row(updated)}
        stale_queueing_claim = _research_preflight_claim_is_stale(config)
        attempts = max(
            0,
            int(config.get("preflight_attempts") or 0) - (1 if stale_queueing_claim else 0),
        )
        if attempts >= RESEARCH_PREFLIGHT_MAX_ATTEMPTS:
            config["readiness"] = readiness
            config["last_error"] = "authenticated_coverage_readiness_exhausted"
            metadata["autonomous_research"] = config
            updated = await conn.fetchrow(
                "UPDATE campaigns SET status='paused', metadata_json=$2::jsonb, updated_at=NOW() WHERE id=$1 RETURNING *",
                campaign_uuid,
                json.dumps(metadata, default=str),
            )
            return {"action": "exhausted", "readiness": readiness, "campaign": _public_campaign_row(updated)}
        budget = await _research_campaign_budget_snapshot(conn, campaign)
        preflight_budget_before = _research_normalize_budget_used(
            config.get("preflight_budget_used") or {}
        )
        if stale_queueing_claim:
            preflight_budget_before = _research_subtract_cost(
                preflight_budget_before, RESEARCH_PREFLIGHT_RESERVED_COST,
            )
            budget["used"] = _research_subtract_cost(
                budget.get("used") or {}, RESEARCH_PREFLIGHT_RESERVED_COST,
            )
            budget["remaining"] = _research_campaign_budget_remaining(
                budget["limits"], budget["used"],
            )
        preflight_budget_used = _research_apply_cost(
            preflight_budget_before,
            RESEARCH_PREFLIGHT_RESERVED_COST,
        )
        aggregate_after_claim = {
            key: int(budget["used"].get(key) or 0) + int(RESEARCH_PREFLIGHT_RESERVED_COST.get(key) or 0)
            for key in RESEARCH_BUDGET_KEYS
        }
        budget_violations = [
            key for key in RESEARCH_BUDGET_KEYS
            if aggregate_after_claim[key] > int(budget["limits"].get(key) or 0)
        ]
        if budget_violations:
            config.update({
                "budget_limits": budget["limits"],
                "budget_used": budget["used"],
                "remaining_budget": budget["remaining"],
                "last_error": "campaign_budget_exhausted:" + ",".join(budget_violations),
            })
            metadata["autonomous_research"] = config
            updated = await conn.fetchrow(
                "UPDATE campaigns SET status='paused', metadata_json=$2::jsonb, updated_at=NOW() WHERE id=$1 RETURNING *",
                campaign_uuid,
                json.dumps(metadata, default=str),
            )
            return {
                "action": "campaign_budget_exhausted",
                "readiness": readiness,
                "campaign": _public_campaign_row(updated),
            }
        preflight_claim_id = str(uuid.uuid4())
        config.update({
            "preflight_state": "queueing",
            "preflight_claim_id": preflight_claim_id,
            "preflight_retry_after": None,
            "preflight_attempts": attempts + 1,
            "preflight_started_at": datetime.now(timezone.utc).isoformat(),
            "readiness": readiness,
            "budget_limits": budget["limits"],
            "preflight_budget_used": preflight_budget_used,
            "budget_used": aggregate_after_claim,
            "remaining_budget": _research_campaign_budget_remaining(
                budget["limits"], aggregate_after_claim,
            ),
        })
        metadata["autonomous_research"] = config
        claimed = await conn.fetchrow(
            """
            UPDATE campaigns SET metadata_json=$2::jsonb, status='active', updated_at=NOW()
            WHERE id=$1 AND status <> 'cancelled'
              AND (
                COALESCE(metadata_json #>> '{autonomous_research,preflight_state}', '')
                    NOT IN ('queueing','running')
                OR (
                  metadata_json #>> '{autonomous_research,preflight_state}' = 'queueing'
                  AND COALESCE(
                    NULLIF(metadata_json #>> '{autonomous_research,preflight_started_at}', '')::timestamptz,
                    '-infinity'::timestamptz
                  ) < NOW() - INTERVAL '2 minutes'
                )
                OR (
                  metadata_json #>> '{autonomous_research,preflight_state}' = 'running'
                  AND EXISTS (
                    SELECT 1 FROM scans linked_preflight
                    WHERE linked_preflight.id::text =
                          metadata_json #>> '{autonomous_research,preflight_scan_id}'
                      AND linked_preflight.status IN ('completed','failed','cancelled')
                  )
                )
              )
            RETURNING *
            """,
            campaign_uuid,
            json.dumps(metadata, default=str),
        )
        if not claimed:
            current = await conn.fetchrow("SELECT * FROM campaigns WHERE id=$1", campaign_uuid)
            return {
                "action": "preflight_claim_lost",
                "readiness": readiness,
                "campaign": _public_campaign_row(current),
            }
        target = await conn.fetchrow("SELECT id, url FROM targets WHERE id=$1 AND is_active=true", campaign["target_id"])
        if not target:
            raise HTTPException(status_code=404, detail="Active target not found")
        # DISTINCT then order: Postgres forbids an ORDER BY expression (the object-route-first
        # priority CASE) that is not in a SELECT DISTINCT list, so dedupe in a subquery and rank
        # outside it. Prior form raised InvalidColumnReferenceError and 500'd every gated launch.
        endpoint_rows = await conn.fetch(
            """
            SELECT method, path FROM (
                -- Dedupe by (method, path) only: the worklist below uses just "METHOD path",
                -- so keeping param_shape in DISTINCT spent LIMIT slots on duplicate method/path pairs.
                SELECT DISTINCT method, path
                FROM target_endpoints
                WHERE target_id=$1 AND COALESCE(test_status, '') <> 'gone'
                  AND (
                    $2::boolean=false
                    OR COALESCE(auth_state, '') IN ('user1','user2')
                  )
            ) e
            ORDER BY
              CASE
                WHEN path ~ '/(\\{[^/{}]+\\}|:[A-Za-z_][A-Za-z0-9_]*|[0-9]+)(/|$)' THEN 0
                WHEN upper(method)='GET' THEN 1
                ELSE 2
              END,
              path, method
            LIMIT 150
            """,
            campaign["target_id"],
            bool((readiness.get("required") or {}).get("primary_credentials")),
        )

    families = {
        str(item).strip().lower()
        for item in config.get("allowed_families") or []
        if str(item).strip()
    }
    # ``auth`` is a Hunt/research objective, not a canonical Scan family. An
    # authenticated surface refresh uses the Scan ``recon`` family with the
    # exact saved principal references; BOLA remains the cross-principal proof
    # family. Never leak the research taxonomy into Scan admission.
    focus_family = next(
        (family for family in ("bola", "sqli", "xss") if family in families),
        (
            "recon"
            if "auth" in families
            or (readiness.get("required") or {}).get("primary_credentials")
            else "all"
        ),
    )
    custom_endpoints = []
    for row in endpoint_rows:
        method = str(row.get("method") or "GET").strip().upper()
        path = str(row.get("path") or "").strip()
        if path:
            custom_endpoints.append(f"{method} {path}")

    try:
        queued = await _submit_scan(ScanInternalCompatibilityRequest(
            target=str(target["url"]),
            budget_profile="thorough",
            policy={
                "preset": "standard_active" if focus_family == "all" else "custom",
                "active_testing": True,
                "include_families": ([] if focus_family == "all" else [focus_family]),
            },
            advanced=ScanAdvancedLimits(
                include_families=[] if focus_family == "all" else [focus_family],
            ),
            approval_receipt_id=config.get("approval_receipt_id"),
            options=_research_preflight_scan_options(
                focus_family=focus_family,
                custom_endpoints=custom_endpoints,
                approval_receipt_id=config.get("approval_receipt_id"),
            ),
        ))
    except Exception as exc:
        transient = _research_preflight_error_is_transient(exc)
        async with db_pool.acquire() as conn:
            campaign = await conn.fetchrow("SELECT * FROM campaigns WHERE id=$1", campaign_uuid)
            if str(campaign.get("status") or "") == "cancelled":
                return {
                    "action": "cancelled_during_preflight_queue",
                    "readiness": readiness,
                    "campaign": _public_campaign_row(campaign),
                }
            payload = row_to_dict(campaign)
            metadata = _decode_json_value(payload.get("metadata_json")) or {}
            config = metadata.get("autonomous_research") if isinstance(metadata.get("autonomous_research"), dict) else {}
            config.update({
                "preflight_state": "pending" if transient else "failed",
                "preflight_attempts": attempts if transient else attempts + 1,
                "preflight_budget_used": preflight_budget_before,
                "budget_used": budget["used"],
                "remaining_budget": _research_campaign_budget_remaining(
                    budget["limits"], budget["used"],
                ),
                "preflight_retry_after": (
                    datetime.now(timezone.utc)
                    + timedelta(seconds=RESEARCH_PREFLIGHT_TRANSIENT_RETRY_SECONDS)
                ).isoformat() if transient else None,
                "last_error": (
                    f"transient_preflight_queue_failure:{str(exc)[:450]}"
                    if transient else str(exc)[:500]
                ),
            })
            metadata["autonomous_research"] = config
            updated = await conn.fetchrow(
                """
                UPDATE campaigns SET status=$4, metadata_json=$2::jsonb, updated_at=NOW()
                WHERE id=$1
                  AND metadata_json #>> '{autonomous_research,preflight_claim_id}'=$3
                RETURNING *
                """,
                campaign_uuid,
                json.dumps(metadata, default=str),
                preflight_claim_id,
                "active" if transient else "paused",
            )
        return {
            "action": "retry_transient" if transient else "failed",
            "error": str(exc)[:500], "readiness": readiness,
            "campaign": _public_campaign_row(updated or campaign),
        }

    async with db_pool.acquire() as conn:
        campaign = await conn.fetchrow("SELECT * FROM campaigns WHERE id=$1", campaign_uuid)
        payload = row_to_dict(campaign)
        metadata = _decode_json_value(payload.get("metadata_json")) or {}
        config = metadata.get("autonomous_research") if isinstance(metadata.get("autonomous_research"), dict) else {}
        config.update({
            "preflight_state": "running",
            "preflight_scan_id": queued.get("scan_id"),
            "preflight_job_id": queued.get("job_id"),
            "surface_before_preflight": readiness.get("surface") or {},
            "preflight_kind": "focused_two_principal_graph" if focus_family == "bola" else "focused_authenticated_family",
            "preflight_family": focus_family,
            "preflight_endpoint_count": len(custom_endpoints),
            "last_error": None,
            "preflight_retry_after": None,
        })
        metadata["autonomous_research"] = config
        updated = await conn.fetchrow(
            """
            UPDATE campaigns SET status='active', metadata_json=$2::jsonb, updated_at=NOW()
            WHERE id=$1 AND status <> 'cancelled'
              AND metadata_json #>> '{autonomous_research,preflight_claim_id}'=$3
            RETURNING *
            """,
            campaign_uuid,
            json.dumps(metadata, default=str),
            preflight_claim_id,
        )
        current = updated or campaign
    if not updated:
        try:
            await cancel_scan(str(queued.get("scan_id")))
        except Exception:
            logger.warning(
                "Could not cancel preflight %s after campaign control raced queue completion",
                queued.get("scan_id"),
                exc_info=True,
            )
        return {
            "action": "cancelled_during_preflight_queue",
            "scan_id": queued.get("scan_id"),
            "job_id": queued.get("job_id"),
            "readiness": readiness,
            "campaign": _public_campaign_row(current),
        }
    return {
        "action": "queued_authenticated_graph_preflight",
        "scan_id": queued.get("scan_id"),
        "job_id": queued.get("job_id"),
        "readiness": readiness,
        "campaign": _public_campaign_row(updated),
    }


async def _research_campaign_yield_metrics(conn: Any, campaign: Any) -> dict[str, Any]:
    payload = row_to_dict(campaign)
    campaign_id = _optional_uuid(payload.get("id"))
    target_id = _optional_uuid(payload.get("target_id"))
    episode_rows = await conn.fetch(
        "SELECT id, status, budget_used FROM research_episodes WHERE campaign_id=$1 ORDER BY created_at",
        campaign_id,
    )
    episode_ids = [row["id"] for row in episode_rows]
    decisions = []
    if episode_ids:
        decisions = await conn.fetch(
            """
            SELECT rd.action, rd.status, rd.validation_errors,
                   cr.id AS command_result_id, cr.status AS command_status,
                   cr.finding_ids, cr.result_json
            FROM research_decisions rd
            LEFT JOIN command_results cr ON cr.id=rd.command_result_id
            WHERE rd.episode_id=ANY($1::uuid[])
            ORDER BY rd.created_at
            """,
            episode_ids,
        )
    model_units = sum(
        int((_decode_json_value(row.get("budget_used")) or {}).get("model_tokens") or 0)
        for row in episode_rows
    )
    experiments = 0
    falsified = 0
    recon_actions = 0
    semantic_dimensions: set[str] = set()
    exhausted_dimensions: set[str] = set()
    falsification_counts: dict[str, int] = {}
    outcome_counts: dict[str, int] = {key: 0 for key in sorted(RESEARCH_EXPERIMENT_OUTCOMES)}
    novelty_blocks = 0
    rejected_decisions = 0
    rejection_reasons: Counter[str] = Counter()
    for row in decisions:
        action = _decode_json_value(row.get("action")) or {}
        command = str(action.get("command") or "")
        if command in RESEARCH_RECON_COMMANDS and str(row.get("status") or "") in {
            "accepted", "dispatching", "completed", "blocked",
        }:
            recon_actions += 1
        validation_errors = _decode_json_value(row.get("validation_errors")) or []
        novelty_blocks += sum(1 for error in validation_errors if str(error) == "known_vulnerability_already_covered")
        if str(row.get("status") or "") in {"rejected", "blocked", "failed"}:
            rejected_decisions += 1
            rejection_reasons.update(str(error) for error in validation_errors if str(error))
        dimension = _research_action_semantic_dimension(action)
        if not dimension:
            continue
        semantic_dimensions.add(dimension)
        if row.get("command_result_id") and str(row.get("status") or "") == "completed":
            experiments += 1
            outcome = _research_experiment_outcome(action, row)
            if outcome:
                outcome_name = str(outcome.get("outcome") or "inconclusive")
                outcome_counts[outcome_name] = outcome_counts.get(outcome_name, 0) + 1
            if outcome and outcome.get("deterministic_refutation"):
                falsified += 1
                falsification_counts[dimension] = falsification_counts.get(dimension, 0) + 1
    exhausted_dimensions.update(
        dimension for dimension, count in falsification_counts.items()
        if count >= RESEARCH_SEMANTIC_FALSIFICATION_LIMIT
    )
    # The board is offering nothing net-new: the planner keeps proposing already-owned vulnerabilities
    # (novelty-suppressed at dispatch) and nothing is actually executing. Stop cleanly and early rather
    # than burning the model budget on a covered-board spin (faster than the generic rejection ceiling).
    all_leads_already_covered = (
        novelty_blocks >= 8
        and experiments == 0
        and novelty_blocks == rejected_decisions
        and novelty_blocks >= max(8, int(len(decisions) * 0.75))
    )
    verified_findings = int(await conn.fetchval(
        """
        SELECT COUNT(*) FROM findings
        WHERE target_id=$1 AND tool='autonomous_workflow'
          AND EXISTS (
              SELECT 1
              FROM jsonb_array_elements(
                  COALESCE(evidence->'research_provenance_history', '[]'::jsonb)
              ) AS provenance
              WHERE provenance->>'campaign_id'=$2::text
          )
          AND last_verification_verdict='exploited'
        """,
        target_id,
        str(campaign_id),
    ) or 0)
    verified_scan_findings = int(await conn.fetchval(
        """
        SELECT COUNT(DISTINCT f.id)
        FROM findings f
        WHERE f.target_id=$1
          AND f.last_verification_verdict='exploited'
          AND f.scan_id IN (
              SELECT cr.scan_id
              FROM research_decisions rd
              JOIN research_episodes re ON re.id=rd.episode_id
              JOIN command_results cr ON cr.id=rd.command_result_id
              WHERE re.campaign_id=$2 AND cr.scan_id IS NOT NULL
          )
        """,
        target_id,
        campaign_id,
    ) or 0)
    verified_retest_findings = int(await conn.fetchval(
        """
        SELECT COUNT(DISTINCT fv.finding_id)
        FROM finding_verifications fv
        JOIN command_results cr ON cr.result_json->>'retest_id'=fv.id::text
        JOIN research_decisions rd ON rd.command_result_id=cr.id
        JOIN research_episodes re ON re.id=rd.episode_id
        WHERE re.campaign_id=$1
          AND fv.status='completed'
          AND fv.verdict='exploited'
        """,
        campaign_id,
    ) or 0)
    metadata = _decode_json_value(payload.get("metadata_json")) or {}
    config = metadata.get("autonomous_research") if isinstance(metadata.get("autonomous_research"), dict) else {}
    aggregate_budget = await _research_campaign_budget_snapshot(conn, campaign)
    before = config.get("surface_before_preflight") if isinstance(config.get("surface_before_preflight"), dict) else {}
    after = config.get("surface_after_preflight") if isinstance(config.get("surface_after_preflight"), dict) else {}
    # Net-new-over-DAST: campaign-attributed exact vulnerability identities
    # that no deterministic scanner finding owns.
    net_new_verified = await _research_net_new_finding_count(
        conn, target_id, campaign_id=campaign_id,
    )
    return {
        "episodes": len(episode_rows),
        "decisions": len(decisions),
        "model_units": model_units,
        "experiments": experiments,
        "falsified_experiments": falsified,
        "experiment_outcomes": outcome_counts,
        "non_scientific_experiments": outcome_counts.get("inconclusive", 0) + outcome_counts.get("blocked", 0),
        "semantic_dimensions_tested": len(semantic_dimensions),
        "exhausted_dimensions": len(exhausted_dimensions),
        "recon_actions": recon_actions,
        "novelty_suppressions": novelty_blocks,
        "rejected_decisions": rejected_decisions,
        "rejection_reasons": dict(rejection_reasons.most_common(20)),
        "verified_autonomous_findings": verified_findings,
        "verified_campaign_scan_findings": verified_scan_findings,
        "verified_campaign_retest_findings": verified_retest_findings,
        "net_new_verified_findings": net_new_verified,
        "finding_yield_per_experiment": round(verified_findings / experiments, 4) if experiments else 0.0,
        "model_units_per_verified_finding": (model_units // verified_findings) if verified_findings else None,
        "aggregate_budget": aggregate_budget,
        "surface": {
            "unique_routes_before": int(before.get("unique_routes") or 0),
            "unique_routes_after": int(after.get("unique_routes") or 0),
            "authenticated_routes_before": int(before.get("authenticated_routes") or 0),
            "authenticated_routes_after": int(after.get("authenticated_routes") or 0),
        },
        "stop_recommended": bool(
            verified_findings == 0
            and (
                all_leads_already_covered
                or (
                    experiments >= 12
                    and falsified >= max(9, int(experiments * 0.75))
                )
                or (
                    experiments >= 8
                    and outcome_counts.get("inconclusive", 0) + outcome_counts.get("blocked", 0)
                    >= max(6, int(experiments * 0.75))
                )
                or (
                    rejected_decisions >= 8
                    and rejected_decisions >= max(8, int(len(decisions) * 0.75))
                )
            )
        ),
        "stop_reason": (
            "zero_yield_falsification_ceiling"
            if experiments >= 12 and verified_findings == 0 and falsified >= max(9, int(experiments * 0.75))
            else "experiment_harness_failure_ceiling"
            if experiments >= 8 and verified_findings == 0
            and outcome_counts.get("inconclusive", 0) + outcome_counts.get("blocked", 0)
            >= max(6, int(experiments * 0.75))
            else "all_leads_already_covered"
            if verified_findings == 0 and all_leads_already_covered
            else "planner_rejection_ceiling"
            if rejected_decisions >= 8 and verified_findings == 0
            and rejected_decisions >= max(8, int(len(decisions) * 0.75))
            else None
        ),
    }


async def _materialize_research_invariant_hypotheses(conn: Any, target_id: Any) -> int:
    """Make approved typed invariants enter the same ranked backlog as scanner residue."""
    rows = await conn.fetch(
        "SELECT * FROM target_invariant_contracts WHERE target_id=$1 AND status='approved' ORDER BY updated_at DESC",
        _optional_uuid(target_id),
    )
    materialized = 0
    for row in rows:
        await _upsert_hypothesis(
            conn,
            _invariant_hypothesis_request(
                str(target_id),
                _public_target_invariant_contract_row(row),
                created_by="research_campaign_readiness",
            ),
        )
        materialized += 1
    return materialized


@app.get("/research/episodes/{episode_id}/benchmark")
async def research_episode_benchmark(
    episode_id: str,
    baseline_scan_id: str = Query(
        ...,
        description=(
            "Completed deterministic Scan baseline with "
            "options.benchmark_request_budget."
        ),
    ),
):
    """Score autonomous net-new verified findings against an explicitly equal-budget DAST baseline."""
    async with db_pool.acquire() as conn:
        episode_row = await _research_episode_or_404(conn, episode_id)
        episode = _public_research_episode_row(episode_row)
        baseline_uuid = _uuid_or_400(baseline_scan_id, "baseline scan id")
        baseline = await conn.fetchrow(
            "SELECT id, target_id, scan_type, status, options FROM scans WHERE id=$1",
            baseline_uuid,
        )
        if not baseline or baseline["target_id"] != episode_row["target_id"]:
            raise HTTPException(status_code=400, detail="Baseline scan must belong to the episode target")
        if str(baseline["status"] or "") != "completed" or str(baseline["scan_type"] or "") != "smart":
            raise HTTPException(
                status_code=400,
                detail="Baseline must be a completed deterministic Scan benchmark",
            )
        options = _decode_json_value(baseline["options"]) or {}
        baseline_budget = _int_or_none(options.get("benchmark_request_budget"))
        episode_budget = int((episode.get("budget_limits") or {}).get("requests") or 0)
        if baseline_budget is None:
            raise HTTPException(status_code=400, detail="Baseline lacks options.benchmark_request_budget")
        equal_budget = baseline_budget == episode_budget
        baseline_rows = await conn.fetch(
            "SELECT id, fingerprint, title, tool, cwe, url, evidence, request FROM findings WHERE scan_id=$1",
            baseline_uuid,
        )
        autonomous_rows = await conn.fetch(
            """
            SELECT id, fingerprint, title, severity, tool, cwe, url, evidence, request,
                   last_verification_verdict
            FROM findings
            WHERE target_id=$1 AND tool='autonomous_workflow'
              AND EXISTS (
                  SELECT 1
                  FROM jsonb_array_elements(
                      COALESCE(evidence->'research_provenance_history', '[]'::jsonb)
                  ) AS provenance
                  WHERE provenance->>'episode_id'=$2::text
              )
              AND last_verification_verdict='exploited'
            ORDER BY created_at
            """,
            episode_row["target_id"],
            episode_row["id"],
        )
        # Any fingerprint produced by a NON-autonomous source on this target (the baseline scan,
        # any other DAST/scanner/manual finding, or a scan that ran during the episode window) is
        # not autonomy's to claim as net-new. Exclude all of them, not just the baseline scan.
        prior_source_rows = await conn.fetch(
            "SELECT id, fingerprint, title, tool, cwe, url, evidence, request FROM findings "
            "WHERE target_id=$1 AND COALESCE(tool,'') <> 'autonomous_workflow'",
            episode_row["target_id"],
        )
    prior_keys = {
        key for key in (_finding_vulnerability_key(row) for row in [*baseline_rows, *prior_source_rows])
        if key
    }
    autonomous_with_keys = [(row, _finding_vulnerability_key(row)) for row in autonomous_rows]
    net_new = [
        {
            field: row.get(field)
            for field in ("id", "fingerprint", "title", "severity", "last_verification_verdict")
        }
        for row, key in autonomous_with_keys if key and key not in prior_keys
    ]
    unattributable = [str(row["id"]) for row, key in autonomous_with_keys if not key]
    episode_actual_requests = int((episode.get("budget_used") or {}).get("requests") or 0)
    return {
        "episode_id": str(episode_row["id"]),
        "baseline_scan_id": str(baseline_uuid),
        "baseline_request_budget_configured": baseline_budget,
        "autonomous_request_budget_configured": episode_budget,
        "autonomous_requests_actual": episode_actual_requests,
        "equal_configured_budget": equal_budget,
        "gate_passed": bool(equal_budget and net_new),
        "net_new_verified_findings": net_new,
        "net_new_verified_count": len(net_new),
        "unattributable_autonomous_finding_ids": unattributable,
        "autonomous_verified_count": len(autonomous_rows),
        "baseline_finding_count": len(baseline_rows),
        "caveats": [
            "Budgets compared are CONFIGURED caps; the baseline's actual HTTP request count is not instrumented here.",
            "No application state snapshot/reset between runs; results can depend on shared mutable state.",
            "Worker build-fingerprint uniformity across the baseline and episode is not enforced here.",
            "gate_passed means: at least one VERIFIED autonomous finding whose canonical family+route identity "
            "no non-autonomous source on this target produced, at equal configured budget -- not a fully controlled superiority proof.",
        ],
        "metric": "net_new_verified_canonical_vulnerabilities_not_produced_by_any_non_autonomous_source_on_target",
    }


async def _reuse_research_launch_episode(
    conn,
    *,
    existing: Any,
    req: ResearchLaunchRequest,
    launch_profile: dict[str, Any],
    target_id: uuid.UUID,
    target_url: str,
) -> dict[str, Any]:
    if str(existing["status"]) == "awaiting_input":
        raise HTTPException(
            status_code=409,
            detail={
                "error": "existing_episode_requires_input",
                "episode_id": str(existing["id"]),
                "ui_path": f"/deep-hunt?episode_id={existing['id']}",
            },
        )
    approval_id: uuid.UUID | None = None
    scope_id: str | None = None
    if launch_profile["execution_mode"] == "gated":
        approval = await _validate_approval_receipt_for_action(
            conn,
            req.approval_receipt_id,
            target_url=target_url,
            target_id=target_id,
            action_name="research_episode.resume",
            command="research.episode",
            risk_tier=launch_profile["max_risk_tier"],
            created_by=req.created_by,
            always_require_receipt=True,
        )
        approval_id = _optional_uuid(req.approval_receipt_id)
        scope_id = str(approval.get("scope_receipt_id") or "") or None
    updated = await conn.fetchrow(
        """
        UPDATE research_episodes
        SET approval_receipt_id=COALESCE($2, approval_receipt_id),
            scope_receipt_id=COALESCE($3, scope_receipt_id),
            autopilot_enabled=$4,
            planner=jsonb_set(
                jsonb_set(planner, '{mode}', to_jsonb($5::text), true),
                '{kind}', to_jsonb($6::text), true
            ),
            autopilot_error=NULL,
            autopilot_consecutive_failures=0, updated_at=NOW()
        WHERE id=$1
        RETURNING *
        """,
        existing["id"],
        approval_id,
        scope_id,
        _research_launch_planner_mode(req) == "configured_ai",
        _research_launch_planner_mode(req),
        _research_planner_kind(_research_launch_planner_mode(req)),
    )
    detail = await _research_episode_detail(conn, str(updated["id"]))
    detail["reused"] = True
    detail["ui_path"] = f"/deep-hunt?episode_id={updated['id']}"
    return detail


@app.post("/research/launch")
async def launch_research_episode(req: ResearchLaunchRequest):
    """Launch or reopen a server-defined, subject-bound autonomous mission."""
    expected_subject_types = {
        "target_hunt": {"target"},
        "verify_finding": {"finding"},
        "close_asm_gaps": {"target", "asm"},
    }
    if req.subject_type not in expected_subject_types[req.mission_profile]:
        raise HTTPException(status_code=400, detail="Mission profile does not support this subject type")

    launch_profile = dict(RESEARCH_LAUNCH_PROFILES[req.intensity])
    planner_mode = _research_launch_planner_mode(req)
    autopilot_enabled = planner_mode == "configured_ai"
    if autopilot_enabled:
        if not _research_configured_planner_ready():
            raise HTTPException(status_code=409, detail="Autonomous planner is not configured in AI settings")
    if launch_profile["execution_mode"] == "gated" and not _ai_ops_execute_enabled():
        raise HTTPException(status_code=409, detail="Autonomous active execution is disabled by server policy")

    subject_uuid = _uuid_or_400(req.subject_id, "research subject id")
    finding: Any = None
    async with db_pool.acquire() as conn:
        if req.subject_type == "finding":
            finding = await conn.fetchrow(
                """
                SELECT f.id, f.target_id, f.title, f.severity,
                       f.tool AS category, f.tool, f.cwe,
                       f.source, f.ai_target_id,
                       t.url AS target_url
                FROM findings f
                JOIN targets t ON t.id=f.target_id AND t.is_active=true
                WHERE f.id=$1
                """,
                subject_uuid,
            )
            if not finding:
                raise HTTPException(status_code=404, detail="Web finding subject not found")
            if not _research_finding_is_web(finding):
                raise HTTPException(status_code=400, detail="AI Gate, AI Session, and Model Intake findings use dedicated replay workflows")
            target_id = finding["target_id"]
            target_url = str(finding["target_url"] or "")
        else:
            target_id = subject_uuid
            target = await conn.fetchrow(
                "SELECT id, url FROM targets WHERE id=$1 AND is_active=true",
                target_id,
            )
            if not target:
                raise HTTPException(status_code=404, detail="Active target subject not found")
            target_url = str(target["url"] or "")

        if not req.force_new:
            existing = await conn.fetchrow(
                """
                SELECT * FROM research_episodes
                WHERE target_id=$1
                  AND planner->'mission'->>'profile'=$2
                  AND planner->'mission'->'subject'->>'type'=$3
                  AND planner->'mission'->'subject'->>'id'=$4
                  AND execution_mode=$5
                  AND COALESCE(planner->>'launch_intensity', 'unknown')=$6
                  AND status NOT IN ('completed','cancelled','failed','budget_exhausted','blocked')
                ORDER BY created_at DESC
                LIMIT 1
                """,
                target_id,
                req.mission_profile,
                req.subject_type,
                str(subject_uuid),
                launch_profile["execution_mode"],
                req.intensity,
            )
            if existing:
                return await _reuse_research_launch_episode(
                    conn,
                    existing=existing,
                    req=req,
                    launch_profile=launch_profile,
                    target_id=target_id,
                    target_url=target_url,
                )

        if req.subject_type == "finding":
            active_retest = await conn.fetchrow(
                """
                SELECT id, status FROM finding_verifications
                WHERE finding_id=$1 AND status IN ('queued','running')
                ORDER BY created_at DESC LIMIT 1
                """,
                subject_uuid,
            )
            if active_retest:
                raise HTTPException(
                    status_code=409,
                    detail={
                        "error": "finding_retest_already_active",
                        "retest_id": str(active_retest["id"]),
                        "status": str(active_retest["status"]),
                        "ui_path": f"/findings/{subject_uuid}",
                    },
                )

    budget_limits = dict(launch_profile["budget_limits"])
    max_steps = int(launch_profile["max_steps"])
    if req.mission_profile == "verify_finding":
        if req.intensity == "analyze":
            max_steps = 4
            budget_limits.update({
                "steps": 4, "actions": 3, "active_actions": 0, "requests": 0,
                "seconds": 300, "model_tokens": 40000,
            })
        else:
            # One proof replay is enough for a finding-focused mission. The controller must
            # observe that result before any follow-up reasoning.
            max_steps = 6
            budget_limits.update({
                "steps": 6, "actions": 5, "active_actions": 1, "requests": 25,
                "seconds": 900, "model_tokens": 75000,
            })
        title = str(finding["title"] or "finding")[:300]
        objective = (
            f"Determine whether finding {subject_uuid} ({title}) is reproducible and current. "
            "Inspect this exact finding first, run at most one bounded deterministic/tiered retest "
            "when authorized, wait for its proof result, then stop with the verdict, remaining "
            "uncertainty, and recommended next step. Do not launch unrelated target-wide work."
        )
    elif req.mission_profile == "close_asm_gaps":
        objective = (
            "Improve this target's most important ASM coverage gaps. Inspect current gaps and "
            "activity, choose the next bounded ASM action, wait for each result, avoid duplicate "
            "actions, and stop when no decision-relevant gap can be improved within budget."
        )
    else:
        objective = (
            "Find and verify the highest-impact security weaknesses on this target. Prioritize "
            "authorization, injection, sensitive-data exposure, and workflow abuse. Learn from "
            "each completed action, never repeat an identical no-progress action, and stop when "
            "the budget is exhausted or no valuable bounded action remains."
        )
    if req.objective_override:
        objective = req.objective_override.strip()
    if req.budget_limits_override:
        for key in RESEARCH_BUDGET_KEYS:
            if key not in req.budget_limits_override:
                continue
            try:
                budget_limits[key] = min(
                    int(budget_limits.get(key) or 0),
                    max(0, int(req.budget_limits_override[key])),
                )
            except (TypeError, ValueError):
                continue
        max_steps = min(max_steps, max(1, int(budget_limits.get("steps") or 1)))

    allowed_families = []
    if launch_profile["execution_mode"] == "gated":
        allowed_families = list(_research_intensity_campaign_families(req.intensity))
    if req.allowed_families_override:
        allowed_families = [str(item).strip() for item in req.allowed_families_override if str(item).strip()]
    if req.mission_profile == "target_hunt" and allowed_families:
        allowed_families = _validate_research_intensity_families(req.intensity, allowed_families)
    if finding:
        family = _research_finding_family(finding)
        allowed_families = [family] if family else []

    if req.mission_profile == "target_hunt" and req.intensity == "deep_hunt":
        # Deep Hunt may self-provision two managed principals via the app's own signup so
        # two-principal BOLA workflows are reachable without hand-configured credentials. Opt-in
        # (target metadata_json.auto_provisioning.enabled); best-effort; never blocks a launch.
        try:
            provisioning = await _research_maybe_auto_provision_principals(
                target_id,
                approval_receipt_id=req.approval_receipt_id,
                created_by=req.created_by,
                require_second_user="bola" in allowed_families,
            )
            logger.info(
                "deep_hunt principal bootstrap for target %s: %s",
                target_id,
                provisioning.get("action"),
            )
        except Exception:
            # A valid approval permits provisioning but does not make target-specific
            # signup failures fatal; the observation exposes missing principals.
            logger.warning("deep_hunt auto-provisioning failed for target %s", target_id, exc_info=True)

    if req.mission_profile == "target_hunt":
        # Seed the hunt with DAST-residue / application-graph leads (auth-boundary edges and
        # producer->consumer object flows persisted from prior scans) so the loop investigates
        # unexplained residue rather than re-verifying findings the scanner already reported.
        # The observation ranks with require_residue=True, so without these leads the ranked
        # board is empty and the planner degrades to generic scanning. Best-effort: the graph
        # only exists after a prior scan, and seeding must never block a launch.
        try:
            await generate_application_graph_hypotheses(
                str(target_id),
                created_by=f"hunt_launch:{req.created_by or 'operator'}",
            )
        except Exception:
            logger.warning("Hunt graph residue seeding failed for target %s", target_id, exc_info=True)
        try:
            # The graph is often empty until a two-user resource-map scan runs; the endpoint
            # inventory always has surface, so seed BOLA/mass-assignment leads from it too.
            await generate_endpoint_inventory_hypotheses(
                str(target_id),
                created_by=f"hunt_launch:{req.created_by or 'operator'}",
            )
        except Exception:
            logger.warning("Hunt inventory residue seeding failed for target %s", target_id, exc_info=True)

    create_request = ResearchEpisodeRequest(
        target_id=str(target_id),
        objective=objective,
        planner={
            "kind": _research_planner_kind(planner_mode),
            "mode": planner_mode,
            "created_by": req.created_by,
            "launch_intensity": req.intensity,
            "dedupe_launch": not req.force_new,
            # Server-authored marker used by the campaign-only active-slot uniqueness index. It
            # intentionally does not constrain legacy/manual mission campaigns.
            "campaign_autopilot": bool(req.campaign_id),
            # Opt-in ReAct hunt loop (only meaningful with the server AI provider).
            "agent_loop": bool(req.agent_loop and planner_mode == "configured_ai"),
        },
        execution_mode=launch_profile["execution_mode"],
        max_risk_tier=launch_profile["max_risk_tier"],
        allowed_families=allowed_families,
        max_steps=max_steps,
        budget_limits=budget_limits,
        approval_receipt_id=req.approval_receipt_id,
        campaign_id=req.campaign_id,
        subject_type=req.subject_type,
        subject_id=str(subject_uuid),
        mission_profile=req.mission_profile,
        created_by=req.created_by,
        autopilot=autopilot_enabled,
    )
    try:
        detail = await create_research_episode(create_request)
    except asyncpg.UniqueViolationError:
        # A concurrent identical one-click launch won the partial unique index race. Reuse its
        # durable mission instead of creating duplicate work.
        if req.force_new:
            raise
        async with db_pool.acquire() as conn:
            existing = await conn.fetchrow(
                """
                SELECT * FROM research_episodes
                WHERE target_id=$1
                  AND planner->'mission'->>'profile'=$2
                  AND planner->'mission'->'subject'->>'type'=$3
                  AND planner->'mission'->'subject'->>'id'=$4
                  AND execution_mode=$5
                  AND planner->>'launch_intensity'=$6
                  AND planner->>'dedupe_launch'='true'
                  AND status NOT IN ('completed','cancelled','failed','budget_exhausted','blocked')
                ORDER BY created_at DESC LIMIT 1
                """,
                target_id,
                req.mission_profile,
                req.subject_type,
                str(subject_uuid),
                launch_profile["execution_mode"],
                req.intensity,
            )
            if not existing:
                raise
            return await _reuse_research_launch_episode(
                conn,
                existing=existing,
                req=req,
                launch_profile=launch_profile,
                target_id=target_id,
                target_url=target_url,
            )
    detail["reused"] = False
    detail["ui_path"] = f"/deep-hunt?episode_id={detail['episode']['id']}"
    return detail


@app.post("/research/campaigns/launch")
async def launch_research_campaign(req: ResearchCampaignLaunchRequest):
    """Launch a durable sequence of autonomous episodes from minimal operator input."""
    target_uuid = _uuid_or_400(req.target_id, "target id")
    planner_mode = _normalize_research_planner_mode(
        req.planner_mode,
        default=_normalize_research_planner_mode(
            _load_effective_automation_settings().get("default_research_planner_mode"),
        ),
    )
    if planner_mode == "configured_ai" and not _research_configured_planner_ready():
        raise HTTPException(
            status_code=409,
            detail="Stored-provider planning was selected, but no AI provider is configured",
        )
    unsupported_families = sorted({
        str(item).strip().lower() for item in req.allowed_families if str(item).strip()
    } - RESEARCH_CAMPAIGN_FAMILIES)
    if unsupported_families:
        raise HTTPException(
            status_code=400,
            detail=f"Unsupported autonomous research families: {', '.join(unsupported_families)}",
        )
    requested_families = list(dict.fromkeys(
        str(item).strip().lower() for item in req.allowed_families if str(item).strip()
    ))
    gated_campaign = RESEARCH_LAUNCH_PROFILES[req.intensity]["execution_mode"] == "gated"
    if gated_campaign and "allowed_families" in req.model_fields_set and not requested_families:
        raise HTTPException(
            status_code=400,
            detail="At least one vulnerability family is required for a gated research campaign",
        )
    if gated_campaign and "allowed_families" not in req.model_fields_set:
        requested_families = list(_research_intensity_campaign_families(req.intensity))
    if gated_campaign:
        requested_families = _validate_research_intensity_families(req.intensity, requested_families)
    deadline = datetime.now(timezone.utc) + timedelta(hours=req.duration_hours)
    metadata = {
        "autonomous_research": {
            "intensity": req.intensity,
            "planner_mode": planner_mode,
            "agent_loop": bool(req.agent_loop and planner_mode == "configured_ai"),
            "deadline_at": deadline.isoformat(),
            "max_episodes": req.max_episodes,
            "budget_limits": _research_campaign_budget_limits(
                req.intensity, req.max_episodes, req.budget_limits,
            ),
            "preflight_budget_used": _research_normalize_budget_used({}),
            "budget_used": _research_normalize_budget_used({}),
            "remaining_budget": _research_campaign_budget_limits(
                req.intensity, req.max_episodes, req.budget_limits,
            ),
            "approval_receipt_id": req.approval_receipt_id,
            "objective": req.objective,
            "allowed_families": requested_families,
            "require_all_requested_families": "allowed_families" in req.model_fields_set,
            "effective_families": [],
            "episodes_started": 0,
            "preflight_state": "pending" if gated_campaign else "not_required",
            "preflight_attempts": 0,
            "preflight_scan_id": None,
            "last_paused_episode_id": None,
            "last_error": None,
        }
    }
    async with db_pool.acquire() as conn:
        target = await conn.fetchrow("SELECT id, url FROM targets WHERE id=$1 AND is_active=true", target_uuid)
        if not target:
            raise HTTPException(status_code=404, detail="Active target not found")
        campaign = await conn.fetchrow(
            """
            INSERT INTO campaigns (
                name, objective, campaign_type, target_id, target_scope, risk_tier,
                planner, status, metadata_json, created_by
            ) VALUES ($1,$2,'autonomous_research',$3,$4::jsonb,$5,$6::jsonb,'paused',$7::jsonb,$8)
            RETURNING *
            """,
            f"Autonomous research: {urllib.parse.urlparse(str(target['url'])).hostname}"[:200],
            req.objective or "Continuously find and verify net-new security weaknesses until the campaign ceiling is reached.",
            target_uuid,
            json.dumps({"target_id": str(target_uuid), "url": str(target["url"])}),
            RESEARCH_LAUNCH_PROFILES[req.intensity]["max_risk_tier"],
            json.dumps({
                "kind": _research_planner_kind(planner_mode),
                "mode": planner_mode,
                "campaign": True,
            }),
            json.dumps(metadata),
            req.created_by,
        )
    campaign_id = str(campaign["id"])
    campaign_requirements = _research_family_readiness_requirements(
        set(requested_families),
        gated=gated_campaign,
    )
    if req.intensity == "deep_hunt" and campaign_requirements["primary_credentials"]:
        try:
            provisioning = await _research_maybe_auto_provision_principals(
                target_uuid,
                approval_receipt_id=req.approval_receipt_id,
                created_by=req.created_by,
                require_second_user=bool(campaign_requirements["second_user"]),
            )
            logger.info(
                "deep_hunt campaign principal bootstrap for target %s: %s",
                target_uuid,
                provisioning.get("action"),
            )
        except Exception:
            # Readiness remains fail-closed and will surface the precise credential blocker.
            logger.warning(
                "deep_hunt campaign auto-provisioning failed for target %s",
                target_uuid,
                exc_info=True,
            )
    repair = await _research_campaign_self_repair(campaign_id)
    readiness = repair.get("readiness") if isinstance(repair.get("readiness"), dict) else {}
    if not readiness.get("ready"):
        repaired_campaign = repair.get("campaign") or _public_campaign_row(campaign)
        preflight_scan_id = repair.get("scan_id") or (
            ((repaired_campaign.get("metadata_json") or {}).get("autonomous_research") or {}).get("preflight_scan_id")
        )
        return {
            "campaign": repaired_campaign,
            "episode": None,
            "readiness": readiness,
            "preflight": {
                "action": repair.get("action"),
                "scan_id": preflight_scan_id,
                "status": "queued" if preflight_scan_id else repair.get("action"),
            },
            "ui_path": f"/scans/{preflight_scan_id}" if preflight_scan_id else "/deep-hunt",
        }
    async with db_pool.acquire() as conn:
        await _materialize_research_invariant_hypotheses(conn, campaign["target_id"])
        current_campaign = await conn.fetchrow("SELECT * FROM campaigns WHERE id=$1", campaign["id"])
        budget = await _research_campaign_budget_snapshot(conn, current_campaign)
        episode_budget_limits = _research_campaign_episode_budget_limits(req.intensity, budget["remaining"])
        current_payload = row_to_dict(current_campaign)
        current_metadata = _decode_json_value(current_payload.get("metadata_json")) or {}
        current_config = (
            current_metadata.get("autonomous_research")
            if isinstance(current_metadata.get("autonomous_research"), dict)
            else {}
        )
        current_config.update({
            "budget_limits": budget["limits"],
            "budget_used": budget["used"],
            "remaining_budget": budget["remaining"],
            "effective_families": list(
                (readiness.get("surface") or {}).get("executable_families") or []
            ),
        })
        current_metadata["autonomous_research"] = current_config
        campaign = await conn.fetchrow(
            "UPDATE campaigns SET status=$2, metadata_json=$3::jsonb, updated_at=NOW() WHERE id=$1 RETURNING *",
            campaign["id"],
            "active" if _research_campaign_episode_budget_available(episode_budget_limits) else "paused",
            json.dumps(current_metadata, default=str),
        )
    if not _research_campaign_episode_budget_available(episode_budget_limits):
        return {
            "campaign": _public_campaign_row(campaign),
            "episode": None,
            "readiness": readiness,
            "stop_reason": "campaign_budget_exhausted",
            "ui_path": "/deep-hunt",
        }
    try:
        episode = await launch_research_episode(ResearchLaunchRequest(
            subject_type="target",
            subject_id=str(target_uuid),
            mission_profile="target_hunt",
            intensity=req.intensity,
            approval_receipt_id=req.approval_receipt_id,
            planner_mode=planner_mode,
            autopilot=planner_mode == "configured_ai",
            force_new=True,
            created_by=req.created_by,
            campaign_id=campaign_id,
            objective_override=req.objective,
            allowed_families_override=list(
                (readiness.get("surface") or {}).get("executable_families") or []
            ),
            budget_limits_override=episode_budget_limits,
            agent_loop=bool(req.agent_loop and planner_mode == "configured_ai"),
        ))
    except asyncpg.UniqueViolationError:
        # Finding 2: the campaign supervisor's 30s tick raced this launch and already started episode #1
        # (the partial unique index on the active-campaign episode fired). That is the desired outcome,
        # not a failure -- adopt the running episode instead of pausing the campaign and returning 500.
        async with db_pool.acquire() as conn:
            existing = await conn.fetchrow(
                "SELECT id FROM research_episodes WHERE campaign_id=$1 ORDER BY created_at ASC LIMIT 1",
                campaign["id"],
            )
            updated = await conn.fetchrow(
                """
                UPDATE campaigns SET
                    metadata_json=jsonb_set(metadata_json, '{autonomous_research,episodes_started}', '1'::jsonb, true),
                    updated_at=NOW() WHERE id=$1 RETURNING *
                """,
                campaign["id"],
            )
            detail = await _research_episode_detail(conn, str(existing["id"])) if existing else {}
        episode = detail.get("episode") if isinstance(detail, dict) else None
        return {
            "campaign": _public_campaign_row(updated),
            "episode": episode,
            "ui_path": (episode or {}).get("ui_path") or (f"/research/episodes/{existing['id']}" if existing else None),
            "note": "campaign_supervisor_started_first_episode",
        }
    except Exception as exc:
        async with db_pool.acquire() as conn:
            await conn.execute(
                """
                UPDATE campaigns SET status='paused',
                    metadata_json=jsonb_set(metadata_json, '{autonomous_research,last_error}', to_jsonb($2::text), true),
                    updated_at=NOW() WHERE id=$1
                """,
                campaign["id"], str(exc)[:500],
            )
        raise
    async with db_pool.acquire() as conn:
        updated = await conn.fetchrow(
            """
            UPDATE campaigns SET
                metadata_json=jsonb_set(metadata_json, '{autonomous_research,episodes_started}', '1'::jsonb, true),
                updated_at=NOW() WHERE id=$1 RETURNING *
            """,
            campaign["id"],
        )
    return {"campaign": _public_campaign_row(updated), "episode": episode, "ui_path": episode.get("ui_path")}


_CAMPAIGN_MAX_CONSECUTIVE_BLOCKED = 3


async def _record_campaign_blocker(
    conn,
    campaign_id: Any,
    *,
    kind: str,
    episode_id: str | None = None,
    detail: str | None = None,
) -> None:
    """Append a durable, bounded blocker to a campaign (escalate-don't-block).

    Blockers are advisory context surfaced in the campaign report so an operator can see why the loop
    had to skip or terminate work -- without the campaign having to stop and wait for an answer.
    """
    row = await conn.fetchrow("SELECT metadata_json FROM campaigns WHERE id=$1", campaign_id)
    if not row:
        return
    metadata = _decode_json_value(row["metadata_json"]) or {}
    config = metadata.get("autonomous_research") if isinstance(metadata.get("autonomous_research"), dict) else {}
    existing = config.get("blockers") if isinstance(config.get("blockers"), list) else []
    blocker = {
        "kind": str(kind)[:80],
        "episode_id": str(episode_id) if episode_id else None,
        "detail": str(detail)[:300] if detail else None,
        "at": datetime.now(timezone.utc).isoformat(),
    }
    blockers = [*existing, blocker][-20:]
    await conn.execute(
        """
        UPDATE campaigns
        SET metadata_json=jsonb_set(metadata_json, '{autonomous_research,blockers}', $2::jsonb, true),
            updated_at=NOW()
        WHERE id=$1
        """,
        campaign_id, json.dumps(blockers),
    )


def _research_campaign_terminal_needs_review(
    config: dict[str, Any], latest_episode_id: Any, latest_status: Any,
) -> bool:
    """Return true once per failed/blocked/cancelled terminal episode until operator resume."""
    episode_id = str(latest_episode_id or "")
    return bool(
        episode_id
        and str(latest_status or "") in {"blocked", "failed"}
        and str(config.get("last_paused_episode_id") or "") != episode_id
    )


async def _continue_autonomous_research_campaigns() -> int:
    """Start the next episode for active campaigns with no non-terminal episode."""
    # D2: reap stuck non-terminal episodes so their campaign becomes visible to the chaining/completion
    # logic below. An episode waiting on operator input, or left in a planning state after the autopilot
    # breaker disabled it (3 consecutive failures) with an expired lease, would otherwise count as
    # "active" forever -- freezing the whole campaign (it never even reaches the deadline/ceiling check).
    # Force it terminal ('blocked'); the terminal-review branch then records a blocker and chains a fresh
    # episode (escalate-don't-block). The lease/autopilot guards avoid racing an actively-planning runner.
    async with db_pool.acquire() as conn:
        await conn.execute(
            """
            UPDATE research_episodes e SET
                status='blocked',
                stop_reason=COALESCE(e.stop_reason, CASE WHEN e.status='awaiting_input'
                    THEN 'operator_input_requested' ELSE 'autopilot_disabled_after_failures' END),
                autopilot_error=COALESCE(e.autopilot_error, 'reaped_by_campaign_supervisor'),
                updated_at=NOW()
            FROM campaigns c
            WHERE e.campaign_id=c.id
              AND c.campaign_type='autonomous_research' AND c.status='active'
              AND e.status NOT IN ('completed','cancelled','failed','budget_exhausted','blocked')
              AND (
                  e.status='awaiting_input'
                  OR (e.status IN ('awaiting_planner','awaiting_observation')
                      AND e.autopilot_enabled=false
                      AND COALESCE(c.metadata_json->'autonomous_research'->>'planner_mode',
                                   e.planner->>'mode', 'configured_ai') = 'configured_ai'
                      AND (e.lease_expires_at IS NULL OR e.lease_expires_at < NOW()))
              )
            """
        )
    async with db_pool.acquire() as conn:
        rows = await conn.fetch(
            """
            SELECT c.*, COUNT(re.id)::int AS episode_count,
                   (ARRAY_AGG(re.id ORDER BY re.created_at DESC)
                       FILTER (WHERE re.id IS NOT NULL))[1] AS latest_episode_id,
                   (ARRAY_AGG(re.status ORDER BY re.created_at DESC)
                       FILTER (WHERE re.id IS NOT NULL))[1] AS latest_episode_status
            FROM campaigns c
            LEFT JOIN research_episodes re ON re.campaign_id=c.id
            WHERE c.campaign_type='autonomous_research' AND c.status='active'
              AND NOT EXISTS (
                  SELECT 1 FROM research_episodes active
                  WHERE active.campaign_id=c.id
                    AND active.status NOT IN ('completed','cancelled','failed','budget_exhausted','blocked')
              )
            GROUP BY c.id ORDER BY c.updated_at ASC LIMIT 5
            """
        )
    started = 0
    for row in rows:
        payload = row_to_dict(row)
        metadata = _decode_json_value(payload.get("metadata_json")) or {}
        config = metadata.get("autonomous_research") if isinstance(metadata.get("autonomous_research"), dict) else {}
        try:
            deadline = datetime.fromisoformat(str(config.get("deadline_at") or "").replace("Z", "+00:00"))
            if deadline.tzinfo is None:
                deadline = deadline.replace(tzinfo=timezone.utc)
        except (TypeError, ValueError):
            deadline = datetime.now(timezone.utc)
        count = int(payload.get("episode_count") or 0)
        try:
            maximum = max(1, min(100, int(config.get("max_episodes") or 1)))
        except (TypeError, ValueError):
            maximum = 1
        if deadline <= datetime.now(timezone.utc) or count >= maximum:
            async with db_pool.acquire() as conn:
                await conn.execute("UPDATE campaigns SET status='completed', updated_at=NOW() WHERE id=$1", row["id"])
            continue
        async with db_pool.acquire() as conn:
            current_campaign = await conn.fetchrow("SELECT * FROM campaigns WHERE id=$1", row["id"])
            readiness = await _research_campaign_readiness(conn, current_campaign)
        if not readiness.get("ready"):
            await _research_campaign_self_repair(row["id"])
            continue
        async with db_pool.acquire() as conn:
            invariant_hypotheses = await _materialize_research_invariant_hypotheses(
                conn,
                row["target_id"],
            )
            budget = await _research_campaign_budget_snapshot(conn, current_campaign)
            episode_budget_limits = _research_campaign_episode_budget_limits(
                str(config.get("intensity") or "deep_hunt"),
                budget["remaining"],
            )
            latest_metadata = _decode_json_value(current_campaign.get("metadata_json")) or {}
            latest_config = (
                latest_metadata.get("autonomous_research")
                if isinstance(latest_metadata.get("autonomous_research"), dict)
                else {}
            )
            latest_config.update({
                "preflight_state": "completed",
                "preflight_scan_id": str((readiness.get("preflight_scan") or {}).get("id") or latest_config.get("preflight_scan_id") or "") or None,
                "readiness": readiness,
                "surface_after_preflight": readiness.get("surface") or {},
                "invariant_hypotheses_materialized": invariant_hypotheses,
                "budget_limits": budget["limits"],
                "budget_used": budget["used"],
                "remaining_budget": budget["remaining"],
                "effective_families": list(
                    (readiness.get("surface") or {}).get("executable_families") or []
                ),
            })
            latest_metadata["autonomous_research"] = latest_config
            if not _research_campaign_episode_budget_available(episode_budget_limits):
                latest_config["last_error"] = "campaign_budget_exhausted"
                latest_metadata["autonomous_research"] = latest_config
                await conn.execute(
                    "UPDATE campaigns SET status='completed', metadata_json=$2::jsonb, updated_at=NOW() WHERE id=$1",
                    row["id"],
                    json.dumps(latest_metadata, default=str),
                )
                continue
            await conn.execute(
                "UPDATE campaigns SET metadata_json=$2::jsonb, updated_at=NOW() WHERE id=$1",
                row["id"],
                json.dumps(latest_metadata, default=str),
            )
            refreshed_campaign = await conn.fetchrow("SELECT * FROM campaigns WHERE id=$1", row["id"])
            yield_metrics = await _research_campaign_yield_metrics(conn, refreshed_campaign)
            if yield_metrics.get("stop_recommended"):
                latest_config["yield"] = yield_metrics
                latest_config["last_error"] = yield_metrics.get("stop_reason")
                latest_metadata["autonomous_research"] = latest_config
                await conn.execute(
                    "UPDATE campaigns SET status='paused', metadata_json=$2::jsonb, updated_at=NOW() WHERE id=$1",
                    row["id"],
                    json.dumps(latest_metadata, default=str),
                )
                continue
        latest_episode_id = str(payload.get("latest_episode_id") or "")
        latest_status = str(payload.get("latest_episode_status") or "")
        # An operator cancelling THIS episode is an explicit stop, not a recoverable planner failure --
        # do NOT relaunch active testing ~30s later. Pause the campaign; an explicit resume restarts it.
        if latest_status == "cancelled" and str(config.get("last_paused_episode_id") or "") != latest_episode_id:
            async with db_pool.acquire() as conn:
                await conn.execute(
                    """
                    UPDATE campaigns SET status='paused',
                        metadata_json=jsonb_set(
                            jsonb_set(metadata_json, '{autonomous_research,last_paused_episode_id}', to_jsonb($2::text), true),
                            '{autonomous_research,last_error}', to_jsonb($3::text), true),
                        updated_at=NOW() WHERE id=$1
                    """,
                    row["id"], latest_episode_id,
                    "Latest research episode was cancelled by an operator; campaign paused (resume to continue)",
                )
            continue
        # Escalate-don't-block: a blocked/failed episode is recorded as a durable blocker and the campaign
        # keeps moving (a fresh episode is chained) so it stays autonomous. Only after several consecutive
        # unrecovered episodes do we pause for real operator review -- a systemic failure, not a dead end.
        from_review = False
        if _research_campaign_terminal_needs_review(config, latest_episode_id, latest_status):
            consecutive_blocked = int(config.get("consecutive_blocked") or 0) + 1
            async with db_pool.acquire() as conn:
                await _record_campaign_blocker(
                    conn, row["id"], kind=f"episode_{latest_status}", episode_id=latest_episode_id,
                )
                if consecutive_blocked >= _CAMPAIGN_MAX_CONSECUTIVE_BLOCKED:
                    await conn.execute(
                        """
                        UPDATE campaigns SET status='paused',
                            metadata_json=jsonb_set(jsonb_set(jsonb_set(metadata_json,
                                '{autonomous_research,last_paused_episode_id}', to_jsonb($2::text), true),
                                '{autonomous_research,consecutive_blocked}', to_jsonb($3::int), true),
                                '{autonomous_research,last_error}', to_jsonb($4::text), true),
                            updated_at=NOW() WHERE id=$1
                        """,
                        row["id"], latest_episode_id, consecutive_blocked,
                        f"Paused after {consecutive_blocked} consecutive unrecovered episodes (last ended {latest_status})",
                    )
                    continue
                await conn.execute(
                    """
                    UPDATE campaigns SET
                        metadata_json=jsonb_set(jsonb_set(metadata_json,
                            '{autonomous_research,last_paused_episode_id}', to_jsonb($2::text), true),
                            '{autonomous_research,consecutive_blocked}', to_jsonb($3::int), true),
                        updated_at=NOW() WHERE id=$1
                    """,
                    row["id"], latest_episode_id, consecutive_blocked,
                )
            from_review = True
        try:
            effective_families = list(
                (readiness.get("surface") or {}).get("executable_families") or []
            )
            planner_mode = str(config.get("planner_mode") or "configured_ai")
            await launch_research_episode(ResearchLaunchRequest(
                subject_type="target", subject_id=str(row["target_id"]), mission_profile="target_hunt",
                intensity=str(config.get("intensity") or "deep_hunt"),
                approval_receipt_id=config.get("approval_receipt_id"),
                planner_mode=planner_mode,
                autopilot=planner_mode == "configured_ai",
                force_new=True,
                created_by="research_campaign_supervisor", campaign_id=str(row["id"]),
                objective_override=config.get("objective"),
                allowed_families_override=effective_families,
                budget_limits_override=episode_budget_limits,
                agent_loop=bool(config.get("agent_loop")),
            ))
        except asyncpg.UniqueViolationError:
            continue
        except Exception as exc:
            async with db_pool.acquire() as conn:
                await conn.execute(
                    """
                    UPDATE campaigns SET status='paused',
                        metadata_json=jsonb_set(metadata_json, '{autonomous_research,last_error}', to_jsonb($2::text), true),
                        updated_at=NOW() WHERE id=$1
                    """,
                    row["id"], str(exc)[:500],
                )
            continue
        async with db_pool.acquire() as conn:
            # Reset the consecutive-blocked counter when chaining after a clean (non-review) episode;
            # keep the just-incremented value when retrying after a recorded blocker.
            await conn.execute(
                """
                UPDATE campaigns SET
                    metadata_json=jsonb_set(
                        jsonb_set(
                            CASE WHEN $3 THEN metadata_json
                                 ELSE jsonb_set(metadata_json, '{autonomous_research,consecutive_blocked}', '0'::jsonb, true) END,
                            '{autonomous_research,episodes_started}', to_jsonb($2::int), true),
                        '{autonomous_research,last_error}', 'null'::jsonb, true),
                    updated_at=NOW() WHERE id=$1
                """,
                row["id"], count + 1, from_review,
            )
        started += 1
    return started


@app.post("/research/campaigns/{campaign_id}/control")
async def control_research_campaign(campaign_id: str, req: ResearchCampaignControlRequest):
    campaign_uuid = _uuid_or_400(campaign_id, "campaign id")
    async with db_pool.acquire() as conn:
        campaign = await conn.fetchrow(
            "SELECT * FROM campaigns WHERE id=$1 AND campaign_type='autonomous_research'",
            campaign_uuid,
        )
        if not campaign:
            raise HTTPException(status_code=404, detail="Autonomous research campaign not found")
        current_status = str(campaign.get("status") or "")
        if req.action == "resume" and current_status in {"completed", "cancelled"}:
            raise HTTPException(
                status_code=409,
                detail=f"A {current_status} research campaign cannot be resumed; launch a new campaign",
            )
        campaign_metadata = _decode_json_value(campaign.get("metadata_json")) or {}
        research_config = (
            campaign_metadata.get("autonomous_research")
            if isinstance(campaign_metadata.get("autonomous_research"), dict)
            else {}
        )
        preflight_scan_id = str(research_config.get("preflight_scan_id") or "") or None
        active_rows = await conn.fetch(
            """
            SELECT id FROM research_episodes WHERE campaign_id=$1
              AND status NOT IN ('completed','cancelled','failed','budget_exhausted','blocked')
            """,
            campaign_uuid,
        )
        status = {"pause": "paused", "resume": "active", "cancel": "cancelled"}[req.action]
        reset_exhausted_preflight = bool(
            req.action == "resume"
            and current_status == "paused"
            and research_config.get("last_error") == "authenticated_coverage_readiness_exhausted"
        )
        if reset_exhausted_preflight:
            history = (
                list(research_config.get("preflight_history") or [])
                if isinstance(research_config.get("preflight_history"), list)
                else []
            )
            history.append({
                "scan_id": preflight_scan_id,
                "attempts": int(research_config.get("preflight_attempts") or 0),
                "state": research_config.get("preflight_state"),
                "reason": research_config.get("last_error"),
                "reset_at": datetime.now(timezone.utc).isoformat(),
                "reset_by": req.created_by,
            })
            research_config.update({
                "preflight_state": "pending",
                "preflight_scan_id": None,
                "preflight_job_id": None,
                "preflight_claim_id": None,
                "preflight_started_at": None,
                "preflight_attempts": 0,
                "preflight_resume_resets": int(research_config.get("preflight_resume_resets") or 0) + 1,
                "preflight_history": history[-10:],
                "readiness": {},
                "last_error": None,
            })
            campaign_metadata["autonomous_research"] = research_config
            updated = await conn.fetchrow(
                """
                UPDATE campaigns SET status=$2, metadata_json=$3::jsonb,
                    updated_at=NOW() WHERE id=$1 RETURNING *
                """,
                campaign_uuid,
                status,
                json.dumps(campaign_metadata, default=str),
            )
        elif req.action == "resume" and current_status == "paused" and research_config.get("last_error"):
            resume_history = (
                list(research_config.get("resume_history") or [])
                if isinstance(research_config.get("resume_history"), list)
                else []
            )
            resume_history.append({
                "reason": str(research_config.get("last_error"))[:500],
                "resumed_at": datetime.now(timezone.utc).isoformat(),
                "resumed_by": req.created_by,
            })
            research_config.update({
                "last_error": None,
                "resume_history": resume_history[-20:],
            })
            campaign_metadata["autonomous_research"] = research_config
            updated = await conn.fetchrow(
                """
                UPDATE campaigns SET status=$2, metadata_json=$3::jsonb,
                    updated_at=NOW() WHERE id=$1 RETURNING *
                """,
                campaign_uuid,
                status,
                json.dumps(campaign_metadata, default=str),
            )
        else:
            updated = await conn.fetchrow(
                "UPDATE campaigns SET status=$2, updated_at=NOW() WHERE id=$1 RETURNING *",
                campaign_uuid, status,
            )
        if req.action in {"pause", "resume"} and active_rows:
            resume_autopilot = (
                req.action == "resume"
                and str(research_config.get("planner_mode") or "configured_ai") == "configured_ai"
            )
            await conn.execute(
                """
                UPDATE research_episodes SET autopilot_enabled=$2,
                    autopilot_error=CASE WHEN $2 THEN NULL ELSE autopilot_error END,
                    updated_at=NOW() WHERE id=ANY($1::uuid[])
                """,
                [row["id"] for row in active_rows], resume_autopilot,
            )
    cancelled: list[str] = []
    cancelled_preflight_scan_ids: list[str] = []
    failed_preflight_scan_ids: list[str] = []
    if req.action == "cancel":
        for row in active_rows:
            try:
                await cancel_research_episode(str(row["id"]))
                cancelled.append(str(row["id"]))
            except HTTPException as exc:
                if exc.status_code not in {404, 409}:
                    raise
        if preflight_scan_id:
            try:
                await cancel_scan(preflight_scan_id)
                cancelled_preflight_scan_ids.append(preflight_scan_id)
            except HTTPException as exc:
                # A terminal scan is already safely stopped; only surface genuine cancellation failures.
                if exc.status_code not in {404, 409}:
                    failed_preflight_scan_ids.append(preflight_scan_id)
            except Exception:
                failed_preflight_scan_ids.append(preflight_scan_id)
    return {
        "campaign": _public_campaign_row(updated),
        "action": req.action,
        "affected_episode_ids": [str(row["id"]) for row in active_rows],
        "cancelled_episode_ids": cancelled,
        "cancelled_preflight_scan_ids": cancelled_preflight_scan_ids,
        "failed_preflight_scan_ids": failed_preflight_scan_ids,
    }


@app.get("/research/episodes")
async def list_research_episodes(
    target_id: Optional[str] = Query(None),
    campaign_id: Optional[str] = Query(None),
    status: Optional[str] = Query(None),
    limit: int = Query(20, ge=1, le=100),
):
    params: list[Any] = []
    clauses: list[str] = []
    if target_id:
        params.append(_uuid_or_400(target_id, "target id"))
        clauses.append(f"target_id=${len(params)}")
    if campaign_id:
        params.append(_uuid_or_400(campaign_id, "campaign id"))
        clauses.append(f"campaign_id=${len(params)}")
    if status:
        params.append(status)
        clauses.append(f"status=${len(params)}")
    params.append(limit)
    where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
    async with db_pool.acquire() as conn:
        rows = await conn.fetch(
            f"SELECT * FROM research_episodes{where} ORDER BY created_at DESC LIMIT ${len(params)}",
            *params,
        )
    return {"episodes": [_public_research_episode_row(row) for row in rows], "count": len(rows)}


@app.get("/research/episodes/{episode_id}")
async def get_research_episode(episode_id: str):
    async with db_pool.acquire() as conn:
        return await _research_episode_detail(conn, episode_id)


# Hard cap on observations per episode. POST /observe consumes no budget, so bound
# unbounded row growth (each observation row is itself size-bounded). 500 is generous
# relative to the <=25-step episode budget.
RESEARCH_MAX_OBSERVATIONS_PER_EPISODE = 500


@app.post("/research/episodes/{episode_id}/observe")
async def refresh_research_observation(episode_id: str, req: ResearchObservationRequest):
    async with db_pool.acquire() as conn:
        async with conn.transaction():
            row = await _research_episode_or_404(conn, episode_id, for_update=True)
            episode = _public_research_episode_row(row)
            if episode.get("terminal") or episode.get("cancel_requested"):
                raise HTTPException(status_code=409, detail="Terminal or cancelled episodes cannot create observations")
            if str(episode.get("status") or "") not in {"awaiting_planner", "awaiting_input"}:
                raise HTTPException(status_code=409, detail="Episode is waiting for an action result")
            if row.get("lease_owner") and row.get("lease_expires_at"):
                lease_active = await conn.fetchval("SELECT $1::timestamptz > NOW()", row["lease_expires_at"])
                if lease_active:
                    raise HTTPException(status_code=409, detail="Episode planner currently holds the observation lease")
            observation_count = await conn.fetchval(
                "SELECT COUNT(*) FROM research_observations WHERE episode_id=$1", row["id"]
            )
            if observation_count >= RESEARCH_MAX_OBSERVATIONS_PER_EPISODE:
                raise HTTPException(
                    status_code=429,
                    detail=f"Research episode observation limit reached ({RESEARCH_MAX_OBSERVATIONS_PER_EPISODE})",
                )
            observation = await _build_research_observation(
                conn,
                row,
                previous_command_result_id=req.previous_command_result_id,
            )
        return {"observation": observation, **(await _research_episode_detail(conn, episode_id))}


@app.post("/research/episodes/{episode_id}/cancel")
async def cancel_research_episode(episode_id: str):
    scan_ids: list[str] = []
    workflow_ids: list[str] = []
    cancelled_retest_ids: list[str] = []
    continuing_retest_ids: list[str] = []
    async with db_pool.acquire() as conn:
        async with conn.transaction():
            row = await _research_episode_or_404(conn, episode_id, for_update=True)
            episode = _public_research_episode_row(row)
            if episode.get("terminal"):
                return await _research_episode_detail(conn, episode_id)
            scan_rows = await conn.fetch(
                """
                SELECT DISTINCT s.id AS scan_id
                FROM research_decisions rd
                LEFT JOIN command_results cr ON cr.id = rd.command_result_id
                JOIN scans s ON (
                    s.id = cr.scan_id
                    OR s.options->>'research_dispatch_correlation' = (
                        'research_episode:' || rd.episode_id::text || ':decision:' || rd.id::text
                    )
                )
                WHERE rd.episode_id=$1 AND s.status IN ('pending','queued','running')
                """,
                row["id"],
            )
            scan_ids = [str(item["scan_id"]) for item in scan_rows if item["scan_id"]]
            workflow_rows = await conn.fetch(
                """
                SELECT DISTINCT rd.action->'parameters'->>'workflow_id' AS workflow_id
                FROM research_decisions rd
                WHERE rd.episode_id=$1 AND rd.status='dispatching'
                  AND rd.action->>'command'='experiment.workflow'
                """,
                row["id"],
            )
            workflow_ids = [
                str(item["workflow_id"]) for item in workflow_rows if item.get("workflow_id")
            ]
            retest_rows = await conn.fetch(
                """
                SELECT DISTINCT fv.id, fv.status, fv.finding_id
                FROM research_decisions rd
                LEFT JOIN command_results cr ON cr.id=rd.command_result_id
                JOIN finding_verifications fv ON (
                    fv.id::text=cr.result_json->>'retest_id'
                    OR fv.requested_by=(
                        'research_episode:' || rd.episode_id::text || ':decision:' || rd.id::text
                    )
                )
                WHERE rd.episode_id=$1 AND fv.status IN ('queued','running')
                """,
                row["id"],
            )
            queued_retest_ids = [item["id"] for item in retest_rows if item["status"] == "queued"]
            continuing_retest_ids = [str(item["id"]) for item in retest_rows if item["status"] == "running"]
            if queued_retest_ids:
                cancelled = await conn.fetch(
                    """
                    UPDATE finding_verifications
                    SET status='cancelled', result_status='cancelled', verdict='cancelled',
                        verdict_reason='Parent research episode cancelled before retest started.',
                        completed_at=NOW(), updated_at=NOW()
                    WHERE id=ANY($1::uuid[]) AND status='queued'
                    RETURNING id
                    """,
                    queued_retest_ids,
                )
                cancelled_retest_ids = [str(item["id"]) for item in cancelled]
                cancelled_finding_ids = [
                    item["finding_id"] for item in retest_rows
                    if item["status"] == "queued" and str(item["id"]) in set(cancelled_retest_ids)
                ]
                if cancelled_finding_ids:
                    await conn.execute(
                        """
                        UPDATE findings
                        SET last_verification_status='cancelled', updated_at=NOW()
                        WHERE id=ANY($1::uuid[])
                        """,
                        cancelled_finding_ids,
                    )
            await conn.execute(
                """
                UPDATE research_episodes
                SET cancel_requested=true, status='cancelled', stop_reason='operator_cancelled',
                    autopilot_enabled=false, lease_expires_at=NULL,
                    version=version+1, updated_at=NOW()
                WHERE id=$1
                """,
                row["id"],
            )
            await conn.execute(
                """
                UPDATE research_decisions
                SET status='blocked', validation_errors=(validation_errors || '["episode_cancelled"]'::jsonb),
                    updated_at=NOW()
                WHERE episode_id=$1 AND status='dispatching'
                """,
                row["id"],
            )
            await _record_research_event(
                conn,
                row["id"],
                event_type="episode_cancelled",
                status="cancelled",
                summary="Research episode cancelled by operator",
                details={
                    "linked_scan_ids": scan_ids,
                    "linked_workflow_ids": workflow_ids,
                    "cancelled_retest_ids": cancelled_retest_ids,
                    "continuing_retest_ids": continuing_retest_ids,
                },
            )
    cancelled_scans: list[str] = []
    cancelled_workflow_ids: list[str] = []
    completed_workflow_ids: list[str] = []
    for workflow_id in workflow_ids:
        event = _active_workflow_cancellations.get(workflow_id)
        if event:
            event.set()
            cancelled_workflow_ids.append(workflow_id)
        else:
            completed_workflow_ids.append(workflow_id)
    cancel_failed_scan_ids: list[str] = []
    for scan_id in scan_ids:
        try:
            await cancel_scan(scan_id)
            cancelled_scans.append(scan_id)
        except Exception:
            cancel_failed_scan_ids.append(scan_id)
            continue
    async with db_pool.acquire() as conn:
        if cancel_failed_scan_ids:
            await _record_research_event(
                conn,
                _uuid_or_400(episode_id, "episode id"),
                event_type="scan_cancellation_failed",
                status="failed",
                summary="One or more linked scans could not be cancelled",
                details={"scan_ids": cancel_failed_scan_ids},
            )
        detail = await _research_episode_detail(conn, episode_id)
    detail["cancelled_scan_ids"] = cancelled_scans
    detail["cancelled_workflow_ids"] = cancelled_workflow_ids
    detail["completed_workflow_ids"] = completed_workflow_ids
    detail["cancel_failed_scan_ids"] = cancel_failed_scan_ids
    detail["cancelled_retest_ids"] = cancelled_retest_ids
    detail["continuing_retest_ids"] = continuing_retest_ids
    return detail


@app.post("/research/episodes/{episode_id}/settle")
async def settle_research_episode(episode_id: str):
    """Attach a completed async scan/retest result without polling or planning another step."""
    async with db_pool.acquire() as conn:
        async with conn.transaction():
            row = await _research_episode_or_404(conn, episode_id, for_update=True)
            episode = _public_research_episode_row(row)
            if episode.get("terminal"):
                return {"settled": False, "reason": "episode_terminal", **(await _research_episode_detail(conn, episode_id))}
            if str(episode.get("status") or "") != "awaiting_observation":
                return {"settled": False, "reason": "episode_not_waiting", **(await _research_episode_detail(conn, episode_id))}
            settlement = await _settle_research_awaiting_observation(conn, row)
        return {**settlement, **(await _research_episode_detail(conn, episode_id))}


@app.post("/research/episodes/{episode_id}/decisions")
async def submit_research_decision(episode_id: str, req: ResearchDecisionRequest):
    dispatch_request: ArsenalExecuteRequest | None = None
    decision_id: uuid.UUID | None = None
    cost: dict[str, Any] | None = None
    normalized: dict[str, Any] = {}
    mode = "shadow"
    idempotency_key = ""
    inferable_request = False

    async with db_pool.acquire() as conn:
        async with conn.transaction():
            episode_row = await _research_episode_or_404(conn, episode_id, for_update=True)
            episode = _public_research_episode_row(episode_row)
            if episode.get("terminal") or episode.get("cancel_requested"):
                raise HTTPException(status_code=409, detail="Research episode is terminal or cancelled")
            if (
                str((req.planner or {}).get("created_by") or "") == "server_autopilot"
                and not episode.get("autopilot_enabled")
            ):
                raise HTTPException(status_code=409, detail="Research autopilot was paused before dispatch")
            if episode.get("status") != "awaiting_planner":
                raise HTTPException(status_code=409, detail="Research episode is not awaiting a planner decision")
            observation_row = await conn.fetchrow(
                "SELECT * FROM research_observations WHERE id=$1 AND episode_id=$2",
                _uuid_or_400(req.observation_id, "observation id"),
                episode_row["id"],
            )
            if not observation_row or str(episode.get("current_observation_id") or "") != str(observation_row["id"]):
                raise HTTPException(status_code=409, detail="Decision must reference the current episode observation")
            observation = _public_research_observation_row(observation_row)
            observation_pack = observation.get("observation_pack") or {}
            raw = req.model_dump(mode="json", exclude={"planner", "model_tokens_used", "execute", "idempotency_key"})
            binding_errors = _research_canonicalize_action_shape(raw)
            # Freelance experiments: the planner often reasons up a hypothesis from the discovered
            # surface and designs a valid experiment for it, but omits hypothesis_id (the lead is not
            # on the seeded board). Bind a matching ranked lead, or create a tracked planner-derived
            # hypothesis, so valid experiments are not rejected for provenance alone.
            # Live create-MA materialization is deliberately deferred to the already-authorized
            # Arsenal dispatch. Decision validation, idempotency checks, semantic policy, and budget
            # checks are pure with respect to the target; rejected or replayed decisions cannot send
            # registration requests or hold this row lock across target I/O.
            binding_errors.extend(
                await _research_autobind_hypothesis(conn, episode, raw, observation_pack)
            )
            catalog = _research_command_catalog()
            normalized, errors, warnings, cost = _research_validate_decision(
                raw,
                episode=episode,
                observation={
                    "id": str(observation_row["id"]),
                    "context_hash": observation_row["context_hash"],
                    "proposable_commands": observation_pack.get("proposable_commands") or [],
                },
                command_catalog=catalog,
            )
            errors.extend(binding_errors)
            if _contains_forbidden_context_key(req.planner):
                errors.append("planner_metadata_contains_secret_field")
            model_limit = int((episode.get("budget_limits") or {}).get("model_tokens") or 0)
            model_used = int((episode.get("budget_used") or {}).get("model_tokens") or 0)
            if model_used + req.model_tokens_used > model_limit:
                errors.append("budget_exhausted:model_tokens")
            campaign_budget = None
            if episode.get("campaign_id"):
                campaign_row = await conn.fetchrow(
                    "SELECT * FROM campaigns WHERE id=$1",
                    _optional_uuid(episode.get("campaign_id")),
                )
                if campaign_row:
                    campaign_budget = await _research_campaign_budget_snapshot(conn, campaign_row)
            command = catalog.get(normalized.get("action", {}).get("command") or "")
            if normalized.get("decision") == "execute_action" and command:
                launch_intensity = str((episode.get("planner") or {}).get("launch_intensity") or "")
                if launch_intensity and int((episode.get("remaining_budget") or {}).get("steps") or 0) <= 1:
                    errors.append("budget_reserved_for_conclusion")
                params, parameter_errors = await _research_prepare_action(conn, episode, normalized, command)
                normalized["action"]["parameters"] = params
                errors.extend(parameter_errors)
                cost = _research_parameterized_action_cost(command, params, cost)
                errors.extend(_research_budget_violations(
                    episode.get("budget_limits"), episode.get("budget_used"), cost
                ))
                if campaign_budget:
                    aggregate_cost = {**(cost or {}), "model_tokens": req.model_tokens_used}
                    errors.extend(_research_campaign_budget_violations(
                        campaign_budget["limits"], campaign_budget["used"], aggregate_cost,
                    ))
                if await _research_is_consecutive_duplicate_action(
                    conn,
                    episode_row["id"],
                    normalized.get("action") or {},
                ):
                    errors.append("repeated_action_without_state_change")
                errors.extend(await _research_semantic_policy_violations(
                    conn,
                    episode,
                    normalized.get("action") or {},
                ))
                mode = str(episode.get("execution_mode") or "read_only")
                if mode == "read_only" and command.get("name") in GATED_RESEARCH_COMMANDS:
                    errors.append("gated_command_forbidden_in_read_only_episode")
                if mode == "gated" and command.get("name") in GATED_RESEARCH_COMMANDS:
                    if not episode.get("approval_receipt_id") or not episode.get("scope_receipt_id"):
                        errors.append("episode_approval_missing")
                    if not _ai_ops_execute_enabled():
                        errors.append("execution_feature_disabled")
            elif campaign_budget:
                errors.extend(_research_campaign_budget_violations(
                    campaign_budget["limits"], campaign_budget["used"],
                    {"model_tokens": req.model_tokens_used},
                ))
            if normalized.get("decision") == "request_input":
                inferable_request = _research_requested_input_is_in_observation(
                    normalized.get("requested_input"),
                    observation_pack,
                )
                if inferable_request:
                    errors.append("operator_input_unnecessary:use_selected_hypothesis_contract")
            errors = list(dict.fromkeys(errors))
            warnings = list(dict.fromkeys(warnings))
            key_material = {
                "episode_id": str(episode_row["id"]),
                "observation_id": str(observation_row["id"]),
                "client_key": req.idempotency_key,
                "decision": None if req.idempotency_key else normalized,
            }
            idempotency_key = _research_canonical_hash(key_material)
            existing = await conn.fetchrow("SELECT * FROM research_decisions WHERE idempotency_key=$1", idempotency_key)
            if existing:
                return {
                    "accepted": existing["status"] not in {"rejected", "blocked", "failed"},
                    "idempotent_replay": True,
                    "decision": _public_research_decision_row(existing),
                    **(await _research_episode_detail(conn, episode_id)),
                }
            decision_sequence = int(await conn.fetchval(
                "SELECT COALESCE(MAX(sequence), 0) + 1 FROM research_decisions WHERE episode_id=$1",
                episode_row["id"],
            ))
            status = "rejected" if errors else "accepted"
            hypothesis_id = _optional_uuid(normalized.get("hypothesis_id"))
            if hypothesis_id:
                bound_hypothesis = await conn.fetchrow(
                    "SELECT source, metadata_json FROM hypotheses WHERE id=$1 AND target_id=$2",
                    hypothesis_id,
                    episode_row["target_id"],
                )
                if not bound_hypothesis:
                    errors.append("hypothesis_not_found_for_target")
                    status = "rejected"
                    hypothesis_id = None
                elif normalized.get("action", {}).get("command") in {"experiment.http_diff", "experiment.workflow"}:
                    metadata = _decode_json_value(bound_hypothesis.get("metadata_json")) or {}
                    source = str(bound_hypothesis.get("source") or "").strip().lower()
                    residue_backed = source in {"app_graph", "benchmark", "dast", "scan", "scanner", "asm"} or bool(
                        metadata.get("unexplained_residue") or metadata.get("graph_edge_id")
                        or metadata.get("edge_id") or metadata.get("source_scan_id")
                        or metadata.get("baseline_scan_id")
                    )
                    if not residue_backed:
                        errors.append("experiment_hypothesis_must_be_backed_by_dast_residue_or_graph")
                        status = "rejected"
            decision_row = await conn.fetchrow(
                """
                INSERT INTO research_decisions (
                    episode_id, observation_id, sequence, decision_version, planner,
                    decision_type, hypothesis_id, action, expected_signal, falsifier,
                    reason, confidence, requested_input, stop_reason, status,
                    validation_errors, validation_warnings, policy_result, idempotency_key
                ) VALUES ($1,$2,$3,$4,$5::jsonb,$6,$7,$8::jsonb,$9,$10,$11,$12,$13,$14,$15,$16::jsonb,$17::jsonb,$18::jsonb,$19)
                RETURNING *
                """,
                episode_row["id"], observation_row["id"], decision_sequence,
                RESEARCH_DECISION_VERSION, json.dumps(_bounded_research_payload(req.planner or {})),
                normalized.get("decision"), hypothesis_id, json.dumps(normalized.get("action") or {}),
                normalized.get("expected_signal"), normalized.get("falsifier"), normalized.get("reason"),
                normalized.get("confidence") or 0, normalized.get("requested_input"), normalized.get("stop_reason"),
                status, json.dumps(errors), json.dumps(warnings),
                json.dumps({"execution_mode": mode, "model_tokens_used": req.model_tokens_used}), idempotency_key,
            )
            decision_id = decision_row["id"]
            used = _research_normalize_budget_used(episode.get("budget_used") or {})
            used["model_tokens"] += req.model_tokens_used
            if errors:
                next_status = "budget_exhausted" if any(item.startswith("budget_exhausted:") for item in errors) else "awaiting_planner"
                await conn.execute(
                    """
                    UPDATE research_episodes
                    SET status=$2, current_decision_id=$3, budget_used=$4::jsonb,
                        stop_reason=CASE WHEN $2='budget_exhausted' THEN 'budget_exhausted' ELSE stop_reason END,
                        version=version+1, updated_at=NOW()
                    WHERE id=$1
                    """,
                    episode_row["id"], next_status, decision_id, json.dumps(used),
                )
                await _record_research_event(
                    conn, episode_row["id"], event_type="decision_rejected", status=status,
                    summary="Planner decision rejected by deterministic policy", observation_id=observation_row["id"],
                    decision_id=decision_id, details={"validation_errors": errors},
                )
                if inferable_request and next_status == "awaiting_planner":
                    # Keep the same episode and turn the rejected request into a
                    # durable tool-style observation.  The next planner turn sees
                    # both the concrete contract and why operator escalation was
                    # unnecessary; the campaign supervisor never gets an
                    # ``awaiting_input`` episode to reap/restart.
                    refreshed = await conn.fetchrow(
                        "SELECT * FROM research_episodes WHERE id=$1",
                        episode_row["id"],
                    )
                    await _build_research_observation(
                        conn,
                        refreshed,
                        previous_result={
                            "execution_blocked_reason": "operator_input_resolved_from_observation",
                            "result": {
                                "status": "context_available",
                                "reason": "Use selected_hypothesis_contracts; no operator input is required.",
                            },
                        },
                        next_status="awaiting_planner",
                    )
                return {
                    "accepted": False,
                    "decision": _public_research_decision_row(decision_row),
                    **(await _research_episode_detail(conn, episode_id)),
                }

            if normalized["decision"] == "stop":
                used["steps"] += 1
                await conn.execute(
                    """
                    UPDATE research_episodes
                    SET status='completed', current_decision_id=$2, step_count=step_count+1,
                        budget_used=$3::jsonb, stop_reason=$4, version=version+1, updated_at=NOW()
                    WHERE id=$1
                    """,
                    episode_row["id"], decision_id, json.dumps(used), normalized.get("stop_reason"),
                )
                await _record_research_event(
                    conn, episode_row["id"], event_type="episode_stopped", status="completed",
                    summary=normalized.get("stop_reason") or "Planner stopped episode", observation_id=observation_row["id"],
                    decision_id=decision_id,
                )
                return {"accepted": True, "decision": _public_research_decision_row(decision_row), **(await _research_episode_detail(conn, episode_id))}

            if normalized["decision"] == "request_input":
                used["steps"] += 1
                await conn.execute(
                    """
                    UPDATE research_episodes
                    SET status='awaiting_input', current_decision_id=$2, step_count=step_count+1,
                        budget_used=$3::jsonb, requested_input=$4, version=version+1, updated_at=NOW()
                    WHERE id=$1
                    """,
                    episode_row["id"], decision_id, json.dumps(used), normalized.get("requested_input"),
                )
                await _record_research_event(
                    conn, episode_row["id"], event_type="input_requested", status="awaiting_input",
                    summary=normalized.get("requested_input") or "Planner requested operator input",
                    observation_id=observation_row["id"], decision_id=decision_id,
                )
                return {"accepted": True, "decision": _public_research_decision_row(decision_row), **(await _research_episode_detail(conn, episode_id))}

            command = catalog[normalized["action"]["command"]]
            effective_cost = dict(cost or {})
            if mode == "shadow" or not req.execute:
                effective_cost["active_actions"] = 0
                effective_cost["requests"] = 0
                effective_cost["seconds"] = 0
            effective_cost["model_tokens"] = req.model_tokens_used
            await conn.execute(
                """
                UPDATE research_episodes
                SET status='dispatching', current_decision_id=$2, version=version+1, updated_at=NOW()
                WHERE id=$1
                """,
                episode_row["id"], decision_id,
            )
            await conn.execute(
                "UPDATE research_decisions SET status='dispatching', policy_result=$2::jsonb, updated_at=NOW() WHERE id=$1",
                decision_id,
                json.dumps({"execution_mode": mode, "cost_reserved": effective_cost, "model_tokens_used": req.model_tokens_used}),
            )
            await _record_research_event(
                conn, episode_row["id"], event_type="decision_accepted", status="dispatching",
                summary=f"Accepted one-step action {command['name']}", observation_id=observation_row["id"],
                decision_id=decision_id, details={"command": command["name"], "cost_reserved": effective_cost},
            )
            cost = effective_cost
            if mode != "shadow" and req.execute:
                confirmations: list[str] = []
                if episode.get("approval_receipt_id"):
                    approval_row = await conn.fetchrow("SELECT * FROM approval_receipts WHERE id=$1", episode["approval_receipt_id"])
                    if approval_row:
                        confirmations = list(_public_approval_receipt_row(approval_row).get("confirmations") or [])
                dispatch_request = ArsenalExecuteRequest(
                    command=command["name"],
                    parameters=normalized["action"]["parameters"],
                    execute=True,
                    confirmations=confirmations,
                    approval_receipt_id=str(episode.get("approval_receipt_id") or "") or None,
                    scope_receipt_id=str(episode.get("scope_receipt_id") or "") or None,
                    created_by=f"research_episode:{episode_id}:decision:{decision_id}",
                    campaign_id=str(episode.get("campaign_id") or "") or None,
                    research_hypothesis_id=str(normalized.get("hypothesis_id") or "") or None,
                )

    if dispatch_request is None:
        dispatch_result: dict[str, Any] = {
            "command": normalized.get("action", {}).get("command"),
            "dispatched": False,
            "dry_run": True,
            "execution_blocked_reason": "shadow_mode" if mode == "shadow" else "execute_not_requested",
        }
    else:
        try:
            dispatch_result = await _arsenal_execute_detached(dispatch_request)
        except HTTPException as exc:
            dispatch_result = {
                "command": dispatch_request.command,
                "dispatched": False,
                "dry_run": False,
                "execution_blocked_reason": "arsenal_rejected",
                "error": _bounded_research_payload(exc.detail),
            }
        except Exception as exc:
            dispatch_result = {
                "command": dispatch_request.command,
                "dispatched": False,
                "dry_run": False,
                "execution_blocked_reason": "arsenal_error",
                "error": type(exc).__name__,
            }

    command_result = dispatch_result.get("command_result") if isinstance(dispatch_result.get("command_result"), dict) else {}
    command_result_id = command_result.get("id") or dispatch_result.get("operation_id")
    dispatched = bool(dispatch_result.get("dispatched"))
    async_ref = _research_dispatch_async_ref(dispatch_result) if dispatched else None
    decision_status = "dispatching" if async_ref else ("completed" if dispatched or mode == "shadow" else "blocked")
    cancelled_during_settlement = False
    settlement_already_recovered = False
    compensation_scan_id: str | None = None
    compensation_error: str | None = None
    async with db_pool.acquire() as conn:
        async with conn.transaction():
            episode_row = await _research_episode_or_404(conn, episode_id, for_update=True)
            episode = _public_research_episode_row(episode_row)
            same_decision = str(episode.get("current_decision_id") or "") == str(decision_id)
            if str(episode.get("status") or "") == "awaiting_observation" and same_decision:
                # Stale-dispatch recovery already attached/settled the durable receipt. The
                # original slow adapter may still return; make that return idempotent.
                await conn.execute(
                    """
                    UPDATE research_decisions
                    SET command_result_id=COALESCE(command_result_id, $2), updated_at=NOW()
                    WHERE id=$1
                    """,
                    decision_id,
                    _optional_uuid(command_result_id),
                )
                settlement_already_recovered = True
            elif episode.get("cancel_requested") or str(episode.get("status") or "") != "dispatching" or not same_decision:
                settled_cost = dict(cost or {})
                if not dispatched and mode != "shadow":
                    settled_cost["active_actions"] = 0
                    settled_cost["requests"] = 0
                    settled_cost["seconds"] = 0
                used = _research_apply_cost(episode.get("budget_used") or {}, settled_cost)
                await conn.execute(
                    """
                    UPDATE research_decisions
                    SET status='blocked', command_result_id=$2, policy_result=$3::jsonb, updated_at=NOW()
                    WHERE id=$1
                    """,
                    decision_id,
                    _optional_uuid(command_result_id),
                    json.dumps({
                        "cancelled_before_settlement": True,
                        "async_work": async_ref,
                        "cost_settled": settled_cost,
                        "observation_summary": _bounded_research_payload(dispatch_result),
                    }),
                )
                await conn.execute(
                    """
                    UPDATE research_episodes
                    SET step_count=step_count+1, budget_used=$2::jsonb,
                        version=version+1, updated_at=NOW()
                    WHERE id=$1
                    """,
                    episode_row["id"],
                    json.dumps(used),
                )
                if async_ref and async_ref.get("kind") == "finding_retest":
                    cancelled_finding_id = await conn.fetchval(
                        """
                        UPDATE finding_verifications
                        SET status='cancelled', result_status='cancelled', verdict='cancelled',
                            verdict_reason='Research episode cancelled during dispatch.',
                            completed_at=NOW(), updated_at=NOW()
                        WHERE id=$1 AND status='queued'
                        RETURNING finding_id
                        """,
                        _optional_uuid(async_ref.get("id")),
                    )
                    if cancelled_finding_id:
                        await conn.execute(
                            """
                            UPDATE findings f
                            SET last_verification_status='cancelled', updated_at=NOW()
                            WHERE f.id=$1
                              AND NOT EXISTS (
                                  SELECT 1 FROM finding_verifications active
                                  WHERE active.finding_id=f.id AND active.status IN ('queued','running')
                              )
                              AND (
                                  SELECT latest.id FROM finding_verifications latest
                                  WHERE latest.finding_id=f.id
                                  ORDER BY latest.created_at DESC LIMIT 1
                              )=$2
                            """,
                            cancelled_finding_id,
                            _optional_uuid(async_ref.get("id")),
                        )
                elif async_ref and async_ref.get("kind") == "scan":
                    compensation_scan_id = str(async_ref.get("id"))
                await _record_research_event(
                    conn,
                    episode_row["id"],
                    event_type="dispatch_compensated",
                    status="cancelled",
                    summary="Recorded compensation for work returned after its dispatch lease was no longer current",
                    decision_id=decision_id,
                    command_result_id=command_result_id,
                    details={
                        "async_work": async_ref,
                        "cost_settled": settled_cost,
                        "episode_status": episode.get("status"),
                        "same_decision": same_decision,
                    },
                )
                cancelled_during_settlement = True
            else:
                settled_cost = dict(cost or {})
                if not dispatched and mode != "shadow":
                    # A rejected/busy/no-op adapter may consume a planner step, but it did not spend
                    # target requests, active-action capacity, or execution time.
                    settled_cost["active_actions"] = 0
                    settled_cost["requests"] = 0
                    settled_cost["seconds"] = 0
                used = _research_apply_cost(episode.get("budget_used") or {}, settled_cost)
                next_step = int(episode.get("step_count") or 0) + 1
                max_steps = int((episode.get("budget_limits") or {}).get("steps") or 1)
                terminal = next_step >= max_steps
                next_status = "budget_exhausted" if terminal else "awaiting_planner"
                stop_reason = "max_steps_reached_without_conclusion" if terminal else None
                policy_result = {
                    "execution_mode": mode,
                    "dispatched": dispatched,
                    "execution_blocked_reason": dispatch_result.get("execution_blocked_reason"),
                    "cost_settled": settled_cost,
                    "async_work": async_ref,
                    "observation_summary": _bounded_research_payload(dispatch_result),
                }
                await conn.execute(
                    """
                    UPDATE research_decisions
                    SET status=$2, command_result_id=$3, policy_result=$4::jsonb, updated_at=NOW()
                    WHERE id=$1
                    """,
                    decision_id, decision_status, _optional_uuid(command_result_id), json.dumps(policy_result),
                )
                await conn.execute(
                    """
                    UPDATE research_episodes
                    SET status='awaiting_observation', step_count=$2, budget_used=$3::jsonb,
                        stop_reason=COALESCE($4, stop_reason), version=version+1, updated_at=NOW()
                    WHERE id=$1
                    """,
                    episode_row["id"], next_step, json.dumps(used), stop_reason,
                )
                await _record_research_hypothesis_outcome(
                    conn,
                    decision_id=decision_id,
                    command_result=command_result,
                )
                if async_ref:
                    await _record_research_event(
                        conn, episode_row["id"], event_type="action_waiting", status="awaiting_observation",
                        summary=f"Waiting for {async_ref['kind']} {async_ref['id']}",
                        decision_id=decision_id, command_result_id=command_result_id,
                        details={"dispatched": True, "async_work": async_ref},
                    )
                else:
                    await _record_research_event(
                        conn, episode_row["id"], event_type="action_observed", status=decision_status,
                        summary=f"Observed {normalized.get('action', {}).get('command')}: {'dispatched' if dispatched else 'not dispatched'}",
                        decision_id=decision_id, command_result_id=command_result_id,
                        details={"dispatched": dispatched, "blocked_reason": dispatch_result.get("execution_blocked_reason")},
                    )
                    refreshed = await conn.fetchrow("SELECT * FROM research_episodes WHERE id=$1", episode_row["id"])
                    await _build_research_observation(
                        conn,
                        refreshed,
                        previous_result=dispatch_result,
                        previous_command_result_id=command_result_id,
                        next_status=next_status,
                    )
    if cancelled_during_settlement and compensation_scan_id:
        try:
            await cancel_scan(compensation_scan_id)
        except Exception as exc:
            compensation_error = f"scan cancellation failed ({type(exc).__name__})"
        async with db_pool.acquire() as conn:
            async with conn.transaction():
                await _record_research_event(
                    conn,
                    _uuid_or_400(episode_id, "episode id"),
                    event_type="dispatch_compensation_result",
                    status="failed" if compensation_error else "cancelled",
                    summary=(
                        "Failed to cancel scan queued during episode cancellation"
                        if compensation_error
                        else "Cancelled scan queued during episode cancellation"
                    ),
                    decision_id=decision_id,
                    command_result_id=command_result_id,
                    details={"scan_id": compensation_scan_id, "error": compensation_error},
                )
    async with db_pool.acquire() as conn:
        detail = await _research_episode_detail(conn, episode_id)
    if settlement_already_recovered:
        return {
            "accepted": True,
            "recovered_settlement": True,
            "dispatched": dispatched,
            "decision_id": str(decision_id),
            **detail,
        }
    if cancelled_during_settlement:
        return {
            "accepted": False,
            "dispatch_compensation_scan_id": compensation_scan_id,
            "dispatch_compensation_error": compensation_error,
            **detail,
        }
    return {"accepted": True, "dispatched": dispatched, "decision_id": str(decision_id), **detail}




def _research_canonicalize_hypothesis_binding(raw: dict[str, Any]) -> list[str]:
    """Move a misplaced experiment hypothesis binding into decision provenance.

    The structured response schema exposes ``hypothesis_id`` at decision level, while
    command parameter schemas intentionally do not. Some providers still duplicate it
    inside ``action.parameters``. Canonicalize the unambiguous case without weakening
    the command contract, and reject conflicting bindings instead of guessing.
    """
    action = raw.get("action") if isinstance(raw.get("action"), dict) else {}
    parameters = action.get("parameters") if isinstance(action.get("parameters"), dict) else {}
    if "hypothesis_id" not in parameters:
        return []
    nested = str(parameters.pop("hypothesis_id") or "").strip()
    action["parameters"] = parameters
    raw["action"] = action
    if not nested:
        return []
    top_level = str(raw.get("hypothesis_id") or "").strip()
    if top_level and top_level != nested:
        return ["hypothesis_id_conflict"]
    raw["hypothesis_id"] = nested
    return []


def _research_canonicalize_workflow_wrapper(raw: dict[str, Any]) -> list[str]:
    """Unwrap a provider-added ``workflow`` envelope without weakening policy.

    Some structured-output providers copy the named experiment template under
    ``action.parameters.workflow`` while keeping server-routing fields beside it.
    The envelope has no authority of its own, so an unambiguous object can be
    flattened safely. Conflicting duplicate fields remain a hard rejection.
    """
    action = raw.get("action") if isinstance(raw.get("action"), dict) else {}
    if str(action.get("command") or "") != "experiment.workflow":
        return []
    parameters = action.get("parameters") if isinstance(action.get("parameters"), dict) else {}
    if "workflow" not in parameters:
        return []
    nested = parameters.pop("workflow")
    if isinstance(nested, str):
        text = nested.strip()
        try:
            decoded = json.loads(text)
        except (TypeError, ValueError, json.JSONDecodeError):
            decoded = None
        if isinstance(decoded, (dict, list)):
            nested = decoded
        else:
            # A few providers use ``workflow`` as a redundant workflow-id alias.
            # Preserve the UUID under the declared field and let the normal command
            # schema reject any genuinely missing steps/assertions.
            try:
                nested_workflow_id = str(uuid.UUID(text))
            except (TypeError, ValueError):
                action["parameters"] = parameters
                raw["action"] = action
                return ["workflow_wrapper_must_be_object"]
            existing_workflow_id = str(parameters.get("workflow_id") or "").strip()
            if existing_workflow_id and existing_workflow_id != nested_workflow_id:
                action["parameters"] = parameters
                raw["action"] = action
                return ["workflow_parameter_conflict:workflow_id"]
            parameters["workflow_id"] = nested_workflow_id
            action["parameters"] = parameters
            raw["action"] = action
            return []
    if isinstance(nested, list):
        if not nested or not all(isinstance(step, dict) for step in nested):
            action["parameters"] = parameters
            raw["action"] = action
            return ["workflow_wrapper_must_be_object"]
        nested = {"steps": nested}
    if not isinstance(nested, dict):
        action["parameters"] = parameters
        raw["action"] = action
        return ["workflow_wrapper_must_be_object"]
    errors: list[str] = []
    for key, value in nested.items():
        if key in parameters and parameters[key] not in (None, "", [], {}):
            if parameters[key] != value:
                errors.append(f"workflow_parameter_conflict:{str(key)[:80]}")
            continue
        parameters[key] = value
    action["parameters"] = parameters
    raw["action"] = action
    return errors


def _research_canonicalize_experiment_steps_alias(raw: dict[str, Any]) -> list[str]:
    """Map the readable ``operations`` alias back to the declared ``steps`` field.

    Campaign memory used this label to describe prior work. Providers sometimes copy
    it literally into the next experiment. The alias carries no extra authority and
    every resulting step still passes the normal command schema, scope, method, body,
    restoration, and secret-field checks.
    """
    action = raw.get("action") if isinstance(raw.get("action"), dict) else {}
    if str(action.get("command") or "") not in _RESEARCH_EXPERIMENT_DEDUPE_COMMANDS:
        return []
    parameters = action.get("parameters") if isinstance(action.get("parameters"), dict) else {}
    if "operations" not in parameters:
        return []
    operations = parameters.pop("operations")
    if not isinstance(operations, list) or not operations or not all(
        isinstance(step, dict) for step in operations
    ):
        action["parameters"] = parameters
        raw["action"] = action
        return ["experiment_operations_must_be_step_list"]
    existing_steps = parameters.get("steps")
    if existing_steps not in (None, [], {}) and existing_steps != operations:
        action["parameters"] = parameters
        raw["action"] = action
        return ["experiment_steps_conflict"]
    parameters["steps"] = operations
    action["parameters"] = parameters
    raw["action"] = action
    return []


def _research_canonicalize_action_shape(raw: dict[str, Any]) -> list[str]:
    errors = _research_canonicalize_workflow_wrapper(raw)
    errors.extend(_research_canonicalize_experiment_steps_alias(raw))
    errors.extend(_research_canonicalize_hypothesis_binding(raw))
    return list(dict.fromkeys(errors))


async def _research_autobind_hypothesis(
    conn, episode: dict[str, Any], raw: dict[str, Any], observation_pack: dict[str, Any],
) -> list[str]:
    """Bind an experiment decision to a tracked hypothesis, mutating ``raw`` in place.

    An ``experiment.*`` decision must carry a hypothesis_id (for provenance + promotion), but the
    planner frequently omits it. Bind an existing ranked live-surface lead of the same complete
    vulnerability identity. Freelance routes fail closed: a model cannot manufacture the residue
    that later authorizes its own active experiment.
    """
    action = raw.get("action") if isinstance(raw.get("action"), dict) else {}
    command = str(action.get("command") or "")
    if command not in {"experiment.workflow", "experiment.http_diff"}:
        return []
    params = action.get("parameters") if isinstance(action.get("parameters"), dict) else {}
    # The workflow runtime requires a UUID workflow_id; the planner routinely omits it or invents a
    # non-UUID (the templates don't show it), which the arsenal rejects as "Invalid workflow id".
    # Supply a valid one so the experiment is dispatched instead of blocked.
    if command == "experiment.workflow":
        try:
            uuid.UUID(str(params.get("workflow_id") or "").strip())
        except ValueError:
            params["workflow_id"] = str(uuid.uuid4())
            action["parameters"] = params
    family = family_proof.canonical_family(params.get("proof_family") or "workflow")
    route = None
    selected_step: dict[str, Any] = {}
    steps = [step for step in (params.get("steps") or []) if isinstance(step, dict)]
    preferred_labels: set[str] = set()
    preferred_predicates = {
        "bola": {"cross_principal_access"},
        "auth_bypass": {"unauthenticated_control"},
        "data_exposure": {"sensitive_value_present"},
        "mass_assignment": {"forbidden_field_accepted"},
        "access_control": {"forbidden_role_access"},
        "field_constraint": {"constraint_violation_persisted"},
        "workflow": {"transition_invariant_broken"},
    }.get(family, set())
    for assertion in (params.get("assertions") or []):
        if isinstance(assertion, dict) and assertion.get("predicate") in preferred_predicates:
            preferred_labels.update(str(assertion.get(key) or "") for key in ("step", "candidate") if assertion.get(key))
    def _in_preferred(step: dict[str, Any]) -> bool:
        return str(step.get("label") or "") in preferred_labels
    # For mutation-based families the vulnerability identity is the state-changing endpoint the
    # forbidden field is assigned to (the lead's POST/PUT/PATCH route), NOT the GET step an assertion
    # reads it back on. Binding on the read step derives (GET, /orders/all/{id}) and can never match a
    # (POST, /orders/{id}) mass_assignment lead -- the experiment_hypothesis_not_on_ranked_live_surface
    # rejection seen for grok's mass_assignment experiments. Prefer the mutation step for those families.
    mutation_family = family in {"mass_assignment", "field_constraint", "workflow"}
    def _is_state_changing(step: dict[str, Any]) -> bool:
        return str(step.get("method") or "").upper() in {"POST", "PUT", "PATCH", "DELETE"}
    def _mutation_binding_priority(step: dict[str, Any]) -> tuple[int, int, int]:
        label = str(step.get("label") or "").strip().lower()
        explicitly_mutating = bool(
            re.search(r"(?:^|[_-])(mutat|transition|violat|attack|candidate)", label)
        )
        return (
            0 if explicitly_mutating else 1,
            0 if _in_preferred(step) else 1,
            0 if str(step.get("checkpoint") or "").lower() == "mutation" else 1,
        )
    if mutation_family and any(_is_state_changing(step) for step in steps):
        ordered_steps = (
            sorted(
                (s for s in steps if _is_state_changing(s)),
                key=_mutation_binding_priority,
            )
            + [s for s in steps if not _is_state_changing(s)]
        )
    else:
        ordered_steps = [s for s in steps if _in_preferred(s)] + [s for s in steps if not _in_preferred(s)]
    for step in ordered_steps:
        if isinstance(step, dict) and step.get("path"):
            route = _canonical_vulnerability_route(step.get("path"))
            if route:
                selected_step = step
                break
    if not route:
        route = _canonical_vulnerability_route(params.get("route") or params.get("url"))
    method = str(selected_step.get("method") or params.get("method") or "GET").upper()
    target_id = str(episode.get("target_id") or "")
    if not target_id or not route:
        return ["experiment_hypothesis_route_missing"]
    assertion_predicates = [
        str(assertion.get("predicate"))
        for assertion in (params.get("assertions") or [])
        if isinstance(assertion, dict) and assertion.get("predicate")
    ]
    vulnerability_dimensions = _research_vulnerability_dimensions(
        params.get("proof_family") or family,
        params,
        selected_step,
        {"predicates": assertion_predicates},
    )
    candidate_key = _canonical_vulnerability_key(
        family=family,
        route=route,
        method=method,
        dimensions=vulnerability_dimensions,
    )
    if not candidate_key:
        return ["experiment_hypothesis_identity_incomplete"]
    # Bind only an existing ranked lead whose complete vulnerability identity matches.
    ranked = (observation_pack.get("current_surface") or {}).get("ranked_hypotheses") or []
    supplied_hypothesis_id = str(raw.get("hypothesis_id") or "").strip()
    if supplied_hypothesis_id:
        # An explicit hypothesis id is already the strongest provenance binding the planner can
        # provide.  The ranked board was filtered against the current live endpoint inventory, so
        # accept that exact row when the experiment still targets its canonical family + operation.
        # Do not require the action's derived dimensional hash to equal the stored lead's hash:
        # assertions and server-bound variable names legitimately refine those dimensions when the
        # planner turns a graph lead into a typed workflow (for example, a BOLA lead with
        # ``object_key=transaction_id`` becomes a four-step principal-variable workflow).  Requiring
        # complete hash equality made a visibly ranked lead impossible to execute and caused the
        # autopilot rejection loop seen in campaign 96f94c01-41dc-4917-a48c-6aa93ee5e0c2.
        for entry in ranked:
            hypothesis = entry.get("hypothesis") if isinstance(entry, dict) else None
            if not isinstance(hypothesis, dict) or str(hypothesis.get("id") or "") != supplied_hypothesis_id:
                continue
            contract = _research_hypothesis_experiment_contract(hypothesis)
            contract_family = family_proof.canonical_family(
                contract.get("family") or hypothesis.get("family")
            )
            contract_route = _canonical_vulnerability_route(contract.get("route"))
            contract_method = str(contract.get("method") or "").upper()
            if (
                contract_family != family
                or not contract_route
                or contract_route != route
                or (contract_method and contract_method != method)
            ):
                return ["experiment_hypothesis_not_on_ranked_live_surface"]
            raw["hypothesis_id"] = supplied_hypothesis_id
            return []
        # Size-compaction can drop ranked_hypotheses from the persisted pack while KEEPING the derived
        # selected_hypothesis_contracts (the authoritative leads the planner is explicitly told to use,
        # and which the compactor preserves as mandatory control data). Bind an explicit id against
        # those too, so a visibly-selected live lead stays executable even when the ranked board was
        # compacted away -- otherwise the gate rejects every experiment against an empty board, the
        # exact experiment_hypothesis_not_on_ranked_live_surface spin observed on crAPI.
        for contract in (observation_pack.get("selected_hypothesis_contracts") or []):
            if not isinstance(contract, dict) or str(contract.get("hypothesis_id") or "") != supplied_hypothesis_id:
                continue
            contract_route = _canonical_vulnerability_route(contract.get("route"))
            contract_method = str(contract.get("method") or "").upper()
            if (
                family_proof.canonical_family(contract.get("family")) != family
                or not contract_route
                or contract_route != route
                or (contract_method and contract_method != method)
            ):
                return ["experiment_hypothesis_not_on_ranked_live_surface"]
            raw["hypothesis_id"] = supplied_hypothesis_id
            return []
        # Compaction can drop BOTH the ranked board and the selected contracts from an oversized pack
        # (grok's large crAPI packs). The planner still legitimately references an id it read in an
        # earlier observation, so resolve it straight from the durable hypotheses table: bind only a
        # live, actionable lead on THIS target whose canonical family+route+method matches the
        # experiment -- the same identity check the board branches enforce, just DB-sourced when the
        # board was compacted away. Fail-closed: no such live lead -> reject.
        lead_uuid = _optional_uuid(supplied_hypothesis_id)
        target_uuid = _optional_uuid(target_id)
        if lead_uuid is not None and target_uuid is not None:
            row = await conn.fetchrow(
                """
                SELECT source, family, next_test_action, metadata_json
                FROM hypotheses
                WHERE id=$1 AND target_id=$2
                  AND status IN ('open','claimed','testing','supported')
                """,
                lead_uuid,
                target_uuid,
            )
            if row is not None:
                lead = {
                    "source": row.get("source"),
                    "family": row["family"],
                    "next_test_action": _decode_json_value(row["next_test_action"]),
                    "metadata_json": _decode_json_value(row["metadata_json"]),
                }
                contract = _research_hypothesis_experiment_contract(lead)
                contract_route = _canonical_vulnerability_route(contract.get("route"))
                contract_method = str(contract.get("method") or "").upper()
                live_operation = str(lead.get("source") or "").strip().lower() == "invariant"
                if not live_operation:
                    # Route-target the liveness lookup. A blanket LIMIT 2000 over a large inventory can
                    # omit the very endpoint being bound (e.g. POST /api/Users ranked ~900th), which
                    # wrongly rejected a live create lead. Prefix-filter to the lead's route first.
                    route_prefix = str(contract_route or "").split("/{id}")[0].rstrip("/")
                    endpoint_rows = await conn.fetch(
                        """
                        SELECT method, path
                        FROM target_endpoints
                        WHERE target_id=$1
                          AND COALESCE(test_status, '') <> 'gone'
                          AND COALESCE(last_http_status, 0) NOT IN (404, 410)
                          AND COALESCE(unreachable_streak, 0) < 2
                          AND ($2 = '' OR path LIKE $2 || '%')
                        LIMIT 2000
                        """,
                        target_uuid,
                        route_prefix,
                    )
                    live_operation = any(
                        _canonical_vulnerability_route(endpoint.get("path")) == contract_route
                        and (
                            not contract_method
                            or str(endpoint.get("method") or "GET").upper() == contract_method
                        )
                        for endpoint in endpoint_rows
                    )
                if (
                    family_proof.canonical_family(contract.get("family") or lead.get("family")) == family
                    and contract_route
                    and contract_route == route
                    and (not contract_method or contract_method == method)
                    and live_operation
                ):
                    raw["hypothesis_id"] = supplied_hypothesis_id
                    return []
        return ["experiment_hypothesis_not_on_ranked_live_surface"]

    # When the planner omitted the id, autobinding stays deliberately stricter: only an exact
    # complete vulnerability identity can select a hypothesis on its behalf.
    for entry in ranked:
        hypothesis = entry.get("hypothesis") if isinstance(entry, dict) else None
        if not isinstance(hypothesis, dict) or not hypothesis.get("id"):
            continue
        if family_proof.canonical_family(hypothesis.get("family")) != family:
            continue
        if _research_hypothesis_vulnerability_key(hypothesis) == candidate_key:
            raw["hypothesis_id"] = str(hypothesis["id"])
            return []
    # The exact dimensional hash legitimately diverges when the planner refines a sparse residue lead
    # into a typed workflow (extra assertions/variables). When the id was omitted, still bind to a
    # visibly ranked or selected lead of the SAME family+route+method: that is a real live-surface lead
    # the board showed the planner, not a manufactured route, so it meets the residue requirement (the
    # same match the supplied-id branch already accepts) without a brittle full-hash equality.
    for contract in (
        list(observation_pack.get("selected_hypothesis_contracts") or [])
        + [entry.get("hypothesis") for entry in ranked if isinstance(entry, dict)]
    ):
        if not isinstance(contract, dict):
            continue
        if family_proof.canonical_family(contract.get("family")) != family:
            continue
        if _canonical_vulnerability_route(contract.get("route")) != route:
            continue
        contract_method = str(contract.get("method") or "").upper()
        if contract_method and contract_method != method:
            continue
        bind_id = str(contract.get("hypothesis_id") or contract.get("id") or "").strip()
        if bind_id:
            raw["hypothesis_id"] = bind_id
            return []
    return ["experiment_hypothesis_not_on_ranked_live_surface"]


# Concrete, contract-valid workflow proof templates per promotable family. The planner copies the
# matching template and fills in real routes/objects/principals from the observation; keeping the
# checkpoints, assertion types, and predicates verbatim is what makes the proof both structurally
# valid (normalize_workflow) and server-corroborable. Every template is asserted valid in tests.


# Create-based mass-assignment: POST /collection overposts a privilege field; the created object is read
# back at /collection/${created_id} and the created objects are DELETE-cleaned. Restoration is the
# collection list (exists before creation and after cleanup). The proof binds the read-back to the
# created object via the extracted id (see workflow_experiment._create_object_readback).


_CREATE_MA_LOGIN_TOKENS = ("email", "mail", "login", "username", "user")
_CREATE_MA_SECRET_TOKENS = ("password", "passwd", "passphrase", "pwd", "secret", "pass")
_CREATE_MA_ID_ENVELOPES = ("data", "result", "item", "user", "record", "payload")


def _classify_create_field(name: str) -> str:
    """Universal field-name heuristic: is a create-body field a login, a secret, or something else.

    Uses only conventional field naming (email/password/...), never a target-specific fact.
    """
    low = re.sub(r"[^a-z0-9]+", "", str(name or "").lower())
    if any(token in low for token in _CREATE_MA_SECRET_TOKENS):
        return "secret"
    if any(token in low for token in _CREATE_MA_LOGIN_TOKENS):
        return "login"
    return "other"


def _discover_create_object_shape(response_json: Any) -> tuple[str | None, str] | None:
    """Locate a created object's envelope + id field in a real create response, universally.

    Returns (envelope_key_or_None, id_field) or None. Checks the root object then one level of common
    REST envelopes for an id-like scalar key -- so the created-id extract path is discovered, not guessed.
    """
    def _id_field(obj: dict[str, Any]) -> str | None:
        for key in obj:
            if str(key).lower() == "id" and not isinstance(obj[key], (dict, list)):
                return str(key)
        for key in obj:
            low = str(key).lower()
            if low.endswith("id") and not isinstance(obj[key], (dict, list)):
                return str(key)
        return None

    if not isinstance(response_json, dict):
        return None
    root_id = _id_field(response_json)
    if root_id:
        return (None, root_id)
    for env in _CREATE_MA_ID_ENVELOPES:
        nested = response_json.get(env)
        if isinstance(nested, dict):
            nested_id = _id_field(nested)
            if nested_id:
                return (env, nested_id)
    return None


def _create_mass_assignment_credentials() -> dict[str, str]:
    """Server-generated, unique-per-run throwaway credentials for a create-MA experiment.

    Never model-supplied (only their sha256 is persisted as principal_variable receipts). Two distinct
    logins so a unique-identifier constraint cannot collide across the control and mutate creates.
    """
    nonce = uuid.uuid4().hex
    return {
        "ctrl_login": f"shakerscan-ma-c-{nonce[:14]}@shakerscan-probe.test",
        "adm_login": f"shakerscan-ma-m-{nonce[14:28]}@shakerscan-probe.test",
        "reg_cred": "ShakerScan9!" + uuid.uuid4().hex[:12],
    }


def _inject_create_mass_assignment_credentials(
    principal_contexts: dict[str, dict[str, Any]], normalized: dict[str, Any],
) -> None:
    """Refresh server-generated create-MA credentials before EACH run of the two-run.

    A create with a unique-identifier constraint (e.g. a registration email) would collide on the
    replay if both runs reused one login, breaking the two-run. Fresh unique credentials per run keep
    it sound; the predicates, assertion shapes, and proof routes are identical across runs regardless
    of the concrete login. No-op for every non-create-based-mass_assignment workflow. Values are
    server-generated (never model-supplied); only their sha256 receipts persist.
    """
    if not _is_create_based_mass_assignment(normalized.get("proof_family"), normalized):
        return
    fresh = _create_mass_assignment_credentials()
    for binding in normalized.get("principal_variables") or []:
        ref = str(binding.get("ref") or "")
        if ref not in fresh:
            continue
        context = principal_contexts.setdefault(str(binding.get("principal") or "user1"), {})
        refs = context.get("captured_refs")
        if not isinstance(refs, dict):
            refs = {}
            context["captured_refs"] = refs
        refs[ref] = fresh[ref]


def _materialize_create_mass_assignment_workflow(
    *,
    collection_route: str,
    request_fields: str | None,
    forbidden_field: str,
    forbidden_value: str,
    envelope: str | None,
    id_field: str,
) -> dict[str, Any] | None:
    """Build a complete create-based mass_assignment workflow from a lead + discovered response shape.

    Universal: field roles come from name heuristics; extract/read-back paths from the discovered
    envelope. Requires a login-like field (a unique identifier, so the two independent creates do not
    collide) and a forbidden field; returns None otherwise rather than fabricate an unprovable workflow.
    """
    collection = "/" + str(collection_route or "").strip().strip("/")
    forbidden = str(forbidden_field or "").strip()
    fields = [f.strip() for f in str(request_fields or "").split(",") if f.strip()]
    roles = {f: _classify_create_field(f) for f in fields}
    if not forbidden or not any(role == "login" for role in roles.values()):
        return None
    id_path = f"$.{envelope}.{id_field}" if envelope else f"$.{id_field}"
    forbidden_path = f"$.{envelope}.{forbidden}" if envelope else f"$.{forbidden}"

    def _body(login_var: str, include_forbidden: bool) -> dict[str, Any]:
        body: dict[str, Any] = {}
        for field in fields:
            if field == forbidden:
                continue
            role = roles[field]
            body[field] = (
                "${%s}" % login_var if role == "login"
                else "${reg_cred}" if role == "secret"
                else "shakerscan-benign"
            )
        if include_forbidden:
            body[forbidden] = forbidden_value
        return body

    return {
        "proof_family": "mass_assignment",
        "objective": f"{forbidden}={forbidden_value} overposted on POST {collection} persists in the created object",
        "expected_signal": "the create succeeds and the created-object read-back shows the forbidden field, while a benign create does not",
        "falsifier": "the create fails, the forbidden field is rejected, or the read-back does not show it",
        "principal_variables": [
            {"name": "ctrl_login", "principal": "user1", "ref": "ctrl_login"},
            {"name": "adm_login", "principal": "user1", "ref": "adm_login"},
            {"name": "reg_cred", "principal": "user1", "ref": "reg_cred"},
        ],
        "steps": [
            {"label": "list_before", "kind": "http", "principal": "user1", "checkpoint": "before", "method": "GET", "path": collection},
            {"label": "control", "kind": "http", "principal": "user1", "checkpoint": "mutation", "method": "POST", "path": collection, "json_body": _body("ctrl_login", False), "extract": [{"name": "control_id", "source": "json", "path": id_path}]},
            {"label": "mutate", "kind": "http", "principal": "user1", "checkpoint": "mutation", "method": "POST", "path": collection, "json_body": _body("adm_login", True), "extract": [{"name": "created_id", "source": "json", "path": id_path}]},
            {"label": "control_verify", "kind": "http", "principal": "user1", "checkpoint": "action", "method": "GET", "path": collection + "/${control_id}", "select_json": [forbidden_path]},
            {"label": "verify", "kind": "http", "principal": "user1", "checkpoint": "action", "method": "GET", "path": collection + "/${created_id}", "select_json": [forbidden_path], "compare_to": "control_verify"},
            {"label": "cleanup_created", "kind": "http", "principal": "user1", "checkpoint": "cleanup", "method": "DELETE", "path": collection + "/${created_id}"},
            {"label": "cleanup_control", "kind": "http", "principal": "user1", "checkpoint": "cleanup", "method": "DELETE", "path": collection + "/${control_id}"},
            {"label": "list_after", "kind": "http", "principal": "user1", "checkpoint": "after", "method": "GET", "path": collection, "compare_to": "list_before"},
        ],
        "assertions": [
            {"type": "status_in", "step": "control", "values": [200, 201, 202, 204], "predicate": "benign_control_accepted"},
            {"type": "status_in", "step": "mutate", "values": [200, 201, 202, 204], "predicate": "forbidden_field_accepted"},
            {"type": "comparison_changed", "control": "control_verify", "candidate": "verify", "predicate": "observable_state_change"},
            {"type": "restored", "control": "list_before", "candidate": "list_after", "predicate": "before_after_state"},
        ],
    }


async def _probe_create_surface(
    target_url: str,
    collection_route: str,
    headers: dict[str, str],
    cookies: dict[str, str] | None = None,
    transport: Any = None,
) -> dict[str, Any]:
    """Discover a create body/response shape and immediately clean up the probe object.

    The first accepted create must expose a scalar identifier and its same-principal DELETE must
    succeed. Otherwise probing stops and the workflow is not materialized. This retains autonomous
    schema discovery without silently accumulating registration artifacts.
    """
    import httpx
    from urllib.parse import quote

    try:
        path = agent_tools.validate_same_origin_path(collection_route)
    except agent_tools.AgentToolError:
        return {
            "usable": False,
            "reason": "probe_collection_outside_same_origin_scope",
            "request_count": 0,
            "cleanup_request_count": 0,
            "artifacts": [],
        }
    parsed_path = urllib.parse.urlsplit(path)
    if parsed_path.query or parsed_path.fragment:
        return {
            "usable": False,
            "reason": "probe_collection_must_not_include_query_or_fragment",
            "request_count": 0,
            "cleanup_request_count": 0,
            "artifacts": [],
        }
    path = parsed_path.path
    url = _provision_same_origin_url(target_url, path)
    creds = _create_mass_assignment_credentials()
    candidate_bodies = [
        {"email": creds["ctrl_login"], "password": creds["reg_cred"], "passwordRepeat": creds["reg_cred"]},
        {"email": creds["ctrl_login"], "password": creds["reg_cred"]},
        {"username": creds["ctrl_login"], "email": creds["ctrl_login"], "password": creds["reg_cred"]},
    ]
    safe_headers = {k: v for k, v in (headers or {}).items() if k.lower() == "authorization"}
    request_count = 0
    cleanup_request_count = 0
    artifacts: list[dict[str, Any]] = []
    try:
        async with httpx.AsyncClient(
            timeout=12,
            trust_env=False,
            follow_redirects=False,
            transport=transport,
            cookies=cookies or {},
        ) as client:
            for body in candidate_bodies:
                try:
                    request_count += 1
                    resp = await client.post(
                        url,
                        json=body,
                        headers=safe_headers,
                    )
                except httpx.HTTPError:
                    continue
                if resp.status_code not in (200, 201, 202, 204):
                    continue
                try:
                    response_json = resp.json()
                    shape = _discover_create_object_shape(response_json)
                except (ValueError, TypeError):
                    response_json = None
                    shape = None
                if not shape:
                    # A 2xx create with no id-bearing body (an empty 204, or a registration that echoes
                    # no identifier) still created a real object -- we must not silently walk away and
                    # leave it behind. Best-effort cleanup: RFC-7231 says a 201's Location header points
                    # at the created resource, so DELETE that when it is same-origin. Whatever the
                    # outcome, record the residual (login hash + status) as an artifact so an uncleaned
                    # object is visible in telemetry rather than silent.
                    residual = {
                        "login_sha256": hashlib.sha256(str(creds["ctrl_login"]).encode()).hexdigest(),
                        "create_status": resp.status_code,
                        "cleanup_attempted": False,
                        "cleanup_succeeded": False,
                    }
                    location = resp.headers.get("location")
                    if location:
                        joined = urllib.parse.urljoin(url, location)
                        if (
                            urllib.parse.urlsplit(joined)[:2]
                            == urllib.parse.urlsplit(target_url)[:2]
                            and urllib.parse.urlsplit(joined).path.startswith("/")
                        ):
                            residual["cleanup_attempted"] = True
                            try:
                                cleanup_request_count += 1
                                cleanup = await client.delete(joined, headers=safe_headers)
                                residual["cleanup_status"] = cleanup.status_code
                                residual["cleanup_succeeded"] = cleanup.status_code in (200, 202, 204)
                            except httpx.HTTPError:
                                residual["cleanup_status"] = None
                    artifacts.append(residual)
                    return {
                        "usable": False,
                        "reason": (
                            "accepted_probe_missing_trackable_id_residual_cleaned"
                            if residual["cleanup_succeeded"]
                            else "accepted_probe_missing_trackable_id_residual_uncleaned"
                        ),
                        "request_count": request_count,
                        "cleanup_request_count": cleanup_request_count,
                        "artifacts": artifacts,
                    }
                envelope, id_field = shape
                created_object = (
                    response_json.get(envelope)
                    if envelope and isinstance(response_json, dict)
                    else response_json
                )
                created_id = (
                    created_object.get(id_field)
                    if isinstance(created_object, dict)
                    else None
                )
                if created_id in (None, "") or isinstance(created_id, (dict, list)):
                    return {
                        "usable": False,
                        "reason": "accepted_probe_identifier_invalid",
                        "request_count": request_count,
                        "cleanup_request_count": cleanup_request_count,
                        "artifacts": artifacts,
                    }
                artifact = {
                    "id_sha256": hashlib.sha256(str(created_id).encode()).hexdigest(),
                    "cleanup_attempted": True,
                    "cleanup_succeeded": False,
                }
                artifacts.append(artifact)
                cleanup_url = _provision_same_origin_url(
                    target_url,
                    path.rstrip("/") + "/" + quote(str(created_id), safe=""),
                )
                try:
                    cleanup_request_count += 1
                    cleanup = await client.delete(
                        cleanup_url,
                        headers=safe_headers,
                    )
                    artifact["cleanup_status"] = cleanup.status_code
                    artifact["cleanup_succeeded"] = cleanup.status_code in (200, 202, 204)
                except httpx.HTTPError:
                    artifact["cleanup_status"] = None
                if not artifact["cleanup_succeeded"]:
                    return {
                        "usable": False,
                        "reason": "probe_cleanup_unconfirmed",
                        "request_count": request_count,
                        "cleanup_request_count": cleanup_request_count,
                        "artifacts": artifacts,
                    }
                return {
                    "usable": True,
                    "request_fields": ",".join(body.keys()),
                    "envelope": envelope,
                    "id_field": id_field,
                    "request_count": request_count,
                    "cleanup_request_count": cleanup_request_count,
                    "artifacts": artifacts,
                }
    except Exception:
        logger.warning("create-surface probe failed for %s", path, exc_info=True)
        return {
            "usable": False,
            "reason": "probe_runtime_error",
            "request_count": request_count,
            "cleanup_request_count": cleanup_request_count,
            "artifacts": artifacts,
        }
    return {
        "usable": False,
        "reason": "no_create_candidate_accepted",
        "request_count": request_count,
        "cleanup_request_count": cleanup_request_count,
        "artifacts": artifacts,
    }


async def _server_materialize_create_ma(
    conn: Any,
    target_url: str,
    target_uuid: uuid.UUID,
    params: dict[str, Any],
    hypothesis_id: str | None,
    approval_receipt_id: str | None = None,
) -> bool:
    """When a create-based mass_assignment lead is dispatched WITHOUT a planner-supplied workflow, the
    server discovers the real create body (active probe) and materializes the workflow itself, so the
    planner only has to SELECT the lead. Respects a planner-supplied workflow (does nothing if steps are
    present). Returns True if it materialized. Backstopped end-to-end by the family proof."""
    if params.get("steps") or not hypothesis_id:
        return False
    hypothesis_uuid = _optional_uuid(hypothesis_id)
    if not hypothesis_uuid:
        return False
    row = await conn.fetchrow(
        "SELECT family, metadata_json FROM hypotheses WHERE id=$1 AND target_id=$2",
        hypothesis_uuid, target_uuid,
    )
    if not row or family_proof.canonical_family(row.get("family")) != "mass_assignment":
        return False
    metadata = _decode_json_value(row.get("metadata_json")) or {}
    collection = str(metadata.get("route") or "").strip()
    if not metadata.get("create_based") or not collection:
        return False
    cleanup_rows = await conn.fetch(
        """
        SELECT path FROM target_endpoints
        WHERE target_id=$1 AND upper(method)='DELETE' AND COALESCE(test_status, '') <> 'gone'
        """,
        target_uuid,
    )
    expected_cleanup_route = (
        (_canonical_vulnerability_route(collection) or "").rstrip("/") + "/{id}"
    )
    if not any(
        _canonical_vulnerability_route(row.get("path")) == expected_cleanup_route
        for row in cleanup_rows
    ):
        params["_server_materialization"] = {
            "usable": False,
            "reason": "cleanup_route_not_on_discovered_surface",
            "request_count": 0,
            "cleanup_request_count": 0,
            "artifacts": [],
        }
        return False
    try:
        contexts = await _resolve_workflow_principal_contexts(conn, target_uuid, {"user1"})
    except WorkflowContractError:
        # Do not mutate anonymously and only then discover the credential-bound workflow is invalid.
        return False
    context = contexts.get("user1") if isinstance(contexts.get("user1"), dict) else {}
    started_at = datetime.now(timezone.utc)
    probe = await _probe_create_surface(
        target_url,
        collection,
        context.get("headers") or {},
        context.get("cookies") or {},
    )
    materialization = {
        "usable": bool(probe.get("usable")),
        "reason": probe.get("reason"),
        "request_count": int(probe.get("request_count") or 0),
        "cleanup_request_count": int(probe.get("cleanup_request_count") or 0),
        "artifacts": probe.get("artifacts") or [],
    }
    if materialization["request_count"]:
        receipt_result = await _record_tool_receipt(conn, ToolReceiptRequest(
            tool_name="experiment.create_surface_probe",
            adapter_version="2026-07-18.v1",
            redacted_argv=[
                "experiment.create_surface_probe",
                str(target_uuid),
                _canonical_vulnerability_route(collection) or "/",
            ],
            target_scope={
                "target_id": str(target_uuid),
                "target_url": target_url,
                "same_origin_only": True,
            },
            approval_receipt_id=approval_receipt_id,
            status="success" if materialization["usable"] else "failed",
            parser_status="parsed",
            started_at=started_at.isoformat(),
            finished_at=datetime.now(timezone.utc).isoformat(),
            redaction_summary="Managed credentials stayed in memory; artifact identifiers are hashed.",
            metadata_json=materialization,
            created_by="research_create_surface_probe",
        ))
        materialization["tool_receipt_id"] = (
            receipt_result.get("tool_receipt") or {}
        ).get("id")
    params["_server_materialization"] = materialization
    if not probe.get("usable"):
        return False
    # role=admin is the dominant privilege-escalation overpost; a wrong field is falsified by the proof.
    workflow = _materialize_create_mass_assignment_workflow(
        collection_route=collection, request_fields=probe["request_fields"],
        forbidden_field="role", forbidden_value="admin",
        envelope=probe["envelope"], id_field=probe["id_field"],
    )
    if not workflow:
        materialization["usable"] = False
        materialization["reason"] = "discovered_shape_not_materializable"
        return False
    for key in ("proof_family", "objective", "expected_signal", "falsifier",
                "principal_variables", "assertions", "steps"):
        params[key] = workflow[key]
    return True
















async def _mark_research_model_budget_exhausted(
    conn,
    *,
    episode_id: str,
    observation_id: str,
    summary: str,
    details: dict[str, Any],
) -> bool:
    """End only the still-current planner turn without fabricating model spend."""
    row = await conn.fetchrow(
        """
        UPDATE research_episodes
        SET status='budget_exhausted', stop_reason='model_token_budget_exhausted',
            autopilot_enabled=false, updated_at=NOW()
        WHERE id=$1 AND status='awaiting_planner' AND cancel_requested=false
          AND current_observation_id=$2
        RETURNING id
        """,
        _uuid_or_400(episode_id, "episode id"),
        _optional_uuid(observation_id),
    )
    if not row:
        return False
    await _record_research_event(
        conn,
        row["id"],
        event_type="model_budget_exhausted",
        status="budget_exhausted",
        summary=summary,
        observation_id=observation_id,
        details=details,
    )
    return True


async def _record_research_planner_failure(
    conn,
    *,
    episode_id: str,
    observation_id: str,
    error: str,
    failure_meta: dict[str, Any],
    force_budget_exhausted: bool,
) -> dict[str, Any] | None:
    """Persist failed-attempt metering against the still-current observation."""
    row = await conn.fetchrow(
        "SELECT * FROM research_episodes WHERE id=$1 FOR UPDATE",
        _uuid_or_400(episode_id, "episode id"),
    )
    if (
        not row
        or str(row["status"]) != "awaiting_planner"
        or bool(row["cancel_requested"])
        or str(row["current_observation_id"] or "") != observation_id
    ):
        return None
    episode = _public_research_episode_row(row)
    try:
        metered_units = max(0, int(failure_meta.get("planning_units_spent") or 0))
    except (TypeError, ValueError):
        metered_units = 0
    used = _research_normalize_budget_used(episode.get("budget_used") or {})
    used["model_tokens"] += metered_units
    model_limit = int((episode.get("budget_limits") or {}).get("model_tokens") or 0)
    exhausted = force_budget_exhausted or used["model_tokens"] >= model_limit
    status = "budget_exhausted" if exhausted else "awaiting_planner"
    await conn.execute(
        """
        UPDATE research_episodes
        SET status=$2, budget_used=$3::jsonb,
            stop_reason=CASE WHEN $2='budget_exhausted' THEN 'model_token_budget_exhausted' ELSE stop_reason END,
            autopilot_enabled=CASE WHEN $2='budget_exhausted' THEN false ELSE autopilot_enabled END,
            updated_at=NOW()
        WHERE id=$1
        """,
        row["id"],
        status,
        json.dumps(used),
    )
    await _record_research_event(
        conn,
        row["id"],
        event_type="planner_provider_failed",
        status=status,
        summary=(
            "Planner fallback chain reached the episode model budget"
            if exhausted
            else "Planner provider call failed before producing a valid decision"
        ),
        observation_id=observation_id,
        details={
            "error": str(error)[:500],
            "metered_model_units": metered_units,
            "provider": _bounded_research_payload(failure_meta),
        },
    )
    if not exhausted:
        refreshed = await conn.fetchrow("SELECT * FROM research_episodes WHERE id=$1", row["id"])
        await _build_research_observation(
            conn,
            refreshed,
            previous_result={
                "execution_blocked_reason": "planner_provider_failed",
                "result": {
                    "status": "planner_provider_failed",
                    "reason": str(error)[:500],
                    "error_message": str(error)[:500],
                },
            },
            next_status="awaiting_planner",
        )
    return {"status": status, "metered_model_units": metered_units}


async def _plan_research_episode_step(episode_id: str, req: ResearchPlannerStepRequest):
    async with db_pool.acquire() as conn:
        detail = await _research_episode_detail(conn, episode_id)
    episode = detail.get("episode") or {}
    if episode.get("terminal") or episode.get("status") != "awaiting_planner":
        raise HTTPException(status_code=409, detail="Episode is not awaiting a planner decision")
    observation = detail.get("current_observation")
    if not isinstance(observation, dict):
        raise HTTPException(status_code=409, detail="Episode has no current observation")
    settings = _load_effective_ai_settings()
    ai_url = str(settings.get("ai_url") or "").strip()
    ai_key = str(settings.get("ai_api_key") or "").strip()
    ai_model = str(settings.get("ai_model") or "").strip()
    if not ai_url or not ai_key or not ai_model:
        raise HTTPException(status_code=409, detail="Configured AI provider is not ready")
    call_provider = _load_research_ai_provider()
    if not call_provider:
        raise HTTPException(status_code=503, detail="Shared AI provider client is unavailable")
    messages = _research_planner_messages(observation)
    remaining_model_units = int((episode.get("remaining_budget") or {}).get("model_tokens") or 0)
    prompt_bytes = sum(len(str(item.get("content") or "").encode("utf-8")) for item in messages)
    prompt_reservation = max(1, (prompt_bytes + 2) // 3)
    if remaining_model_units <= prompt_reservation + 128:
        async with db_pool.acquire() as conn:
            async with conn.transaction():
                changed = await _mark_research_model_budget_exhausted(
                    conn,
                    episode_id=episode_id,
                    observation_id=str(observation.get("id") or ""),
                    summary="Remaining model budget cannot fit another bounded planner prompt",
                    details={
                        "remaining_model_units": remaining_model_units,
                        "prompt_reservation": prompt_reservation,
                    },
                )
            if not changed:
                raise HTTPException(status_code=409, detail="Planner observation is no longer current")
            detail = await _research_episode_detail(conn, episode_id)
        return {"accepted": False, "planner_call": {"error": "model_token_budget_exhausted"}, **detail}
    observation_pack = observation.get("observation_pack") if isinstance(observation.get("observation_pack"), dict) else {}
    command_names = [
        str(item.get("name") or "")
        for item in observation_pack.get("proposable_commands") or []
        if isinstance(item, dict) and item.get("proposable") and item.get("name")
    ]
    failure_meta: dict[str, Any] = {}
    response, error, latency_ms = await call_provider(
        ai_url=ai_url,
        ai_api_key=ai_key,
        model=ai_model,
        messages=messages,
        timeout_seconds=req.timeout_seconds,
        max_tokens=req.max_tokens,
        temperature=0.1,
        json_schema=_research_decision_json_schema(
            command_names,
            observation_id=str(observation.get("id") or ""),
            context_hash=str(observation.get("context_hash") or ""),
        ),
        fallback_models=settings.get("ai_model_fallback"),
        overall_budget_seconds=req.timeout_seconds,
        response_validator=lambda value: _research_provider_contract_error(value, observation),
        token_budget=remaining_model_units,
        failure_meta_sink=failure_meta,
        use_circuit_breaker=False,
    )
    if error or not isinstance(response, dict):
        error_text = str(error or "invalid response")[:500]
        async with db_pool.acquire() as conn:
            async with conn.transaction():
                failure = await _record_research_planner_failure(
                    conn,
                    episode_id=episode_id,
                    observation_id=str(observation.get("id") or ""),
                    error=error_text,
                    failure_meta=failure_meta,
                    force_budget_exhausted="token budget" in error_text.lower(),
                )
            if not failure:
                raise HTTPException(status_code=409, detail="Planner observation is no longer current")
            if failure["status"] == "budget_exhausted":
                detail = await _research_episode_detail(conn, episode_id)
                return {
                    "accepted": False,
                    "planner_call": {
                        "error": error_text[:300],
                        "provider": _bounded_research_payload(failure_meta),
                    },
                    **detail,
                }
        raise HTTPException(status_code=502, detail=f"Research planner failed: {error_text[:300]}")
    provider_meta = response.pop("_provider_meta", {}) if isinstance(response.get("_provider_meta"), dict) else {}
    output_bytes = len(json.dumps(response, default=str).encode("utf-8"))
    estimated_tokens = max(1, (prompt_bytes + output_bytes + 3) // 4)
    usage = (
        provider_meta.get("usage_units")
        if isinstance(provider_meta.get("usage_units"), dict)
        else provider_meta.get("usage") if isinstance(provider_meta.get("usage"), dict) else {}
    )
    try:
        provider_tokens = max(
            0,
            int(
                provider_meta.get("planning_units_spent")
                or provider_meta.get("token_units_spent")
                or usage.get("total_units")
                or usage.get("total_tokens")
                or 0
            ),
        )
    except (TypeError, ValueError):
        provider_tokens = 0
    model_tokens_used = provider_tokens or estimated_tokens
    bound_response = _bind_research_decision_to_observation(response, observation)
    harness_repairs = bound_response.pop("_harness_repairs", [])
    actual_model = str(provider_meta.get("model_used") or provider_meta.get("model") or ai_model)[:200]
    actual_mode = str(provider_meta.get("mode_used") or provider_meta.get("mode") or "unknown")[:80]
    try:
        decision_req = ResearchDecisionRequest(
            **bound_response,
            planner={
                "kind": "configured_ai",
                "requested_model": ai_model[:200],
                "model": actual_model,
                "provider_mode": actual_mode,
                "provider_kind": str(provider_meta.get("provider_kind") or "unknown")[:80],
                "parse_method": str(provider_meta.get("parse_method") or "unknown")[:80],
                "fallback_index": max(0, int(provider_meta.get("fallback_index") or 0)),
                "mode_index": max(0, int(provider_meta.get("mode_index") or 0)),
                "attempt_index": max(0, int(provider_meta.get("attempt_index") or 0)),
                "finish_reason": str(provider_meta.get("finish_reason") or "")[:80] or None,
                "schema_validated": bool(provider_meta.get("schema_validated")),
                "reasoning_present": bool(provider_meta.get("reasoning_present")),
                "harness_repairs": [str(item)[:100] for item in harness_repairs[:20]],
                "usage": _bounded_research_payload(usage),
                "latency_ms": latency_ms,
                "metering_quality": "provider" if provider_tokens else "estimated",
                "created_by": req.created_by,
            },
            model_tokens_used=model_tokens_used,
            execute=req.execute,
        )
    except ValidationError as exc:
        raise HTTPException(status_code=422, detail={"error": "planner_decision_schema_invalid", "violations": exc.errors()}) from exc
    result = await submit_research_decision(episode_id, decision_req)
    result["planner_call"] = {
        "requested_model": ai_model[:200],
        "model": actual_model,
        "provider_mode": actual_mode,
        "latency_ms": latency_ms,
        "model_tokens": model_tokens_used,
        "metering_quality": "provider" if provider_tokens else "estimated",
        "harness_repairs": harness_repairs,
    }
    return result


async def _release_research_autopilot_lease(
    pool,
    episode_id: str,
    owner: str,
    *,
    error: str | None = None,
) -> None:
    async with pool.acquire() as conn:
        if error:
            row = await conn.fetchrow(
                """
                UPDATE research_episodes
                SET autopilot_error=$3,
                    autopilot_consecutive_failures=autopilot_consecutive_failures+1,
                    autopilot_enabled=CASE WHEN autopilot_consecutive_failures+1 < 3 THEN autopilot_enabled ELSE false END,
                    lease_owner=NULL,
                    lease_expires_at=CASE
                        WHEN autopilot_consecutive_failures+1 < 3 THEN NOW() + make_interval(secs => LEAST(60, 5 * (autopilot_consecutive_failures+1)))
                        ELSE NULL
                    END,
                    updated_at=NOW()
                WHERE id=$1 AND lease_owner=$2
                RETURNING id, autopilot_enabled, autopilot_consecutive_failures
                """,
                uuid.UUID(episode_id), owner, error[:1000],
            )
            if row:
                await _record_research_event(
                    conn,
                    row["id"],
                    event_type="autopilot_error",
                    status="retrying" if row["autopilot_enabled"] else "paused",
                    summary=("Autopilot planner failed; retry scheduled" if row["autopilot_enabled"] else "Autopilot paused after repeated planner failures"),
                    details={"error": error[:500], "consecutive_failures": row["autopilot_consecutive_failures"]},
                )
            return
        await conn.execute(
            """
            UPDATE research_episodes
            SET lease_owner=NULL, lease_expires_at=NULL, autopilot_error=NULL,
                autopilot_consecutive_failures=0,
                autopilot_enabled=CASE
                    WHEN status IN ('awaiting_planner','awaiting_observation') THEN autopilot_enabled
                    ELSE false
                END,
                updated_at=NOW()
            WHERE id=$1 AND lease_owner=$2
            """,
            uuid.UUID(episode_id), owner,
        )


async def _research_lease_heartbeat(
    pool: Any,
    episode_id: str,
    owner: str,
    stop: asyncio.Event,
) -> None:
    """Keep a short lease alive; process death now becomes recoverable in about 30 seconds."""
    while not stop.is_set():
        try:
            await asyncio.wait_for(stop.wait(), timeout=RESEARCH_AUTOPILOT_HEARTBEAT_SECONDS)
            break
        except asyncio.TimeoutError:
            pass
        async with pool.acquire() as conn:
            refreshed = await conn.fetchval(
                """
                UPDATE research_episodes
                SET lease_expires_at=NOW()+make_interval(secs => $3), updated_at=NOW()
                WHERE id=$1 AND lease_owner=$2
                RETURNING id
                """,
                uuid.UUID(episode_id),
                owner,
                RESEARCH_AUTOPILOT_LEASE_SECONDS,
            )
        if not refreshed:
            break


def _research_autopilot_expected_control_race(exc: Exception) -> bool:
    """Operator pause/cancel racing a model call is control flow, not a planner failure."""
    if not isinstance(exc, HTTPException) or int(exc.status_code or 0) != 409:
        return False
    detail = str(exc.detail or "")
    return detail in {
        "Research autopilot was paused before dispatch",
        "Research episode is terminal or cancelled",
    }


RESEARCH_EPISODE_ABANDON_TTL_HOURS = int(os.getenv("RESEARCH_EPISODE_ABANDON_TTL_HOURS", "6") or 6)


async def _reap_abandoned_research_episodes(conn) -> int:
    """Expire episodes stranded in a waiting state with no activity for the abandon TTL — chiefly
    agent-mode (session-driven) episodes whose driving coding-agent session never returned. The
    autopilot runner only advances `autopilot_enabled` episodes, so these never get touched and
    accumulate indefinitely (16 observed, oldest a week old). Conservative TTL (default 6h) so a
    legitimately-slow session is safe. Also GCs old terminal keyless `agent_hunt_runs`.
    (External-audit P2 — stuck episodes / no GC.)"""
    ttl = max(1, RESEARCH_EPISODE_ABANDON_TTL_HOURS)
    # Reap ONLY genuinely-stranded work: agent-mode (autopilot_enabled=false) episodes stuck waiting
    # for a PLANNER/OPERATOR that never returned, whose campaign is not operator-paused. Deliberately
    # EXCLUDE awaiting_observation (that state is blocked on real linked scan/retest work — the
    # stale-dispatch reconciler owns it; cancelling it would orphan a live scan) and autopilot
    # episodes (the runner advances/re-leases them). No hard delete of hunt transcripts — those are
    # run records under the evidence-retention discipline, not reaper-deletable. (External-audit P1/P2.)
    reaped = await conn.fetch(
        """UPDATE research_episodes re
           SET status='cancelled', stop_reason='abandoned_reaper_timeout',
               lease_expires_at=NULL, updated_at=NOW()
           WHERE re.status IN ('awaiting_planner','awaiting_input')
             AND re.autopilot_enabled=false
             AND re.cancel_requested=false
             AND re.updated_at < NOW() - make_interval(hours => $1::int)
             AND NOT EXISTS (
                 SELECT 1 FROM campaigns c WHERE c.id=re.campaign_id AND c.status='paused')
             -- Do NOT reap an OPERATOR-PAUSED episode: autopilot pause sets autopilot_enabled=false
             -- (the same signal as agent-mode), so distinguish a pause via its event trail — skip any
             -- episode whose latest autopilot event is a pause (no later resume). (External-audit P1.)
             AND NOT EXISTS (
                 SELECT 1 FROM research_events ev
                 WHERE ev.episode_id=re.id AND ev.event_type='autopilot_paused'
                   AND ev.created_at > COALESCE(
                       (SELECT max(ev2.created_at) FROM research_events ev2
                        WHERE ev2.episode_id=re.id AND ev2.event_type='autopilot_resumed'),
                       '-infinity'::timestamptz))
           RETURNING id""",
        ttl,
    )
    return len(reaped)


async def _reconcile_stale_research_dispatches(conn) -> int:
    """Fail closed on expired dispatch windows; never replay an uncertain active action."""
    rows = await conn.fetch(
        """
        SELECT re.*, rd.id AS decision_id, rd.command_result_id AS linked_command_result_id,
               rd.policy_result, rd.action,
               recovered.id AS recovered_command_result_id,
               recovered.status AS recovered_command_status,
               recovered.dry_run AS recovered_command_dry_run,
               recovered_scan.id AS recovered_scan_id,
               recovered_scan.status AS recovered_scan_status,
               recovered_scan.job_id AS recovered_scan_job_id,
               recovered_scan.campaign_id AS recovered_scan_campaign_id,
               fv.id AS recovered_retest_id, fv.finding_id AS recovered_finding_id,
               fv.status AS recovered_retest_status
        FROM research_episodes re
        LEFT JOIN research_decisions rd ON rd.id=re.current_decision_id
        LEFT JOIN LATERAL (
            SELECT cr.id, cr.status, cr.dry_run
            FROM command_results cr
            WHERE rd.command_result_id IS NULL
              AND cr.created_by=(
                  'research_episode:' || re.id::text || ':decision:' || rd.id::text
              )
            ORDER BY cr.created_at DESC
            LIMIT 1
        ) recovered ON true
        LEFT JOIN LATERAL (
            SELECT s.id, s.status, s.job_id, s.campaign_id
            FROM scans s
            WHERE rd.command_result_id IS NULL
              AND recovered.id IS NULL
              AND s.options->>'research_dispatch_correlation'=(
                  'research_episode:' || re.id::text || ':decision:' || rd.id::text
              )
            ORDER BY s.created_at DESC
            LIMIT 1
        ) recovered_scan ON true
        LEFT JOIN LATERAL (
            SELECT verification.id, verification.finding_id, verification.status
            FROM finding_verifications verification
            WHERE rd.command_result_id IS NULL
              AND recovered.id IS NULL
              AND recovered_scan.id IS NULL
              AND verification.requested_by=(
                  'research_episode:' || re.id::text || ':decision:' || rd.id::text
              )
            ORDER BY verification.created_at DESC
            LIMIT 1
        ) fv ON true
        WHERE re.status='dispatching'
          AND re.updated_at < NOW() - INTERVAL '5 minutes'
        ORDER BY re.updated_at ASC
        FOR UPDATE OF re SKIP LOCKED
        LIMIT 10
    """
    )
    repaired = 0
    for row in rows:
        receipt_id = row["linked_command_result_id"] or row["recovered_command_result_id"]
        recovered_status = str(row["recovered_command_status"] or "")
        recovered_dry_run = bool(row["recovered_command_dry_run"])
        correlation = f"research_episode:{row['id']}:decision:{row['decision_id']}"
        if not receipt_id and row.get("recovered_scan_id"):
            action = _decode_json_value(row.get("action")) or {}
            command_name = str(action.get("command") or "asm.improve").strip()
            command = _research_command_catalog().get(command_name) or {}
            scan_status = str(row.get("recovered_scan_status") or "unknown")
            receipt_status = (
                "queued" if scan_status in {"pending", "queued"}
                else "running" if scan_status == "running"
                else scan_status
            )
            synthesized = await _record_command_result(
                conn,
                command=command_name,
                status=receipt_status,
                risk_tier=str(command.get("risk_tier") or "active"),
                campaign_id=row.get("recovered_scan_campaign_id"),
                scan_id=row["recovered_scan_id"],
                operator_message="Recovered ASM scan queued by an interrupted research dispatch",
                result_json={
                    "scan_id": str(row["recovered_scan_id"]),
                    "job_id": str(row.get("recovered_scan_job_id") or ""),
                    "status": scan_status,
                    "recovered_from_scan_correlation": True,
                },
                next_action=f"/scans/{row['recovered_scan_id']}",
                created_by=correlation,
            )
            receipt_id = synthesized["id"]
            recovered_status = str(synthesized.get("status") or "")
            recovered_dry_run = bool(synthesized.get("dry_run"))
        if not receipt_id and row["recovered_retest_id"]:
            synthesized = await _record_command_result(
                conn,
                command="finding.retest",
                status=(
                    "retest_scheduled"
                    if str(row["recovered_retest_status"] or "") in {"queued", "running"}
                    else str(row["recovered_retest_status"] or "completed")
                ),
                risk_tier="active",
                finding_ids=[str(row["recovered_finding_id"])],
                operator_message="Recovered finding retest queued by an interrupted research dispatch",
                result_json={
                    "finding_id": str(row["recovered_finding_id"]),
                    "retest_id": str(row["recovered_retest_id"]),
                    "status": str(row["recovered_retest_status"] or "unknown"),
                },
                next_action=f"/findings/{row['recovered_finding_id']}",
                created_by=correlation,
            )
            receipt_id = synthesized["id"]
            recovered_status = str(synthesized.get("status") or "")
            recovered_dry_run = bool(synthesized.get("dry_run"))
        if receipt_id:
            if not row["linked_command_result_id"]:
                policy_result = _decode_json_value(row["policy_result"]) or {}
                settled_cost = dict(policy_result.get("cost_reserved") or {})
                if recovered_dry_run or recovered_status in {
                    "blocked", "approval_required", "failed", "cancelled",
                }:
                    settled_cost["active_actions"] = 0
                    settled_cost["requests"] = 0
                    settled_cost["seconds"] = 0
                recovered_decision_status = (
                    "blocked"
                    if recovered_dry_run or recovered_status in {
                        "blocked", "approval_required", "failed", "cancelled",
                    }
                    else "dispatching"
                )
                used = _research_apply_cost(
                    _decode_json_value(row["budget_used"]) or {},
                    settled_cost,
                )
                next_step = int(row["step_count"] or 0) + 1
                max_steps = int((_decode_json_value(row["budget_limits"]) or {}).get("steps") or 1)
                await conn.execute(
                    """
                    UPDATE research_decisions
                    SET command_result_id=$2, status=$4,
                        policy_result=$3::jsonb, updated_at=NOW()
                    WHERE id=$1 AND command_result_id IS NULL
                    """,
                    row["decision_id"],
                    _optional_uuid(receipt_id),
                    json.dumps({
                        **policy_result,
                        "recovered_dispatch": True,
                        "cost_settled": settled_cost,
                    }),
                    recovered_decision_status,
                )
                await conn.execute(
                    """
                    UPDATE research_episodes
                    SET status='awaiting_observation', step_count=$2,
                        budget_used=$3::jsonb,
                        stop_reason=CASE WHEN $2 >= $4 THEN 'max_steps_reached_without_conclusion' ELSE stop_reason END,
                        lease_owner=NULL, lease_expires_at=NULL,
                        autopilot_error='recovered_expired_dispatch_with_receipt',
                        version=version+1, updated_at=NOW()
                    WHERE id=$1
                    """,
                    row["id"], next_step, json.dumps(used), max_steps,
                )
            else:
                await conn.execute(
                    """
                    UPDATE research_episodes
                    SET status='awaiting_observation', lease_owner=NULL, lease_expires_at=NULL,
                        autopilot_error='recovered_expired_dispatch_with_receipt', updated_at=NOW()
                    WHERE id=$1
                    """,
                    row["id"],
                )
            summary = "Recovered expired dispatch from its durable command receipt"
            status = "awaiting_observation"
        else:
            await conn.execute(
                """
                UPDATE research_episodes
                SET status='blocked', autopilot_enabled=false, lease_owner=NULL,
                    lease_expires_at=NULL, stop_reason='dispatch_outcome_unknown',
                    autopilot_error='dispatch_outcome_unknown_no_replay', updated_at=NOW()
                WHERE id=$1
                """,
                row["id"],
            )
            await conn.execute(
                """
                UPDATE research_decisions
                SET status='blocked', validation_errors=(validation_errors || '["dispatch_outcome_unknown"]'::jsonb),
                    updated_at=NOW()
                WHERE id=$1 AND status='dispatching'
                """,
                row["decision_id"],
            )
            summary = "Blocked expired dispatch with no durable receipt; action was not replayed"
            status = "blocked"
        await _record_research_event(
            conn,
            row["id"],
            event_type="dispatch_reconciled",
            status=status,
            summary=summary,
            decision_id=row["decision_id"],
            command_result_id=receipt_id,
        )
        repaired += 1
    return repaired


def _research_queued_job_ids(redis_client, queue_name: str) -> set[str]:
    queued: set[str] = set()
    for raw in queue_payloads(redis_client, queue_name):
        try:
            payload = json.loads(raw)
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if isinstance(payload, dict) and payload.get("job_id"):
            queued.add(str(payload["job_id"]))
    return queued


RESEARCH_PROCESSING_LEASE_MAX_AGE_SECONDS = 120


def _redis_hash_text(payload: Any) -> dict[str, str]:
    if not isinstance(payload, dict):
        return {}
    result: dict[str, str] = {}
    for raw_key, raw_value in payload.items():
        key = raw_key.decode("utf-8", "replace") if isinstance(raw_key, bytes) else str(raw_key)
        value = raw_value.decode("utf-8", "replace") if isinstance(raw_value, bytes) else str(raw_value)
        result[key] = value
    return result


def _research_fresh_processing_lease(
    metadata: Any,
    *,
    now: datetime | None = None,
    max_age_seconds: int = RESEARCH_PROCESSING_LEASE_MAX_AGE_SECONDS,
) -> bool:
    """Accept only a worker-authored, recent pop/heartbeat marker.

    The API's ordinary ``status=queued`` cache hash is not queue durability: it
    survives a Stream lease, worker crashes, and queue clearing. Workers stamp
    ``processing_lease_at`` immediately after leasing; running jobs also maintain
    ``heartbeat``. Either timestamp is useful only while fresh.
    """
    values = _redis_hash_text(metadata)
    raw_timestamp = values.get("processing_lease_at") or values.get("heartbeat")
    if not raw_timestamp:
        return False
    try:
        parsed = datetime.fromisoformat(raw_timestamp.replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return False
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    current = now or datetime.now(timezone.utc)
    age_seconds = (current - parsed.astimezone(timezone.utc)).total_seconds()
    return -5 <= age_seconds <= max(1, int(max_age_seconds))


def _research_queue_presence(
    redis_client,
    *,
    queue_ids: set[str],
    job_id: str,
    metadata_key: str,
    now: datetime | None = None,
) -> bool | None:
    """Return True for durable/fresh work, False for proven orphan, None if unknown."""
    if not job_id:
        return False
    if job_id in queue_ids:
        return True
    try:
        metadata = redis_client.hgetall(metadata_key)
    except Exception:
        # A partial Redis read cannot prove absence; retry on the next sweep.
        return None
    return _research_fresh_processing_lease(metadata, now=now)


async def _reconcile_unconfirmed_queue_handoffs(conn) -> int:
    """Fail stale two-phase handoffs that died before queue confirmation."""
    rows = await conn.fetch(
        """
        SELECT id, campaign_id
        FROM scans
        WHERE status='pending'
          AND options->>'queue_handoff_confirmed'='false'
          AND created_at < NOW() - INTERVAL '5 minutes'
        ORDER BY created_at ASC
        FOR UPDATE SKIP LOCKED
        LIMIT 25
        """
    )
    repaired = 0
    for row in rows:
        changed = await conn.fetchval(
            """
            UPDATE scans
            SET status='failed', progress=100, current_phase='queue_failed',
                error_message='Queue handoff confirmation remained absent after the recovery deadline; active work was not started.',
                completed_at=NOW()
            WHERE id=$1 AND status='pending'
              AND options->>'queue_handoff_confirmed'='false'
            RETURNING id
            """,
            row["id"],
        )
        if not changed:
            continue
        campaign_id = row.get("campaign_id")
        if campaign_id:
            await conn.execute(
                """
                UPDATE scan_campaigns campaign
                SET status='failed', completed_at=COALESCE(completed_at, NOW()), updated_at=NOW()
                WHERE campaign.id=$1 AND campaign.status='active'
                  AND EXISTS (
                      SELECT 1 FROM scans owner
                      WHERE owner.id=$2 AND owner.campaign_id=campaign.id
                        AND owner.status='failed'
                  )
                  AND NOT EXISTS (
                      SELECT 1 FROM scans other
                      WHERE other.campaign_id=campaign.id AND other.id<>$2
                  )
                """,
                campaign_id,
                row["id"],
            )
        repaired += 1
    return repaired


async def _reconcile_research_orphaned_queue_work(conn) -> int:
    """Fail closed work committed to Postgres but lost before its Redis enqueue."""
    try:
        redis_client = get_redis()
        redis_client.ping()
        scan_queue_ids = _research_queued_job_ids(redis_client, QUEUE_NAME)
        retest_queue_ids = _research_queued_job_ids(redis_client, RETEST_QUEUE_NAME)
    except Exception:
        # Queue visibility is required to prove a job is orphaned.
        return 0

    scan_rows = await conn.fetch(
        """
        SELECT re.id AS episode_id, s.id, s.job_id
        FROM research_episodes re
        JOIN research_decisions rd ON rd.episode_id=re.id
        JOIN command_results cr ON cr.id=rd.command_result_id
        JOIN scans s ON s.id=cr.scan_id
        WHERE re.status='awaiting_observation' AND re.cancel_requested=false
          AND s.status IN ('pending','queued')
          AND s.created_at < NOW() - INTERVAL '5 minutes'
        FOR UPDATE OF s SKIP LOCKED
        LIMIT 25
        """
    )
    retest_rows = await conn.fetch(
        """
        SELECT re.id AS episode_id, fv.id, fv.job_id, fv.finding_id
        FROM research_episodes re
        JOIN research_decisions rd ON rd.episode_id=re.id
        JOIN command_results cr ON cr.id=rd.command_result_id
        JOIN finding_verifications fv ON fv.id::text=cr.result_json->>'retest_id'
        WHERE re.status='awaiting_observation' AND re.cancel_requested=false
          AND fv.status='queued'
          AND fv.created_at < NOW() - INTERVAL '5 minutes'
        FOR UPDATE OF fv SKIP LOCKED
        LIMIT 25
        """
    )
    repaired = 0
    for row in scan_rows:
        job_id = str(row["job_id"] or "")
        presence = _research_queue_presence(
            redis_client,
            queue_ids=scan_queue_ids,
            job_id=job_id,
            metadata_key=f"job:{job_id}",
        )
        if presence is not False:
            continue
        changed = await conn.fetchval(
            """
            UPDATE scans
            SET status='failed', progress=100, current_phase='terminated', completed_at=NOW(),
                error_message='Research dispatch queue handoff was not durable; job was never enqueued.'
            WHERE id=$1 AND status IN ('pending','queued')
            RETURNING id
            """,
            row["id"],
        )
        if changed:
            await _record_research_event(
                conn,
                row["episode_id"],
                event_type="orphaned_queue_work_failed",
                status="failed",
                summary="Marked a scan failed because its durable queue handoff was missing",
                details={"kind": "scan", "scan_id": str(row["id"]), "job_id": job_id},
            )
            repaired += 1
    for row in retest_rows:
        job_id = str(row["job_id"] or "")
        presence = _research_queue_presence(
            redis_client,
            queue_ids=retest_queue_ids,
            job_id=job_id,
            metadata_key=f"retest_job:{job_id}",
        )
        if presence is not False:
            continue
        changed = await conn.fetchval(
            """
            UPDATE finding_verifications
            SET status='failed', result_status='error', verdict='error',
                verdict_reason='Research dispatch queue handoff was not durable; job was never enqueued.',
                error_message='Research dispatch queue handoff missing', completed_at=NOW(), updated_at=NOW()
            WHERE id=$1 AND status='queued'
            RETURNING id
            """,
            row["id"],
        )
        if changed:
            await conn.execute(
                """
                UPDATE findings f
                SET last_verification_status='error', last_verification_verdict='error',
                    last_verified_at=NOW(), updated_at=NOW()
                WHERE f.id=$1
                  AND NOT EXISTS (
                      SELECT 1 FROM finding_verifications active
                      WHERE active.finding_id=f.id AND active.status IN ('queued','running')
                  )
                  AND (
                      SELECT latest.id FROM finding_verifications latest
                      WHERE latest.finding_id=f.id ORDER BY latest.created_at DESC LIMIT 1
                  )=$2
                """,
                row["finding_id"], row["id"],
            )
            await _record_research_event(
                conn,
                row["episode_id"],
                event_type="orphaned_queue_work_failed",
                status="failed",
                summary="Marked a finding retest failed because its durable queue handoff was missing",
                details={"kind": "finding_retest", "retest_id": str(row["id"]), "job_id": job_id},
            )
            repaired += 1
    return repaired


async def research_autopilot_runner(pool) -> None:
    """Durably advance opted-in episodes independent of any browser session.

    A Postgres lease makes the controller safe across API replicas. Episodes with a linked active
    scan or finding retest are left alone until that work settles, then receive exactly one fresh
    result-bearing observation before planning.
    """
    owner = f"api-autopilot:{os.getpid()}:{uuid.uuid4()}"
    last_queue_reconcile_monotonic = 0.0
    last_campaign_reconcile_monotonic = 0.0
    last_episode_reap_monotonic = 0.0
    while True:
        episode_id: str | None = None
        try:
            now_monotonic = time.monotonic()
            if now_monotonic - last_campaign_reconcile_monotonic >= 30.0:
                await _continue_autonomous_research_campaigns()
                last_campaign_reconcile_monotonic = now_monotonic
            async with pool.acquire() as conn:
                async with conn.transaction():
                    await _reconcile_stale_research_dispatches(conn)
                    now_monotonic = time.monotonic()
                    if now_monotonic - last_queue_reconcile_monotonic >= 30.0:
                        await _reconcile_unconfirmed_queue_handoffs(conn)
                        await _reconcile_research_orphaned_queue_work(conn)
                        last_queue_reconcile_monotonic = now_monotonic
                    if now_monotonic - last_episode_reap_monotonic >= 300.0:
                        await _reap_abandoned_research_episodes(conn)
                        last_episode_reap_monotonic = now_monotonic
                row = await conn.fetchrow(
                    """
                    WITH candidate AS (
                        SELECT re.id
                        FROM research_episodes re
                        WHERE re.autopilot_enabled=true
                          AND re.status IN ('awaiting_planner','awaiting_observation')
                          AND re.cancel_requested=false
                          AND (re.lease_expires_at IS NULL OR re.lease_expires_at < NOW())
                          AND NOT EXISTS (
                              SELECT 1
                              FROM research_decisions rd
                              JOIN command_results cr ON cr.id=rd.command_result_id
                              JOIN scans s ON s.id=cr.scan_id
                              WHERE rd.episode_id=re.id AND s.status IN ('pending','queued','running')
                          )
                          AND NOT EXISTS (
                              SELECT 1
                              FROM research_decisions rd
                              JOIN command_results cr ON cr.id=rd.command_result_id
                              JOIN finding_verifications fv ON fv.id::text=cr.result_json->>'retest_id'
                              WHERE rd.episode_id=re.id AND fv.status IN ('queued','running')
                          )
                        ORDER BY re.updated_at ASC
                        FOR UPDATE SKIP LOCKED
                        LIMIT 1
                    )
                    UPDATE research_episodes re
                    SET lease_owner=$1,
                        lease_expires_at=NOW()+make_interval(secs => $2),
                        updated_at=NOW()
                    FROM candidate
                    WHERE re.id=candidate.id
                    RETURNING re.*
                    """,
                    owner,
                    RESEARCH_AUTOPILOT_LEASE_SECONDS,
                )
                if row:
                    episode_id = str(row["id"])
                    should_plan = str(row["status"]) == "awaiting_planner"
                    if str(row["status"]) == "awaiting_observation":
                        async with conn.transaction():
                            locked = await conn.fetchrow(
                                "SELECT * FROM research_episodes WHERE id=$1 FOR UPDATE",
                                row["id"],
                            )
                            if (
                                not locked
                                or str(locked["status"]) != "awaiting_observation"
                                or bool(locked["cancel_requested"])
                                or str(locked["lease_owner"] or "") != owner
                            ):
                                should_plan = False
                            elif await _research_async_work(conn, row["id"], active_only=True):
                                # Work became active after the candidate query; keep waiting.
                                should_plan = False
                            else:
                                settlement = await _settle_research_awaiting_observation(conn, locked)
                                should_plan = settlement.get("next_status") == "awaiting_planner"
            if not episode_id:
                await asyncio.sleep(1.0)
                continue
            if not should_plan:
                await _release_research_autopilot_lease(pool, episode_id, owner)
                continue
            heartbeat_stop = asyncio.Event()
            heartbeat_task = asyncio.create_task(
                _research_lease_heartbeat(pool, episode_id, owner, heartbeat_stop)
            )
            try:
                if _research_episode_uses_agent_loop(row):
                    # Opt-in: drive this episode with the LLM ReAct hunt loop instead of the
                    # menu planner. The existing create-MA/menu path is untouched (this branch
                    # only fires when planner.agent_loop was set at launch).
                    result = await _run_agent_hunt_for_episode(episode_id)
                else:
                    result = await _plan_research_episode_step(
                        episode_id,
                        ResearchPlannerStepRequest(
                            execute=True,
                            # 240s (of a 300s ceiling) so a large reasoning planner finishes the first big
                            # pack with room for one retry after a transient provider connection error; the
                            # full 8000 max_tokens so a filled mass_assignment/BOLA workflow isn't truncated
                            # into a harness-repair/misinferred stop.
                            timeout_seconds=240,
                            max_tokens=8000,
                            created_by="server_autopilot",
                        ),
                    )
            except asyncio.CancelledError:
                heartbeat_stop.set()
                # Graceful shutdown cancels this task and awaits it BEFORE closing the pool (see
                # lifespan), so release the lease we hold here. Otherwise a restarted controller must
                # wait out the ~4-minute lease TTL before it can resume this episode -- the observed
                # multi-minute dead window after an API restart. Shield so the cleanup completes
                # despite the cancellation propagating.
                try:
                    await asyncio.shield(heartbeat_task)
                except Exception:
                    pass
                try:
                    await asyncio.shield(_release_research_autopilot_lease(pool, episode_id, owner))
                except Exception:
                    pass
                raise
            except Exception as exc:
                heartbeat_stop.set()
                await heartbeat_task
                if _research_autopilot_expected_control_race(exc):
                    await _release_research_autopilot_lease(pool, episode_id, owner)
                else:
                    detail = exc.detail if isinstance(exc, HTTPException) else str(exc)
                    error = json.dumps(detail, default=str) if isinstance(detail, (dict, list)) else str(detail)
                    await _release_research_autopilot_lease(pool, episode_id, owner, error=error or type(exc).__name__)
            else:
                heartbeat_stop.set()
                await heartbeat_task
                result_episode = result.get("episode") if isinstance(result, dict) else {}
                if isinstance(result, dict) and result.get("accepted") is False and not (result_episode or {}).get("terminal"):
                    errors = []
                    decisions = result.get("decisions") if isinstance(result.get("decisions"), list) else []
                    if decisions and isinstance(decisions[0], dict):
                        errors = decisions[0].get("validation_errors") or []
                    policy_steering = _research_rejection_is_policy_steering(errors)
                    async with pool.acquire() as conn:
                        episode_row = await conn.fetchrow(
                            "SELECT * FROM research_episodes WHERE id=$1 AND lease_owner=$2",
                            uuid.UUID(episode_id), owner,
                        )
                        if episode_row and str(episode_row["status"]) == "awaiting_planner":
                            await _build_research_observation(
                                conn,
                                episode_row,
                                previous_result={
                                    "planner_rejection": {
                                        "validation_errors": [str(item)[:300] for item in errors[:20]],
                                        "instruction": (
                                            "The deterministic policy excluded this exact action/hypothesis. "
                                            "Choose a different planner-visible hypothesis or semantic dimension."
                                            if policy_steering else
                                            "Choose a named proposable command or provide a valid stop/input decision."
                                        ),
                                    }
                                },
                                next_status="awaiting_planner",
                            )
                            if policy_steering:
                                await _record_research_event(
                                    conn,
                                    episode_row["id"],
                                    event_type="planner_steered",
                                    status="retrying",
                                    summary="Deterministic policy steered the planner to different work",
                                    details={"validation_errors": [str(item)[:300] for item in errors[:20]]},
                                )
                    if policy_steering:
                        await _release_research_autopilot_lease(pool, episode_id, owner)
                    else:
                        await _release_research_autopilot_lease(
                            pool,
                            episode_id,
                            owner,
                            error=f"planner_decision_rejected:{','.join(str(item) for item in errors)[:800]}",
                        )
                else:
                    await _release_research_autopilot_lease(pool, episode_id, owner)
        except asyncio.CancelledError:
            raise
        except Exception:
            if episode_id:
                try:
                    await _release_research_autopilot_lease(pool, episode_id, owner, error="autopilot_controller_error")
                except Exception:
                    pass
            await asyncio.sleep(2.0)


@app.post("/research/episodes/{episode_id}/plan-step")
async def plan_research_episode_step(episode_id: str, req: ResearchPlannerStepRequest):
    owner = f"manual-planner:{os.getpid()}:{uuid.uuid4()}"
    async with db_pool.acquire() as conn:
        claimed = await conn.fetchval(
            """
            UPDATE research_episodes
            SET lease_owner=$2,
                lease_expires_at=NOW()+make_interval(secs => $3),
                updated_at=NOW()
            WHERE id=$1 AND status='awaiting_planner'
              AND (lease_expires_at IS NULL OR lease_expires_at < NOW())
            RETURNING id
            """,
            _uuid_or_400(episode_id, "episode id"), owner, RESEARCH_AUTOPILOT_LEASE_SECONDS,
        )
    if not claimed:
        raise HTTPException(status_code=409, detail="Episode planner is already running or not ready")
    heartbeat_stop = asyncio.Event()
    heartbeat_task = asyncio.create_task(
        _research_lease_heartbeat(db_pool, episode_id, owner, heartbeat_stop)
    )
    try:
        return await _plan_research_episode_step(episode_id, req)
    finally:
        heartbeat_stop.set()
        await heartbeat_task
        async with db_pool.acquire() as conn:
            await conn.execute(
                "UPDATE research_episodes SET lease_owner=NULL, lease_expires_at=NULL WHERE id=$1 AND lease_owner=$2",
                _uuid_or_400(episode_id, "episode id"), owner,
            )


@app.put("/research/episodes/{episode_id}/autopilot")
async def set_research_episode_autopilot(episode_id: str, req: ResearchAutopilotRequest):
    episode_uuid = _uuid_or_400(episode_id, "episode id")
    async with db_pool.acquire() as conn:
        async with conn.transaction():
            row = await conn.fetchrow("SELECT * FROM research_episodes WHERE id=$1 FOR UPDATE", episode_uuid)
            if not row:
                raise HTTPException(status_code=404, detail="Research episode not found")
            current_mode = _research_episode_planner_mode(row)
            planner_mode = str(req.planner_mode or ("configured_ai" if req.enabled else current_mode))
            if req.enabled and planner_mode != "configured_ai":
                raise HTTPException(
                    status_code=400,
                    detail="Only configured_ai uses server autopilot; agent planners submit decisions directly",
                )
            if req.enabled and not _research_configured_planner_ready():
                raise HTTPException(
                    status_code=409,
                    detail="Stored-provider planning cannot resume until AI settings are configured",
                )
            if req.enabled and str(row["status"]) not in {"awaiting_planner", "awaiting_observation"}:
                raise HTTPException(status_code=409, detail="Only a planning/waiting episode can resume autopilot")
            if req.enabled and row.get("lease_owner") and row.get("lease_expires_at"):
                lease_active = await conn.fetchval("SELECT $1::timestamptz > NOW()", row["lease_expires_at"])
                if lease_active:
                    raise HTTPException(status_code=409, detail="Episode planner is already active")
            updated = await conn.fetchrow(
                """
                UPDATE research_episodes
                SET autopilot_enabled=$2,
                    planner=jsonb_set(
                        jsonb_set(planner, '{mode}', to_jsonb($3::text), true),
                        '{kind}', to_jsonb($4::text), true
                    ),
                    autopilot_error=CASE WHEN $2 THEN NULL ELSE autopilot_error END,
                    autopilot_consecutive_failures=CASE WHEN $2 THEN 0 ELSE autopilot_consecutive_failures END,
                    lease_owner=CASE
                        WHEN $2 AND (lease_expires_at IS NULL OR lease_expires_at < NOW()) THEN NULL
                        ELSE lease_owner
                    END,
                    lease_expires_at=CASE
                        WHEN $2 AND (lease_expires_at IS NULL OR lease_expires_at < NOW()) THEN NULL
                        ELSE lease_expires_at
                    END,
                    updated_at=NOW()
                WHERE id=$1
                RETURNING *
                """,
                episode_uuid, req.enabled, planner_mode, _research_planner_kind(planner_mode),
            )
            if row.get("campaign_id") and req.planner_mode:
                await conn.execute(
                    """
                    UPDATE campaigns
                    SET planner=jsonb_set(
                            jsonb_set(planner, '{mode}', to_jsonb($2::text), true),
                            '{kind}', to_jsonb($3::text), true
                        ),
                        metadata_json=jsonb_set(
                            metadata_json,
                            '{autonomous_research,planner_mode}',
                            to_jsonb($2::text),
                            true
                        ),
                        updated_at=NOW()
                    WHERE id=$1 AND campaign_type='autonomous_research'
                    """,
                    row["campaign_id"], planner_mode, _research_planner_kind(planner_mode),
                )
            await _record_research_event(
                conn,
                episode_uuid,
                event_type="autopilot_resumed" if req.enabled else "autopilot_paused",
                status=str(updated["status"]) if req.enabled else "paused",
                summary="Server autopilot resumed" if req.enabled else "Server autopilot paused by operator",
                details={"created_by": req.created_by, "planner_mode": planner_mode},
            )
            return await _research_episode_detail(conn, str(updated["id"]))












def _ai_ops_execute_enabled() -> bool:
    # First-run installs should be able to launch Deep Hunt without a hidden
    # environment prerequisite. Execution is still bounded by per-operation
    # confirmations, target-scoped approval receipts, and the server-side
    # scope/budget/proof gates. Operators can set the flag to false to disable
    # every gated AI Operations execution path globally.
    return str(os.environ.get("AI_OPS_ROUTER_EXECUTE_ENABLED", "true")).strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }














async def _asm_active_scan_count(conn, target_id: str) -> int:
    return int(await conn.fetchval(
        """
        SELECT COUNT(*) FROM scans
        WHERE target_id = $1 AND status IN ('pending', 'queued', 'running')
        """,
        uuid.UUID(target_id),
    ) or 0)






async def _persist_asm_decision(
    conn,
    target_id: str | uuid.UUID,
    decision: dict[str, Any],
    *,
    source: str,
    active_scan_ids: list[str] | None = None,
) -> None:
    public = _public_asm_decision(decision) or {}
    public["source"] = source
    public["recorded_at"] = utc_now_iso()
    if active_scan_ids:
        public["active_scan_id"] = active_scan_ids[0]
        public["active_scan_ids"] = active_scan_ids
    await conn.execute(
        """
        UPDATE targets
        SET metadata_json = jsonb_set(
                COALESCE(metadata_json, '{}'::jsonb),
                '{asm_last_decision}',
                $1::jsonb,
                true
            ),
            updated_at = NOW()
        WHERE id = $2
        """,
        json.dumps(public),
        uuid.UUID(str(target_id)),
    )









































